import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Product {
  id: string;
  name: string;
  stock: number;
  price: number;
  created_at: string;
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  created_at: string;
}

export interface Sale {
  id: string;
  customer_id: string;
  product_id: string;
  amount: number;
  value: number;
  created_at: string;
  customer?: Customer;
  product?: Product;
}

export interface DashboardStats {
  totalRevenue: number;
  totalSales: number;
  lowStockItems: Product[];
}

import { createClient } from '@supabase/supabase-js';

// These should be configured in Vercel environment variables
const supabaseUrl = (import.meta as any).env?.VITE_SUPABASE_URL || '';
const supabaseAnonKey = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY || '';

export const supabase = createClient(supabaseUrl, supabaseAnonKey);

// Utility to check if Supabase is configured
export const isSupabaseConfigured = () => !!supabaseUrl && !!supabaseAnonKey;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  ShoppingCart, 
  Package, 
  Users, 
  LogOut,
  ChevronRight,
  Plus,
  ArrowUpRight,
  TrendingUp,
  AlertTriangle
} from 'lucide-react';
import { isSupabaseConfigured } from './lib/supabase';
import Dashboard from './components/Dashboard';
import Sales from './components/Sales';
import Inventory from './components/Inventory';
import Customers from './components/Customers';
import Login from './components/Login';

enum View {
  Dashboard = 'dashboard',
  Sales = 'sales',
  Inventory = 'inventory',
  Customers = 'customers'
}

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [currentView, setCurrentView] = useState<View>(View.Dashboard);

  useEffect(() => {
    const session = localStorage.getItem('app_session');
    if (session === 'true') {
      setIsAuthenticated(true);
    }
  }, []);

  if (!isAuthenticated) {
    return <Login onLogin={() => setIsAuthenticated(true)} />;
  }

  const renderView = () => {
    switch (currentView) {
      case View.Dashboard: return <Dashboard onNavigate={(v) => setCurrentView(v as View)} />;
      case View.Sales: return <Sales />;
      case View.Inventory: return <Inventory />;
      case View.Customers: return <Customers />;
      default: return <Dashboard onNavigate={(v) => setCurrentView(v as View)} />;
    }
  };

  const NavItem = ({ view, icon: Icon, label }: { view: View, icon: any, label: string }) => (
    <button
      onClick={() => setCurrentView(view)}
      className={`flex flex-col items-center justify-center w-full py-2 transition-colors ${
        currentView === view ? 'text-indigo-600' : 'text-gray-400'
      }`}
    >
      <Icon size={20} className={currentView === view ? 'scale-110' : ''} />
      <span className="text-[10px] mt-1 font-medium">{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col max-w-md mx-auto shadow-xl ring-1 ring-gray-200">
      {/* Header */}
      <header className="bg-white border-b border-gray-100 px-4 py-3 sticky top-0 z-20 flex justify-between items-center">
        <div>
          <h1 className="text-lg font-bold text-gray-900 tracking-tight">
            {currentView === View.Dashboard && 'Olá, Admin 👋'}
            {currentView === View.Sales && 'Vendas Instagram'}
            {currentView === View.Inventory && 'Controle de Estoque'}
            {currentView === View.Customers && 'Meus Clientes'}
          </h1>
          <p className="text-xs text-gray-500 font-medium uppercase tracking-wider">
            Painel de Gestão
          </p>
        </div>
        <button 
          onClick={() => {
            localStorage.removeItem('app_session');
            setIsAuthenticated(false);
          }}
          className="p-2 text-gray-400 hover:text-red-500 transition-colors"
        >
          <LogOut size={20} />
        </button>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto pb-24 px-4 pt-4 no-scrollbar">
        {renderView()}
      </main>

      {/* Bottom Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 px-2 py-1 flex justify-around items-center z-30 max-w-md mx-auto shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
        <NavItem view={View.Dashboard} icon={LayoutDashboard} label="Home" />
        <NavItem view={View.Sales} icon={ShoppingCart} label="Vendas" />
        <NavItem view={View.Inventory} icon={Package} label="Estoque" />
        <NavItem view={View.Customers} icon={Users} label="Clientes" />
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { TrendingUp, ShoppingBag, AlertCircle, ArrowUpRight } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product, Sale } from '../types';

interface DashboardProps {
  onNavigate: (view: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ onNavigate }) => {
  const [stats, setStats] = useState({ revenue: 0, salesCount: 0 });
  const [lowStock, setLowStock] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);

      // Fetch Sales for revenue and count
      const { data: sales } = await supabase.from('sales').select('value');
      if (sales) {
        const total = sales.reduce((acc, sale) => acc + sale.value, 0);
        setStats({ revenue: total, salesCount: sales.length });
      }

      // Fetch Low Stock
      const { data: products } = await supabase
        .from('products')
        .select('*')
        .lt('stock', 3);
      if (products) setLowStock(products);

    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col gap-4 animate-pulse">
        <div className="h-32 bg-gray-200 rounded-2xl w-full"></div>
        <div className="h-32 bg-gray-200 rounded-2xl w-full"></div>
        <div className="h-48 bg-gray-200 rounded-2xl w-full"></div>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Main Stats */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-indigo-600 rounded-2xl p-4 text-white shadow-lg shadow-indigo-100 flex flex-col justify-between">
          <div className="flex justify-between items-start">
            <TrendingUp size={20} className="opacity-80" />
            <span className="text-[10px] font-bold bg-indigo-500 px-2 py-0.5 rounded-full uppercase">Total</span>
          </div>
          <div className="mt-4">
            <p className="text-xs opacity-80 mb-1">Faturamento</p>
            <p className="text-xl font-bold leading-none">R$ {stats.revenue.toLocaleString('pt-BR')}</p>
          </div>
        </div>

        <div className="bg-white border border-gray-100 rounded-2xl p-4 shadow-sm flex flex-col justify-between">
          <div className="flex justify-between items-start">
            <ShoppingBag size={20} className="text-indigo-600" />
            <button 
              onClick={() => onNavigate('sales')}
              className="p-1 hover:bg-gray-50 rounded-full"
            >
              <ArrowUpRight size={14} className="text-gray-400" />
            </button>
          </div>
          <div className="mt-4">
            <p className="text-xs text-gray-500 mb-1">Vendas Totais</p>
            <p className="text-xl font-bold text-gray-900 leading-none">{stats.salesCount}</p>
          </div>
        </div>
      </div>

      {/* Low Stock Alerts */}
      <div className="bg-white border border-gray-100 rounded-2xl overflow-hidden shadow-sm">
        <div className="px-4 py-3 border-b border-gray-50 flex justify-between items-center">
          <h2 className="text-sm font-bold text-gray-900 flex items-center gap-2">
            <AlertCircle size={16} className="text-amber-500" />
            Alerta de Estoque
          </h2>
          <span className="text-[10px] font-bold text-amber-600 bg-amber-50 px-2 py-0.5 rounded-full">
            ABAIXO DE 3
          </span>
        </div>
        <div className="divide-y divide-gray-50">
          {lowStock.length > 0 ? (
            lowStock.map(product => (
              <div key={product.id} className="p-4 flex justify-between items-center">
                <div>
                  <p className="text-sm font-semibold text-gray-900">{product.name}</p>
                  <p className="text-xs text-gray-500">R$ {product.price.toFixed(2)}</p>
                </div>
                <div className="text-right">
                  <p className="text-sm font-bold text-red-600">{product.stock} un</p>
                  <p className="text-[10px] text-gray-400 uppercase">Restantes</p>
                </div>
              </div>
            ))
          ) : (
            <div className="p-8 text-center">
              <p className="text-sm text-gray-400 italic">Tudo sob controle! Nenhum item com estoque baixo.</p>
            </div>
          )}
        </div>
        {lowStock.length > 0 && (
          <button 
            onClick={() => onNavigate('inventory')}
            className="w-full py-3 text-xs font-bold text-indigo-600 bg-indigo-50 hover:bg-indigo-100 transition-colors"
          >
            Ver Inventário Completo
          </button>
        )}
      </div>

      {/* Quick Actions Card */}
      <div className="bg-gradient-to-br from-gray-900 to-gray-800 rounded-2xl p-5 text-white shadow-xl">
        <h3 className="text-sm font-bold mb-1">Acesso Rápido</h3>
        <p className="text-xs text-gray-400 mb-4">Gerencie seu negócio do Instagram</p>
        <div className="grid grid-cols-2 gap-3">
          <button 
            onClick={() => onNavigate('sales')}
            className="bg-white/10 hover:bg-white/20 py-2 px-3 rounded-xl text-xs font-medium flex items-center justify-center gap-2 transition-all"
          >
            <ShoppingBag size={14} /> Nova Venda
          </button>
          <button 
            onClick={() => onNavigate('customers')}
            className="bg-white/10 hover:bg-white/20 py-2 px-3 rounded-xl text-xs font-medium flex items-center justify-center gap-2 transition-all"
          >
            <TrendingUp size={14} /> Clientes
          </button>
        </div>
      </div>
    </div>
  );
