export default Dashboard;

import React, { useState, useEffect } from 'react';
import { Plus, ShoppingCart, User, Package, DollarSign, Calendar, Search } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product, Customer } from '../types';

const Sales: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);

  const [formData, setFormData] = useState({
    customerId: '',
    productId: '',
    value: '',
    amount: '1',
    date: new Date().toISOString().split('T')[0]
  });

  useEffect(() => {
    fetchInitialData();
  }, []);

  const fetchInitialData = async () => {
    const { data: p } = await supabase.from('products').select('*');
    const { data: c } = await supabase.from('customers').select('*');
    if (p) setProducts(p);
    if (c) setCustomers(c);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.customerId || !formData.productId || !formData.value) return;

    setLoading(true);
    try {
      const selectedProduct = products.find(p => p.id === formData.productId);

      // 1. Record Sale
      const { error: saleError } = await supabase.from('sales').insert({
        customer_id: formData.customerId,
        product_id: formData.productId,
        value: parseFloat(formData.value),
        amount: parseInt(formData.amount),
        created_at: formData.date
      });

      if (saleError) throw saleError;

      // 2. Update Inventory
      if (selectedProduct) {
        await supabase
          .from('products')
          .update({ stock: selectedProduct.stock - parseInt(formData.amount) })
          .eq('id', selectedProduct.id);
      }

      alert('Venda registrada com sucesso!');
      setShowForm(false);
      setFormData({
        customerId: '',
        productId: '',
        value: '',
        amount: '1',
        date: new Date().toISOString().split('T')[0]
      });
      fetchInitialData();
    } catch (err) {
      console.error(err);
      alert('Erro ao registrar venda.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center mb-2">
        <h2 className="text-sm font-bold text-gray-500 uppercase tracking-widest">Registrar Movimento</h2>
        <button 
          onClick={() => setShowForm(!showForm)}
          className="bg-indigo-600 text-white p-2 rounded-full shadow-lg hover:scale-105 active:scale-95 transition-all"
        >
          {showForm ? <Search size={20} /> : <Plus size={20} />}
        </button>
      </div>

      {showForm ? (
        <form onSubmit={handleSubmit} className="bg-white rounded-2xl p-5 shadow-sm space-y-4 border border-gray-100 animate-in slide-in-from-bottom-2 duration-300">
          <div className="space-y-4">
            <div>
              <label className="text-xs font-bold text-gray-400 uppercase mb-1 block">Cliente</label>
              <div className="relative">
                <User size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                <select 
                  className="w-full bg-gray-50 border border-gray-100 rounded-xl py-3 pl-10 pr-4 text-sm focus:ring-2 focus:ring-indigo-500 appearance-none"
                  value={formData.customerId}
                  onChange={e => setFormData({...formData, customerId: e.target.value})}
                  required
                >
                  <option value="">Selecionar Cliente</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>
            </div>

            <div>
              <label className="text-xs font-bold text-gray-400 uppercase mb-1 block">Produto</label>
              <div className="relative">
                <Package size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                <select 
                  className="w-full bg-gray-50 border border-gray-100 rounded-xl py-3 pl-10 pr-4 text-sm focus:ring-2 focus:ring-indigo-500 appearance-none"
                  value={formData.productId}
                  onChange={e => {
                    const prod = products.find(p => p.id === e.target.value);
                    setFormData({...formData, productId: e.target.value, value: prod?.price.toString() || ''});
                  }}
                  required
                >
                  <option value="">Selecionar Produto</option>
                  {products.map(p => <option key={p.id} value={p.id}>{p.name} ({p.stock} un)</option>)}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs font-bold text-gray-400 uppercase mb-1 block">Quantidade</label>
                <input 
                  type="number" 
                  className="w-full bg-gray-50 border border-gray-100 rounded-xl py-3 px-4 text-sm focus:ring-2 focus:ring-indigo-500"
                  value={formData.amount}
                  onChange={e => setFormData({...formData, amount: e.target.value})}
                  min="1"
                  required
                />
              </div>
              <div>
                <label className="text-xs font-bold text-gray-400 uppercase mb-1 block">Valor Total</label>
                <div className="relative">
                  <DollarSign size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                  <input 
                    type="number" 
                    step="0.01"
                    className="w-full bg-gray-50 border border-gray-100 rounded-xl py-3 pl-10 pr-4 text-sm focus:ring-2 focus:ring-indigo-500 font-bold text-indigo-600"
                    placeholder="0,00"
                    value={formData.value}
                    onChange={e => setFormData({...formData, value: e.target.value})}
                    required
                  />
                </div>
              </div>
            </div>

            <div>
              <label className="text-xs font-bold text-gray-400 uppercase mb-1 block">Data da Venda</label>
              <div className="relative">
                <Calendar size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                <input 
                  type="date" 
                  className="w-full bg-gray-50 border border-gray-100 rounded-xl py-3 pl-10 pr-4 text-sm focus:ring-2 focus:ring-indigo-500"
                  value={formData.date}
                  onChange={e => setFormData({...formData, date: e.target.value})}
                  required
                />
              </div>
            </div>
          </div>

          <button 
            type="submit" 
            disabled={loading}
            className="w-full bg-indigo-600 text-white py-4 rounded-xl font-bold text-sm shadow-lg shadow-indigo-100 active:scale-95 transition-all disabled:opacity-50"
          >
            {loading ? 'Salvando...' : 'Confirmar Venda'}
          </button>
        </form>
      ) : (
        <div className="bg-white rounded-2xl p-10 shadow-sm border border-gray-100 text-center space-y-4">
          <div className="bg-indigo-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto text-indigo-600">
            <ShoppingCart size={32} />
          </div>
          <h3 className="text-lg font-bold text-gray-900">Histórico de Vendas</h3>
          <p className="text-sm text-gray-500 px-6">Visualize suas vendas recentes do Instagram clicando no botão de busca ou adicione uma nova.</p>
          <button 
            onClick={() => alert('Lista completa de vendas em breve!')}
            className="text-indigo-600 font-bold text-xs uppercase tracking-wider hover:underline"
          >
            Ver Relatório Completo
          </button>
        </div>
      )}
    </div>
  );
};

export default Sales;

import React, { useState, useEffect } from 'react';
import { Package, Search, Plus, Minus, MoreVertical } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const { data } = await supabase
        .from('products')
        .select('*')
        .order('name', { ascending: true });
      if (data) setProducts(data);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const updateStock = async (id: string, delta: number) => {
    const product = products.find(p => p.id === id);
    if (!product) return;

    const newStock = Math.max(0, product.stock + delta);

    // Optimistic update
    setProducts(prev => prev.map(p => p.id === id ? { ...p, stock: newStock } : p));

    try {
      const { error } = await supabase
        .from('products')
        .update({ stock: newStock })
        .eq('id', id);
      if (error) throw error;
    } catch (e) {
      console.error(e);
      // Rollback on error
      fetchProducts();
    }
  };

  const filtered = products.filter(p => 
    p.name.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-4">
      <div className="relative">
        <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
        <input 
          type="text" 
          placeholder="Buscar produto..."
          className="w-full bg-white border border-gray-100 rounded-2xl py-3 pl-10 pr-4 text-sm shadow-sm focus:ring-2 focus:ring-indigo-500"
          value={search}
          onChange={e => setSearch(e.target.value)}
        />
      </div>

      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
        {loading ? (
          <div className="p-8 text-center text-gray-400">Carregando estoque...</div>
        ) : filtered.length > 0 ? (
          <div className="divide-y divide-gray-50">
            {filtered.map(product => (
              <div key={product.id} className="p-4 flex items-center gap-4">
                <div className="w-12 h-12 rounded-xl bg-gray-50 flex items-center justify-center text-indigo-600 flex-shrink-0">
                  <Package size={20} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-bold text-gray-900 truncate">{product.name}</p>
                  <p className="text-xs text-gray-500">R$ {product.price.toLocaleString('pt-BR')}</p>
                </div>
                <div className="flex items-center gap-2">
                  <button 
                    onClick={() => updateStock(product.id, -1)}
                    className="p-1.5 bg-gray-50 rounded-lg text-gray-400 active:bg-red-50 active:text-red-500 transition-colors"
                  >
                    <Minus size={16} />
                  </button>
                  <div className={`min-w-[40px] text-center font-bold text-sm ${product.stock < 3 ? 'text-red-600' : 'text-gray-900'}`}>
                    {product.stock}
                  </div>
                  <button 
                    onClick={() => updateStock(product.id, 1)}
                    className="p-1.5 bg-gray-50 rounded-lg text-gray-400 active:bg-green-50 active:text-green-500 transition-colors"
                  >
                    <Plus size={16} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="p-12 text-center text-gray-400 italic">Nenhum produto encontrado.</div>
        )}
      </div>
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect } from 'react';
import { Users, Search, MessageCircle, Plus, Phone } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Customer } from '../types';

const Customers: React.FC = () => {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchCustomers();
  }, []);

  const fetchCustomers = async () => {
    try {
      setLoading(true);
      const { data } = await supabase.from('customers').select('*').order('name', { ascending: true });
      if (data) setCustomers(data);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const openWhatsApp = (phone: string, name: string) => {
    // Basic phone sanitization
    const cleanPhone = phone.replace(/\D/g, '');
    const message = encodeURIComponent(`Olá ${name}, tudo bem? Estou entrando em contato sobre o seu pedido.`);
    window.open(`https://wa.me/55${cleanPhone}?text=${message}`, '_blank');
  };

  const filtered = customers.filter(c => 
    c.name.toLowerCase().includes(search.toLowerCase()) || 
    c.phone.includes(search)
  );

  return (
    <div className="space-y-4">
      <div className="flex gap-2">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
          <input 
            type="text" 
            placeholder="Nome ou celular..."
            className="w-full bg-white border border-gray-100 rounded-2xl py-3 pl-10 pr-4 text-sm shadow-sm focus:ring-2 focus:ring-indigo-500"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
        <button className="bg-white border border-gray-100 p-3 rounded-2xl text-indigo-600 shadow-sm active:scale-95 transition-all">
