      <span className="text-[10px] mt-1 font-bold uppercase tracking-tighter">{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col max-w-md mx-auto shadow-xl ring-1 ring-gray-200">
      {/* Header */}
      <header className="bg-white border-b border-gray-100 px-4 py-3 sticky top-0 z-20 flex justify-between items-center">
        <div>
          <h1 className="text-lg font-bold text-gray-900 tracking-tight flex items-center gap-2">
            {currentView === View.Dashboard && 'Sensitive Shop 🎀'}
            {currentView === View.Sales && 'Vendas Instagram 👙'}
            {currentView === View.Inventory && 'Estoque de Luxo ✨'}
            {currentView === View.Customers && 'Minhas Clientes 💖'}
          </h1>
          <p className="text-[10px] text-pink-500 font-bold uppercase tracking-[0.2em]">
            Administração Intimista
          </p>
        </div>
        <button 
          onClick={() => {
            localStorage.removeItem('app_session');
            setIsAuthenticated(false);
          }}
          className="p-2 text-gray-400 hover:text-pink-600 transition-colors"
        >
          <LogOut size={20} />
        </button>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto pb-24 px-4 pt-4 no-scrollbar">
        {renderView()}
      </main>

      {/* Bottom Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 px-2 py-2 flex justify-around items-center z-30 max-w-md mx-auto shadow-[0_-4px_10px_rgba(0,0,0,0.03)]">
