        <NavItem view={View.Sales} icon={Heart} label="Vender" />
        <NavItem view={View.Inventory} icon={Sparkles} label="Estoque" />
        <NavItem view={View.Customers} icon={Users} label="Clientes" />
      </nav>
    </div>
