import React, { useState, useEffect } from 'react';
import { Sparkles, Search, Plus, Minus, X, Check } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const [newProduct, setNewProduct] = useState({
    name: '',
    price: '',
    stock: ''
  });

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const { data } = await supabase.from('products').select('*').order('created_at', { ascending: false });
      if (data) setProducts(data);
    } catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const handleAddProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProduct.name || !newProduct.price) return;

    setIsSaving(true);
    try {
      const { error } = await supabase.from('products').insert([{
        name: newProduct.name,
        price: parseFloat(newProduct.price),
        stock: parseInt(newProduct.stock) || 0
      }]);

      if (error) throw error;

      setNewProduct({ name: '', price: '', stock: '' });
      setShowForm(false);
      fetchProducts();
    } catch (e) {
      alert('Erro ao salvar produto.');
    } finally {
      setIsSaving(false);
    }
  };

  const updateStock = async (id: string, delta: number) => {
    const product = products.find(p => p.id === id);
    if (!product) return;
    const newStock = Math.max(0, product.stock + delta);
    setProducts(prev => prev.map(p => p.id === id ? { ...p, stock: newStock } : p));
    try {
      const { error } = await supabase.from('products').update({ stock: newStock }).eq('id', id);
      if (error) throw error;
    } catch (e) { fetchProducts(); }
  };

  const filtered = products.filter(p => p.name.toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="space-y-4">
      {/* Search and Add Header */}
      <div className="flex gap-2">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-pink-400" />
          <input 
            type="text" 
            placeholder="Buscar no closet... ✨"
            className="w-full bg-white border border-gray-100 rounded-3xl py-4 pl-12 pr-4 text-sm shadow-sm focus:ring-2 focus:ring-pink-500 transition-all font-medium outline-none"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
        <button 
          onClick={() => setShowForm(!showForm)}
          className={`p-4 rounded-3xl shadow-lg transition-all active:scale-95 ${showForm ? 'bg-gray-800 text-white' : 'bg-pink-600 text-white shadow-pink-100'}`}
        >
          {showForm ? <X size={22} /> : <Plus size={22} />}
        </button>
      </div>

      {/* New Product Form */}
      {showForm && (
        <form onSubmit={handleAddProduct} className="bg-white border-2 border-pink-100 rounded-[2rem] p-6 shadow-xl animate-in fade-in slide-in-from-top-4 duration-300 space-y-4">
          <h3 className="text-sm font-black text-pink-600 uppercase tracking-widest flex items-center gap-2">
            <Sparkles size={16} /> Nova Peça de Luxo
          </h3>
          <div className="space-y-3">
            <input 
              type="text" 
              placeholder="Nome da Lingerie (Ex: Conjunto Rubi)"
              className="w-full bg-gray-50 border-2 border-gray-100 rounded-2xl py-3 px-4 text-sm font-bold focus:border-pink-500 outline-none transition-all"
              value={newProduct.name}
              onChange={e => setNewProduct({...newProduct, name: e.target.value})}
              required
            />
            <div className="grid grid-cols-2 gap-3">
              <input 
                type="number" 
                step="0.01"
                placeholder="Preço R$"
                className="w-full bg-gray-50 border-2 border-gray-100 rounded-2xl py-3 px-4 text-sm font-bold focus:border-pink-500 outline-none transition-all"
                value={newProduct.price}
                onChange={e => setNewProduct({...newProduct, price: e.target.value})}
                required
              />
              <input 
                type="number" 
                placeholder="Estoque Inicial"
                className="w-full bg-gray-50 border-2 border-gray-100 rounded-2xl py-3 px-4 text-sm font-bold focus:border-pink-500 outline-none transition-all"
                value={newProduct.stock}
                onChange={e => setNewProduct({...newProduct, stock: e.target.value})}
                required
              />
            </div>
          </div>
          <button 
            type="submit" 
            disabled={isSaving}
            className="w-full bg-pink-600 text-white py-4 rounded-2xl font-black text-sm shadow-lg shadow-pink-100 flex items-center justify-center gap-2 active:scale-95 transition-all disabled:opacity-50"
          >
            {isSaving ? 'Salvando...' : <><Check size={18} /> Cadastrar no Closet</>}
          </button>
        </form>
      )}

      {/* Product List */}
      <div className="bg-white rounded-[2rem] border border-gray-100 shadow-sm overflow-hidden mb-6">
        {loading ? (
          <div className="p-12 text-center text-gray-400 font-medium animate-pulse">Organizando as gavetas... 👙</div>
        ) : filtered.length > 0 ? (
          <div className="divide-y divide-gray-50">
            {filtered.map(product => (
              <div key={product.id} className="p-4 flex items-center gap-4 hover:bg-pink-50/10 transition-colors">
                <div className="w-14 h-14 rounded-2xl bg-pink-50 flex items-center justify-center text-pink-500 flex-shrink-0 shadow-inner">
                  <Sparkles size={24} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-black text-gray-900 truncate">{product.name}</p>
                  <p className="text-[11px] text-pink-600 font-bold uppercase tracking-wider">R$ {Number(product.price).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                </div>
                <div className="flex items-center gap-2 bg-gray-50 p-1 rounded-xl border border-gray-100">
                  <button onClick={() => updateStock(product.id, -1)} className="p-1.5 bg-white rounded-lg text-gray-400 shadow-sm active:bg-rose-50 active:text-rose-500 transition-all">
                    <Minus size={16} />
                  </button>
                  <div className={`min-w-[32px] text-center font-black text-base ${product.stock < 3 ? 'text-rose-600' : 'text-gray-900'}`}>
                    {product.stock}
                  </div>
                  <button onClick={() => updateStock(product.id, 1)} className="p-1.5 bg-white rounded-lg text-gray-400 shadow-sm active:bg-pink-50 active:text-pink-500 transition-all">
                    <Plus size={16} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="p-16 text-center text-gray-400 italic font-medium">Closet vazio por aqui. 🎀</div>
        )}
      </div>
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect } from 'react';
