      {/* New Customer Form */}
      {showForm && (
        <form onSubmit={handleAddCustomer} className="bg-white border-2 border-pink-100 rounded-[2rem] p-6 shadow-xl animate-in fade-in slide-in-from-top-4 duration-300 space-y-4">
          <h3 className="text-sm font-black text-pink-600 uppercase tracking-widest flex items-center gap-2">
            <Heart size={16} className="fill-pink-600" /> Nova Diva no Cadastro
          </h3>
          <div className="space-y-3">
