              type="text" 
              placeholder="Nome Completo"
              className="w-full bg-gray-50 border-2 border-gray-100 rounded-2xl py-3 px-4 text-sm font-bold focus:border-pink-500 outline-none transition-all"
              value={newCustomer.name}
              onChange={e => setNewCustomer({...newCustomer, name: e.target.value})}
              required
            />
            <input 
              type="tel" 
              placeholder="WhatsApp (Ex: 11999998888)"
