import { 
  Home, 
  ShoppingBag, 
  Sparkles, 
  Users, 
  LogOut,
  Settings,
  AlertCircle
} from 'lucide-react';
import { isSupabaseConfigured } from './lib/supabase';
import Dashboard from './components/Dashboard';
import Sales from './components/Sales';
import Inventory from './components/Inventory';
import Customers from './components/Customers';
import Login from './components/Login';

enum View {
  Dashboard = 'dashboard',
  Sales = 'sales',
  Inventory = 'inventory',
  Customers = 'customers'
}

const ConfigMissingScreen = () => (
  <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-6 text-center max-w-md mx-auto">
    <div className="bg-gray-100 p-4 rounded-full mb-6 text-gray-900">
      <Settings size={48} className="animate-pulse" />
    </div>
    <h1 className="text-2xl font-bold text-gray-900 mb-4">Configuração Necessária</h1>
    <p className="text-gray-600 mb-8 font-medium">
      Para que o sistema da Sensitive Shop funcione, verifique as variáveis de ambiente:
    </p>
    <div className="bg-white p-4 rounded-2xl border border-gray-200 text-left w-full space-y-3 font-mono text-xs shadow-sm">
      <p className="flex justify-between border-b border-gray-50 pb-2">
        <span className="text-gray-400">Status API</span>
        <span className="text-gray-900 font-bold truncate ml-2">Conectando...</span>
      </p>
    </div>
