      <AlertCircle size={14} className="shrink-0" />
      Credenciais integradas. Verifique sua conexão.
    </p>
  </div>
);

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [currentView, setCurrentView] = useState<View>(View.Dashboard);
  const [configured, setConfigured] = useState<boolean>(true);

  useEffect(() => {
    const isConfigured = isSupabaseConfigured();
    setConfigured(isConfigured);

    if (isConfigured) {
      const session = localStorage.getItem('app_session');
      if (session === 'true') {
        setIsAuthenticated(true);
      }
    }
  }, []);

  if (!configured) {
    return <ConfigMissingScreen />;
  }

  if (!isAuthenticated) {
    return <Login onLogin={() => setIsAuthenticated(true)} />;
  }

  const renderView = () => {
    switch (currentView) {
      case View.Dashboard: return <Dashboard onNavigate={(v) => setCurrentView(v as View)} />;
      case View.Sales: return <Sales />;
      case View.Inventory: return <Inventory />;
      case View.Customers: return <Customers />;
      default: return <Dashboard onNavigate={(v) => setCurrentView(v as View)} />;
    }
  };

  const NavItem = ({ view, icon: Icon, label }: { view: View, icon: any, label: string }) => (
    <button
      onClick={() => setCurrentView(view)}
      className={`flex flex-col items-center justify-center w-full py-2 transition-all ${
        currentView === view ? 'text-gray-900' : 'text-gray-300'
      }`}
    >
      <Icon size={22} className={currentView === view ? 'scale-110' : ''} />
      <span className="text-[10px] mt-1 font-black uppercase tracking-widest">{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen bg-white flex flex-col max-w-md mx-auto shadow-2xl">
      {/* Header */}
      <header className="bg-white border-b border-gray-100 px-6 py-5 sticky top-0 z-20 flex justify-between items-center">
        <div>
          <h1 className="text-xl font-black text-gray-900 tracking-tighter flex items-center gap-2">
            {currentView === View.Dashboard && 'S.'}
            {currentView === View.Sales && 'VENDAS'}
            {currentView === View.Inventory && 'ESTOQUE'}
            {currentView === View.Customers && 'DIVAS'}
            <span className="text-gray-300 font-light ml-1">|</span>
            <span className="text-sm font-bold text-gray-400 tracking-widest uppercase">
              {currentView === View.Dashboard ? 'Início' : currentView}
            </span>
          </h1>
        </div>
        <button 
          onClick={() => {
            localStorage.removeItem('app_session');
            setIsAuthenticated(false);
          }}
          className="p-2 text-gray-300 hover:text-gray-900 transition-colors"
        >
          <LogOut size={18} />
        </button>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto pb-24 px-6 pt-6 no-scrollbar">
        {renderView()}
      </main>

      {/* Bottom Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 px-4 py-3 flex justify-around items-center z-30 max-w-md mx-auto shadow-[0_-10px_30px_rgba(0,0,0,0.02)]">
        <NavItem view={View.Dashboard} icon={Home} label="Home" />
        <NavItem view={View.Sales} icon={ShoppingBag} label="Venda" />
        <NavItem view={View.Inventory} icon={Sparkles} label="Estoque" />
        <NavItem view={View.Customers} icon={Users} label="Divas" />
      </nav>
    </div>
  );
};

export default App;

