import React, { useState, useEffect } from 'react';
import { Sparkles, Search, Plus, Minus, X, Check, AlertCircle } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');

  const [newProduct, setNewProduct] = useState({
    name: '',
    price: '',
    stock: ''
  });

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const { data } = await supabase.from('products').select('*').order('created_at', { ascending: false });
      if (data) setProducts(data);
    } catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const handleAddProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProduct.name || !newProduct.price) return;

    setIsSaving(true);
    setErrorMessage('');

    try {
      // CORREÇÃO: Payload explícito e conversão de tipos
      const payload = {
        name: newProduct.name.trim(),
        price: parseFloat(newProduct.price.replace(',', '.')),
        stock: parseInt(newProduct.stock) || 0
      };

      const { data, error } = await supabase
        .from('products')
        .insert([payload]) // Supabase espera array de objetos
        .select();

      if (error) {
        console.error("Supabase Error Details:", error);
        throw new Error(error.message);
      }

      setNewProduct({ name: '', price: '', stock: '' });
      setShowForm(false);
      fetchProducts();
    } catch (e: any) {
      console.error('Falha ao salvar no banco:', e);
      setErrorMessage(e.message || 'Erro ao salvar. Verifique o console.');
    } finally {
      setIsSaving(false);
    }
  };

  const updateStock = async (id: string, delta: number) => {
    const product = products.find(p => p.id === id);
    if (!product) return;
    const newStock = Math.max(0, product.stock + delta);
    setProducts(prev => prev.map(p => p.id === id ? { ...p, stock: newStock } : p));
    try {
      const { error } = await supabase.from('products').update({ stock: newStock }).eq('id', id);
      if (error) throw error;
    } catch (e) { fetchProducts(); }
  };

  const filtered = products.filter(p => p.name.toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="space-y-6">
      <div className="flex gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-300" />
          <input 
            type="text" 
            placeholder="Pesquisar catálogo..."
            className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-4 pl-14 pr-6 text-sm shadow-sm focus:ring-2 focus:ring-gray-900 transition-all font-bold outline-none"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
        <button 
          onClick={() => setShowForm(!showForm)}
          className={`w-14 h-14 rounded-2xl shadow-xl transition-all active:scale-95 flex items-center justify-center ${showForm ? 'bg-white text-gray-900 border border-gray-100' : 'bg-gray-900 text-white'}`}
        >
          {showForm ? <X size={24} /> : <Plus size={24} />}
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleAddProduct} className="bg-white border border-gray-100 rounded-[2.5rem] p-8 shadow-2xl animate-in fade-in slide-in-from-top-6 duration-300 space-y-6">
          <div className="flex items-center justify-between">
            <h3 className="text-xs font-black text-gray-900 uppercase tracking-[0.3em]">Novo Item</h3>
            <Sparkles size={16} className="text-gray-300" />
          </div>

          <div className="space-y-4">
            <input 
              type="text" 
              placeholder="Nome da Peça"
              className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-4 px-6 text-sm font-bold focus:border-gray-900 outline-none transition-all"
              value={newProduct.name}
              onChange={e => setNewProduct({...newProduct, name: e.target.value})}
              required
            />
            <div className="grid grid-cols-2 gap-4">
              <input 
                type="text" 
                placeholder="Preço (R$)"
                className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-4 px-6 text-sm font-bold focus:border-gray-900 outline-none transition-all"
                value={newProduct.price}
                onChange={e => setNewProduct({...newProduct, price: e.target.value})}
                required
              />
              <input 
                type="number" 
                placeholder="Estoque"
                className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-4 px-6 text-sm font-bold focus:border-gray-900 outline-none transition-all"
                value={newProduct.stock}
                onChange={e => setNewProduct({...newProduct, stock: e.target.value})}
                required
              />
            </div>
          </div>

          {errorMessage && (
            <div className="p-4 bg-red-50 text-red-700 rounded-2xl text-[10px] font-bold flex gap-2 items-center">
              <AlertCircle size={14} /> {errorMessage}
            </div>
          )}

          <button 
            type="submit" 
            disabled={isSaving}
            className="w-full bg-gray-900 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-xl active:scale-95 transition-all disabled:opacity-50"
          >
            {isSaving ? 'Processando...' : 'Adicionar ao Catálogo'}
          </button>
        </form>
      )}

      <div className="bg-white rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden">
        {loading ? (
          <div className="p-16 text-center text-gray-300 text-xs font-black uppercase tracking-widest animate-pulse">Sincronizando Boutique...</div>
        ) : filtered.length > 0 ? (
          <div className="divide-y divide-gray-50">
            {filtered.map(product => (
              <div key={product.id} className="p-6 flex items-center gap-5 hover:bg-gray-50/50 transition-colors">
                <div className="w-16 h-16 rounded-2xl bg-gray-50 flex items-center justify-center text-gray-900 shadow-inner">
                  <Sparkles size={24} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-black text-gray-900 uppercase tracking-tight truncate">{product.name}</p>
                  <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest mt-1">R$ {Number(product.price).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                </div>
                <div className="flex items-center gap-3 bg-white p-1.5 rounded-2xl border border-gray-100 shadow-sm">
                  <button onClick={() => updateStock(product.id, -1)} className="w-8 h-8 flex items-center justify-center bg-gray-50 rounded-xl text-gray-400 active:bg-gray-900 active:text-white transition-all">
                    <Minus size={14} />
                  </button>
                  <div className={`min-w-[30px] text-center font-black text-sm ${product.stock < 3 ? 'text-red-600' : 'text-gray-900'}`}>
                    {product.stock}
                  </div>
                  <button onClick={() => updateStock(product.id, 1)} className="w-8 h-8 flex items-center justify-center bg-gray-50 rounded-xl text-gray-400 active:bg-gray-900 active:text-white transition-all">
                    <Plus size={14} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="p-20 text-center text-gray-300 text-[10px] font-black uppercase tracking-[0.3em]">Nenhum item em exibição.</div>
        )}
      </div>
    </div>
  );
};

export default Inventory;

