import React, { useState, useEffect } from 'react';
import { Plus, ShoppingBag, User, Package, DollarSign, Calendar, Search, Check } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product, Customer } from '../types';

const Sales: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);

  const [formData, setFormData] = useState({
    customerId: '',
    productId: '',
    value: '',
    amount: '1',
    date: new Date().toISOString().split('T')[0]
  });

  useEffect(() => {
    fetchInitialData();
  }, []);

  const fetchInitialData = async () => {
    const { data: p } = await supabase.from('products').select('*');
    const { data: c } = await supabase.from('customers').select('*');
    if (p) setProducts(p);
    if (c) setCustomers(c);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.customerId || !formData.productId || !formData.value) return;

    setLoading(true);
    try {
      const selectedProduct = products.find(p => p.id === formData.productId);

      const { error: saleError } = await supabase.from('sales').insert([{
        customer_id: formData.customerId,
        product_id: formData.productId,
        value: parseFloat(formData.value.toString().replace(',', '.')),
        amount: parseInt(formData.amount),
        created_at: formData.date
      }]);

      if (saleError) throw saleError;

      if (selectedProduct) {
        await supabase
          .from('products')
          .update({ stock: selectedProduct.stock - parseInt(formData.amount) })
          .eq('id', selectedProduct.id);
      }

      alert('Movimento registrado com sucesso! ✨');
      setShowForm(false);
      setFormData({
        customerId: '',
        productId: '',
        value: '',
        amount: '1',
        date: new Date().toISOString().split('T')[0]
      });
      fetchInitialData();
    } catch (err) {
      console.error(err);
      alert('Erro ao registrar venda.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center px-2">
        <h2 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em]">Registrar Operação</h2>
        <button 
          onClick={() => setShowForm(!showForm)}
          className={`w-12 h-12 rounded-2xl shadow-xl transition-all active:scale-95 flex items-center justify-center ${showForm ? 'bg-white border border-gray-100 text-gray-900' : 'bg-gray-950 text-white'}`}
        >
          {showForm ? <X size={20} /> : <Plus size={20} />}
        </button>
      </div>

      {showForm ? (
        <form onSubmit={handleSubmit} className="bg-white rounded-[2.5rem] p-8 shadow-2xl space-y-6 border border-gray-50 animate-in slide-in-from-bottom-4 duration-400">
          <div className="space-y-5">
            <div>
              <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block ml-1">Quem comprou?</label>
              <div className="relative">
                <User size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
                <select 
                  className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-4 pl-12 pr-6 text-xs font-bold focus:ring-2 focus:ring-gray-900 appearance-none outline-none"
                  value={formData.customerId}
                  onChange={e => setFormData({...formData, customerId: e.target.value})}
                  required
                >
                  <option value="">Selecionar Diva</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>
            </div>

            <div>
              <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block ml-1">Peça Escolhida</label>
              <div className="relative">
                <Package size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
                <select 
                  className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-4 pl-12 pr-6 text-xs font-bold focus:ring-2 focus:ring-gray-900 appearance-none outline-none"
                  value={formData.productId}
                  onChange={e => {
                    const prod = products.find(p => p.id === e.target.value);
                    setFormData({...formData, productId: e.target.value, value: prod?.price.toString() || ''});
                  }}
                  required
                >
                  <option value="">Selecionar Peça</option>
                  {products.map(p => <option key={p.id} value={p.id}>{p.name} ({p.stock} un)</option>)}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block ml-1">Qtd</label>
                <input 
                  type="number" 
                  className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-4 px-6 text-xs font-bold focus:ring-2 focus:ring-gray-900 outline-none"
                  value={formData.amount}
                  onChange={e => setFormData({...formData, amount: e.target.value})}
                  min="1"
                  required
                />
              </div>
              <div>
                <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block ml-1">Valor Final</label>
                <div className="relative">
                  <DollarSign size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
                  <input 
                    type="text" 
                    className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-4 pl-12 pr-6 text-xs font-black text-gray-900 outline-none"
                    placeholder="0,00"
                    value={formData.value}
                    onChange={e => setFormData({...formData, value: e.target.value})}
                    required
                  />
                </div>
              </div>
            </div>

            <div>
              <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block ml-1">Data</label>
              <div className="relative">
                <Calendar size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
                <input 
                  type="date" 
                  className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-4 pl-12 pr-6 text-xs font-bold focus:ring-2 focus:ring-gray-900 outline-none"
                  value={formData.date}
                  onChange={e => setFormData({...formData, date: e.target.value})}
                  required
                />
              </div>
            </div>
          </div>

          <button 
            type="submit" 
            disabled={loading}
            className="w-full bg-gray-950 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-2xl active:scale-95 transition-all disabled:opacity-50 mt-4"
          >
            {loading ? 'Finalizando...' : 'Confirmar Pedido'}
          </button>
        </form>
      ) : (
        <div className="bg-white rounded-[2.5rem] p-12 shadow-sm border border-gray-50 text-center space-y-6">
          <div className="bg-gray-50 w-20 h-20 rounded-[2rem] flex items-center justify-center mx-auto text-gray-900 shadow-inner">
            <ShoppingBag size={32} />
          </div>
          <div>
            <h3 className="text-sm font-black text-gray-900 uppercase tracking-widest mb-2">Relatório de Vendas</h3>
            <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest px-4 leading-relaxed">Clique no botão superior para registrar um novo pedido do Instagram.</p>
          </div>
          <button 
            onClick={() => alert('Em desenvolvimento ✨')}
            className="text-gray-900 font-black text-[9px] uppercase tracking-[0.3em] hover:opacity-50 transition-all pt-4 border-t border-gray-50 w-full"
          >
            Acessar Histórico Completo
          </button>
        </div>
      )}
    </div>
  );
};

export default Sales;

