import React, { useState, useEffect } from 'react';
import { 
  Home, 
  ShoppingBag, 
  Sparkles, 
  Users, 
  LogOut,
  Settings,
  AlertCircle
} from 'lucide-react';
import { isSupabaseConfigured } from './lib/supabase';
import Dashboard from './components/Dashboard';
import Sales from './components/Sales';
import Inventory from './components/Inventory';
import Customers from './components/Customers';
import Login from './components/Login';

enum View {
  Dashboard = 'dashboard',
  Sales = 'sales',
  Inventory = 'inventory',
  Customers = 'customers'
}

const ConfigMissingScreen = () => (
  <div className="min-h-screen bg-white flex flex-col items-center justify-center p-6 text-center max-w-md mx-auto">
    <div className="text-6xl font-serif-brand font-black mb-8">S.</div>
    <h1 className="text-xl font-bold text-gray-900 mb-2 uppercase tracking-tighter">Erro de Conexão</h1>
    <p className="text-gray-500 mb-8 text-sm leading-relaxed">
      Não conseguimos localizar as tabelas no seu banco de dados. Certifique-se de executar o SQL no painel do Supabase.
    </p>
    <div className="bg-gray-50 p-5 rounded-2xl border border-gray-100 text-left w-full space-y-3 font-mono text-[10px]">
      <p className="flex justify-between border-b border-gray-100 pb-2 italic text-gray-400">
        Status do Banco: <span className="text-red-500 font-bold uppercase">Tabelas não encontradas</span>
      </p>
    </div>
  </div>
);

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [currentView, setCurrentView] = useState<View>(View.Dashboard);
  const [configured, setConfigured] = useState<boolean>(true);

  useEffect(() => {
    const isConfigured = isSupabaseConfigured();
    setConfigured(isConfigured);

    if (isConfigured) {
      const session = localStorage.getItem('app_session');
      if (session === 'true') {
        setIsAuthenticated(true);
      }
    }
  }, []);

  if (!configured) {
    return <ConfigMissingScreen />;
  }

  if (!isAuthenticated) {
    return <Login onLogin={() => setIsAuthenticated(true)} />;
  }

  const renderView = () => {
    switch (currentView) {
      case View.Dashboard: return <Dashboard onNavigate={(v) => setCurrentView(v as View)} />;
      case View.Sales: return <Sales />;
      case View.Inventory: return <Inventory />;
      case View.Customers: return <Customers />;
      default: return <Dashboard onNavigate={(v) => setCurrentView(v as View)} />;
    }
  };

  const NavItem = ({ view, icon: Icon, label }: { view: View, icon: any, label: string }) => (
    <button
      onClick={() => setCurrentView(view)}
      className={`flex flex-col items-center justify-center w-full py-2 transition-all ${
        currentView === view ? 'text-black' : 'text-gray-300'
      }`}
    >
      <Icon size={20} strokeWidth={currentView === view ? 2.5 : 2} />
      <span className="text-[9px] mt-1.5 font-black uppercase tracking-[0.2em]">{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen bg-white flex flex-col max-w-md mx-auto shadow-2xl overflow-x-hidden">
      {/* Header */}
      <header className="bg-white border-b border-gray-50 px-6 py-6 sticky top-0 z-20 flex justify-between items-center">
        <div className="flex items-baseline gap-3">
          <span className="text-3xl font-serif-brand font-black text-black">S.</span>
          <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em] mb-1">
            {currentView === View.Dashboard ? 'Management' : currentView}
          </span>
        </div>
        <button 
          onClick={() => {
            localStorage.removeItem('app_session');
            setIsAuthenticated(false);
          }}
          className="p-2 text-gray-200 hover:text-black transition-colors"
        >
          <LogOut size={18} />
        </button>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto pb-32 px-6 pt-6 no-scrollbar">
        {renderView()}
      </main>

      {/* Bottom Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-50 px-4 py-4 flex justify-around items-center z-30 max-w-md mx-auto shadow-[0_-15px_40px_rgba(0,0,0,0.04)]">
        <NavItem view={View.Dashboard} icon={Home} label="Início" />
        <NavItem view={View.Sales} icon={ShoppingBag} label="Venda" />
        <NavItem view={View.Inventory} icon={Sparkles} label="Estoque" />
        <NavItem view={View.Customers} icon={Users} label="Divas" />
      </nav>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Lock, User, AlertCircle } from 'lucide-react';

interface LoginProps {
  onLogin: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const correctUser = 'admin';
    const correctPassword = (import.meta as any).env?.VITE_APP_PASSWORD || 'admin123';
    if (username === correctUser && password === correctPassword) {
      localStorage.setItem('app_session', 'true');
      onLogin();
    } else {
      setError(true);
      setTimeout(() => setError(false), 2000);
    }
  };

  return (
    <div className="min-h-screen bg-white flex flex-col items-center justify-center p-8 max-w-md mx-auto">
