import React, { useState, useEffect } from 'react';
import { Plus, ShoppingBag, User, Package, DollarSign, Calendar, X } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product, Customer } from '../types';

const Sales: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);

  const [formData, setFormData] = useState({
    customerId: '',
    productId: '',
    value: '',
    amount: '1',
    date: new Date().toISOString().split('T')[0]
  });

  useEffect(() => {
    fetchInitialData();
  }, []);

  const fetchInitialData = async () => {
    try {
      const { data: p } = await supabase.from('products').select('*');
      const { data: c } = await supabase.from('customers').select('*');
      if (p) setProducts(p);
      if (c) setCustomers(c);
    } catch (e) {
      console.error('Erro ao buscar dados para venda:', e);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.customerId || !formData.productId || !formData.value) return;

    setLoading(true);
    try {
      const selectedProduct = products.find(p => p.id === formData.productId);

      const { error: saleError } = await supabase.from('sales').insert([{
        customer_id: formData.customerId,
        product_id: formData.productId,
        value: parseFloat(formData.value.toString().replace(',', '.')),
        amount: parseInt(formData.amount),
        created_at: formData.date
      }]);

      if (saleError) throw saleError;

      if (selectedProduct) {
        await supabase
          .from('products')
          .update({ stock: selectedProduct.stock - parseInt(formData.amount) })
          .eq('id', selectedProduct.id);
      }

      alert('Venda registrada com sucesso! ✨');
      setShowForm(false);
      setFormData({
        customerId: '',
        productId: '',
        value: '',
        amount: '1',
        date: new Date().toISOString().split('T')[0]
      });
      fetchInitialData();
    } catch (err) {
      console.error(err);
      alert('Erro ao registrar venda.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center px-2">
        <h2 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em]">Registrar Operação</h2>
        <button 
          onClick={() => setShowForm(!showForm)}
          className={`w-12 h-12 rounded-2xl shadow-xl transition-all active:scale-95 flex items-center justify-center ${showForm ? 'bg-white border border-gray-100 text-black' : 'bg-black text-white'}`}
        >
          {showForm ? <X size={20} /> : <Plus size={20} />}
        </button>
      </div>

      {showForm ? (
        <form onSubmit={handleSubmit} className="bg-white rounded-[2.5rem] p-8 shadow-2xl space-y-6 border border-gray-50 animate-in slide-in-from-bottom-4 duration-400">
          <div className="space-y-5">
            <div>
              <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block ml-1">Quem comprou?</label>
              <div className="relative">
                <User size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
                <select 
