import React, { useState, useEffect } from 'react';
import { Plus, ShoppingBag, User, Package, DollarSign, Calendar, X, AlertCircle } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product, Customer } from '../types';

const Sales: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);

  const [formData, setFormData] = useState({
    customerId: '',
    productId: '',
    discount: '0',
    amount: '1',
    date: new Date().toISOString().split('T')[0]
  });

  const [calculatedValue, setCalculatedValue] = useState(0);

  useEffect(() => {
    fetchInitialData();
  }, []);

  useEffect(() => {
    const product = products.find(p => p.id === formData.productId);
    if (product) {
      const basePrice = Number(product.price);
      const qty = parseInt(formData.amount) || 0;
      const desc = parseFloat(formData.discount.replace(',', '.')) || 0;
      setCalculatedValue(Math.max(0, (basePrice * qty) - desc));
    } else {
      setCalculatedValue(0);
    }
  }, [formData.productId, formData.amount, formData.discount, products]);

  const fetchInitialData = async () => {
    try {
      const { data: p } = await supabase.from('products').select('*');
      const { data: c } = await supabase.from('customers').select('*');
      if (p) setProducts(p);
      if (c) setCustomers(c);
    } catch (e) {
      console.error('Erro ao buscar dados para venda:', e);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.customerId || !formData.productId) return;

    const selectedProduct = products.find(p => p.id === formData.productId);
    const saleAmount = parseInt(formData.amount);

    if (!selectedProduct) return;

    // Validação de estoque rigorosa
    if (saleAmount > selectedProduct.stock) {
      alert(`⚠️ Estoque Insuficiente! \n\nProduto: ${selectedProduct.name}\nDisponível: ${selectedProduct.stock} unidades\nTentativa de venda: ${saleAmount} unidades`);
      return;
    }

    setLoading(true);
    try {
      const { error: saleError } = await supabase.from('sales').insert([{
        customer_id: formData.customerId,
        product_id: formData.productId,
        value: calculatedValue,
        discount: parseFloat(formData.discount.replace(',', '.')) || 0,
        amount: saleAmount,
        created_at: formData.date
      }]);

      if (saleError) throw saleError;

      // Reduzir estoque
      const { error: stockError } = await supabase
        .from('products')
        .update({ stock: selectedProduct.stock - saleAmount })
        .eq('id', selectedProduct.id);

      if (stockError) throw stockError;

      alert('Venda registrada e estoque atualizado! ✨');
      setShowForm(false);
      setFormData({
        customerId: '',
        productId: '',
        discount: '0',
        amount: '1',
        date: new Date().toISOString().split('T')[0]
      });
      fetchInitialData();
    } catch (err) {
      console.error(err);
      alert('Erro ao registrar venda.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center px-2">
        <h2 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em]">Registrar Operação</h2>
        <button 
          onClick={() => setShowForm(!showForm)}
          className={`w-12 h-12 rounded-2xl shadow-xl transition-all active:scale-95 flex items-center justify-center ${showForm ? 'bg-white border border-gray-100 text-black' : 'bg-black text-white'}`}
        >
          {showForm ? <X size={20} /> : <Plus size={20} />}
        </button>
      </div>

      {showForm ? (
        <form onSubmit={handleSubmit} className="bg-white rounded-[2.5rem] p-8 shadow-2xl space-y-6 border border-gray-50 animate-in slide-in-from-bottom-4 duration-400">
          <div className="space-y-5">
            <div>
              <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block ml-1">Quem comprou?</label>
              <div className="relative">
                <User size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
                <select 
                  className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 pl-12 pr-6 text-xs font-bold focus:ring-2 focus:ring-black appearance-none outline-none text-black"
                  value={formData.customerId}
                  onChange={e => setFormData({...formData, customerId: e.target.value})}
                  required
                >
                  <option value="">Selecionar Diva</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>
            </div>

            <div>
              <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block ml-1">Peça Escolhida</label>
              <div className="relative">
                <Package size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
                <select 
                  className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 pl-12 pr-6 text-xs font-bold focus:ring-2 focus:ring-black appearance-none outline-none text-black"
                  value={formData.productId}
                  onChange={e => setFormData({...formData, productId: e.target.value})}
                  required
                >
                  <option value="">Selecionar Peça</option>
                  {products.map(p => (
                    <option key={p.id} value={p.id} disabled={p.stock <= 0}>
                      {p.name} ({p.stock} un) - R$ {p.price}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block ml-1">Quantidade</label>
                <input 
                  type="number" 
                  className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold focus:ring-2 focus:ring-black outline-none text-black"
                  value={formData.amount}
                  onChange={e => setFormData({...formData, amount: e.target.value})}
                  min="1"
                  required
                />
              </div>
              <div>
                <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block ml-1">Desconto (R$)</label>
                <div className="relative">
                  <DollarSign size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
                  <input 
                    type="text" 
                    className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 pl-12 pr-6 text-xs font-black text-red-500 outline-none"
                    placeholder="0,00"
                    value={formData.discount}
                    onChange={e => setFormData({...formData, discount: e.target.value})}
                  />
                </div>
              </div>
            </div>

            <div className="bg-gray-50 rounded-3xl p-6 border border-gray-100">
              <div className="flex justify-between items-center">
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Valor Final</span>
                <span className="text-2xl font-black text-black">
                  R$ {calculatedValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                </span>
              </div>
            </div>

            <div>
              <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block ml-1">Data</label>
              <div className="relative">
                <Calendar size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
                <input 
                  type="date" 
                  className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 pl-12 pr-6 text-xs font-bold focus:ring-2 focus:ring-black outline-none text-black"
                  value={formData.date}
                  onChange={e => setFormData({...formData, date: e.target.value})}
                  required
                />
              </div>
            </div>
          </div>

          <button 
            type="submit" 
            disabled={loading}
            className="w-full bg-black text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-2xl active:scale-95 transition-all disabled:opacity-50 mt-4"
          >
            {loading ? 'Processando...' : 'Confirmar Venda'}
          </button>
        </form>
      ) : (
        <div className="bg-white rounded-[2.5rem] p-12 shadow-sm border border-gray-50 text-center space-y-6">
          <div className="bg-gray-50 w-20 h-20 rounded-[2rem] flex items-center justify-center mx-auto text-black shadow-inner">
            <ShoppingBag size={32} />
          </div>
          <div>
            <h3 className="text-sm font-black text-black uppercase tracking-widest mb-2">Relatório de Movimento</h3>
            <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest px-4 leading-relaxed">Clique no botão superior para registrar uma nova venda.</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default Sales;

import React, { useState, useEffect } from 'react';
import { Sparkles, Search, Plus, Minus, X, Check, AlertCircle, Edit2, Save } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const [editingPriceId, setEditingPriceId] = useState<string | null>(null);
  const [tempPrice, setTempPrice] = useState('');

  const [newProduct, setNewProduct] = useState({
    name: '',
    price: '',
    stock: '',
    size: '',
    color: ''
  });

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const { data, error } = await supabase.from('products').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) setProducts(data);
    } catch (e) { 
      console.error('Erro ao buscar produtos:', e); 
    } finally { 
      setLoading(false); 
    }
  };

  const handleAddProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProduct.name || !newProduct.price) return;

    setIsSaving(true);
    setErrorMessage('');

    try {
      const payload = {
        name: newProduct.name.trim(),
        price: parseFloat(newProduct.price.replace(',', '.')),
        stock: parseInt(newProduct.stock) || 0,
        size: newProduct.size.trim(),
        color: newProduct.color.trim()
      };

      const { error } = await supabase
        .from('products')
        .insert([payload]);

      if (error) {
        console.error("Erro no Supabase:", error);
        throw new Error(error.message);
      }

      setNewProduct({ name: '', price: '', stock: '', size: '', color: '' });
      setShowForm(false);
      fetchProducts();
    } catch (e: any) {
      setErrorMessage(e.message || 'Erro ao salvar produto.');
    } finally {
      setIsSaving(false);
    }
  };

  const saveNewPrice = async (id: string) => {
    const newPrice = parseFloat(tempPrice.replace(',', '.'));
    if (isNaN(newPrice)) return;

    try {
      const { error } = await supabase.from('products').update({ price: newPrice }).eq('id', id);
      if (error) throw error;
      setEditingPriceId(null);
      fetchProducts();
    } catch (e) {
      console.error('Erro ao atualizar preço:', e);
    }
  };

  const filtered = products.filter(p => p.name.toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="space-y-6">
      <div className="flex gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400" />
          <input 
            type="text" 
            placeholder="Pesquisar catálogo..."
            className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 pl-14 pr-6 text-sm shadow-sm focus:ring-2 focus:ring-black transition-all font-bold outline-none text-black"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
        <button 
          onClick={() => setShowForm(!showForm)}
          className={`w-14 h-14 rounded-2xl shadow-xl transition-all active:scale-95 flex items-center justify-center ${showForm ? 'bg-white text-black border border-gray-200' : 'bg-black text-white'}`}
        >
          {showForm ? <X size={24} /> : <Plus size={24} />}
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleAddProduct} className="bg-white border border-gray-100 rounded-[2.5rem] p-8 shadow-2xl animate-in fade-in slide-in-from-top-6 duration-300 space-y-6">
          <div className="flex items-center justify-between">
            <h3 className="text-xs font-black text-black uppercase tracking-[0.3em]">Novo Cadastro</h3>
            <Sparkles size={16} className="text-gray-300" />
          </div>

          <div className="space-y-4">
            <input 
              type="text" 
              placeholder="Nome da Peça"
              className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-sm font-bold focus:border-black outline-none transition-all text-black"
              value={newProduct.name}
              onChange={e => setNewProduct({...newProduct, name: e.target.value})}
              required
            />

            <div className="grid grid-cols-2 gap-4">
              <input 
                type="text" 
                placeholder="Tamanho (P, M, G, 42...)"
                className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-sm font-bold focus:border-black outline-none transition-all text-black"
                value={newProduct.size}
                onChange={e => setNewProduct({...newProduct, size: e.target.value})}
              />
              <input 
                type="text" 
                placeholder="Cor Predominante"
                className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-sm font-bold focus:border-black outline-none transition-all text-black"
                value={newProduct.color}
                onChange={e => setNewProduct({...newProduct, color: e.target.value})}
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <input 
                type="text" 
                placeholder="Preço de Venda (R$)"
                className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-sm font-bold focus:border-black outline-none transition-all text-black"
                value={newProduct.price}
                onChange={e => setNewProduct({...newProduct, price: e.target.value})}
                required
              />
              <input 
                type="number" 
                placeholder="Qtd em Estoque"
                className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-sm font-bold focus:border-black outline-none transition-all text-black"
