                    )}
                  </div>

                  {editingPriceId === product.id ? (
                    <div className="flex items-center gap-2 mt-1">
                      <input 
                        autoFocus
                        type="text" 
                        className="bg-gray-100 text-[10px] font-black w-20 px-2 py-1 rounded-lg outline-none text-black border border-black"
                        value={tempPrice}
                        onChange={e => setTempPrice(e.target.value)}
                        onBlur={() => setEditingPriceId(null)}
                      />
                      <button onMouseDown={() => saveNewPrice(product.id)} className="text-black">
                        <Save size={14} />
                      </button>
                    </div>
                  ) : (
                    <div className="flex items-center gap-2 mt-1 group">
                      <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">
                        R$ {Number(product.price).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                      </p>
                      <button 
                        onClick={() => {
                          setEditingPriceId(product.id);
                          setTempPrice(product.price.toString());
                        }}
                        className="opacity-0 group-hover:opacity-100 transition-opacity text-gray-300"
                      >
                        <Edit2 size={10} />
                      </button>
                    </div>
                  )}

                  {product.color && (
                    <p className="text-[9px] text-gray-300 font-bold uppercase tracking-widest">{product.color}</p>
                  )}
                </div>
                <div className="text-right shrink-0">
                  <div className="text-[9px] font-black text-gray-300 uppercase tracking-widest mb-1">QTD</div>
                  <div className={`text-sm font-black ${product.stock < 3 ? 'text-red-600' : 'text-black'}`}>
                    {product.stock}
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="p-20 text-center text-gray-300 text-[10px] font-black uppercase tracking-[0.3em]">Nenhum item em exibição.</div>
        )}
      </div>
    </div>
  );
};

export default Inventory;

