};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { Sparkles, Search, Plus, X, Edit2, Save, Tag, Info, DollarSign, Package, Palette, Layers, ArrowRight } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [editingPriceId, setEditingPriceId] = useState<string | null>(null);
  const [tempPrice, setTempPrice] = useState('');

  // Modal State
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);

  const [newProduct, setNewProduct] = useState({
    name: '',
    reference: '',
    purchase_price: '',
    price: '',
    stock: '',
    size: '',
    color: ''
  });

  useEffect(() => { fetchProducts(); }, []);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const { data } = await supabase.from('products').select('*').order('created_at', { ascending: false });
      if (data) setProducts(data);
    } catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const handleAddProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      const { error } = await supabase.from('products').insert([{
        name: newProduct.name.trim(),
        reference_code: newProduct.reference.trim(),
        purchase_price: parseFloat(newProduct.purchase_price.replace(',', '.')),
        price: parseFloat(newProduct.price.replace(',', '.')),
        stock: parseInt(newProduct.stock) || 0,
        size: newProduct.size.trim(),
        color: newProduct.color.trim()
      }]);
      if (error) throw error;
      setNewProduct({ name:'', reference:'', purchase_price:'', price:'', stock:'', size:'', color:'' });
      setShowForm(false);
      fetchProducts();
    } catch (e) { console.error(e); } finally { setIsSaving(false); }
  };

  const saveNewPrice = async (id: string) => {
    const newPrice = parseFloat(tempPrice.replace(',', '.'));
    if (isNaN(newPrice)) return;
    try {
      await supabase.from('products').update({ price: newPrice }).eq('id', id);
      setEditingPriceId(null);
      fetchProducts();
    } catch (e) { console.error(e); }
  };

  const filtered = products.filter(p => 
    p.name.toLowerCase().includes(search.toLowerCase()) || 
    p.reference_code?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-6 relative">
      <div className="flex gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400" />
          <input 
            type="text" 
            placeholder="Buscar por nome ou ref..."
            className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 pl-14 pr-6 text-xs shadow-sm focus:border-black transition-all font-bold outline-none text-black"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
        <button 
          onClick={() => {
            setShowForm(!showForm);
            setSelectedProduct(null);
          }} 
          className={`w-14 h-14 rounded-2xl shadow-xl transition-all flex items-center justify-center ${showForm ? 'bg-white text-black border border-gray-100' : 'bg-black text-white'}`}
        >
          {showForm ? <X size={24} /> : <Plus size={24} />}
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleAddProduct} className="bg-white border border-gray-100 rounded-[2.5rem] p-8 shadow-2xl space-y-5 animate-in slide-in-from-top-4 duration-300">
          <div className="flex items-center justify-between">
            <h3 className="text-[10px] font-black text-black uppercase tracking-[0.3em]">Cadastro Boutique</h3>
            <Tag size={16} className="text-indigo-400" />
          </div>
          <input type="text" placeholder="Nome da Peça" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newProduct.name} onChange={e => setNewProduct({...newProduct, name: e.target.value})} required />
          <div className="grid grid-cols-2 gap-4">
            <input type="text" placeholder="Ref. Interna" className="bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newProduct.reference} onChange={e => setNewProduct({...newProduct, reference: e.target.value})} />
            <input type="number" placeholder="Estoque Inicial" className="bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newProduct.stock} onChange={e => setNewProduct({...newProduct, stock: e.target.value})} required />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <input type="text" placeholder="Custo (Compra)" className="bg-gray-50 border border-indigo-100 rounded-2xl py-4 px-6 text-xs font-bold text-indigo-600 outline-none" value={newProduct.purchase_price} onChange={e => setNewProduct({...newProduct, purchase_price: e.target.value})} required />
            <input type="text" placeholder="Preço (Venda)" className="bg-gray-50 border border-emerald-100 rounded-2xl py-4 px-6 text-xs font-bold text-emerald-600 outline-none" value={newProduct.price} onChange={e => setNewProduct({...newProduct, price: e.target.value})} required />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <input type="text" placeholder="Tamanho" className="bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newProduct.size} onChange={e => setNewProduct({...newProduct, size: e.target.value})} />
            <input type="text" placeholder="Cor" className="bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newProduct.color} onChange={e => setNewProduct({...newProduct, color: e.target.value})} />
          </div>
          <button type="submit" disabled={isSaving} className="w-full bg-black text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-xl disabled:opacity-50">
            {isSaving ? 'Gravando...' : 'Finalizar Cadastro'}
          </button>
        </form>
      )}

      {/* Product List */}
      <div className="bg-white rounded-[2.5rem] border border-gray-50 shadow-sm divide-y divide-gray-50">
        {loading ? (
          <div className="p-20 text-center text-gray-200 text-[10px] font-black uppercase tracking-widest animate-pulse">Consultando Catálogo...</div>
        ) : filtered.map(product => (
          <div 
            key={product.id} 
            onClick={() => setSelectedProduct(product)}
            className="p-6 flex items-center gap-5 hover:bg-gray-50/50 transition-colors cursor-pointer"
          >
            <div className="w-16 h-16 rounded-2xl bg-gray-50 flex items-center justify-center text-black shadow-inner">
              <Sparkles size={24} className="text-gray-300" />
            </div>
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2">
                <p className="text-xs font-black text-black uppercase tracking-tight truncate">{product.name}</p>
                <span className="text-[8px] font-black px-1.5 py-0.5 rounded-md bg-indigo-50 text-indigo-400">{product.size}</span>
              </div>
              <p className="text-[9px] text-gray-300 font-bold uppercase tracking-widest mt-0.5">REF: {product.reference_code || '---'}</p>

              {editingPriceId === product.id ? (
                <div className="flex items-center gap-2 mt-1" onClick={e => e.stopPropagation()}>
                  <input autoFocus type="text" className="bg-gray-100 text-[10px] font-black w-20 px-2 py-1 rounded-lg outline-none text-black" value={tempPrice} onChange={e => setTempPrice(e.target.value)} onBlur={() => setEditingPriceId(null)} />
                  <button onMouseDown={() => saveNewPrice(product.id)} className="text-black"><Save size={14} /></button>
                </div>
              ) : (
                <div className="flex items-center gap-2 mt-1 group">
                  <p className="text-[10px] text-emerald-500 font-black uppercase">R$ {Number(product.price).toFixed(2)}</p>
                  <button 
                    onClick={(e) => { 
                      e.stopPropagation();
                      setEditingPriceId(product.id); 
                      setTempPrice(product.price.toString()); 
                    }} 
                    className="opacity-0 group-hover:opacity-100 transition-opacity text-gray-200"
                  >
                    <Edit2 size={10} />
                  </button>
                </div>
              )}
            </div>
            <div className="text-right">
              <div className="text-[9px] font-black text-gray-300 uppercase tracking-widest">QTD</div>
              <div className={`text-sm font-black ${product.stock < 3 ? 'text-red-500' : 'text-black'}`}>{product.stock}</div>
            </div>
          </div>
        ))}
      </div>

      {/* Product Detail Modal */}
      {selectedProduct && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-6 bg-black/40 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-sm rounded-[3rem] p-8 shadow-2xl space-y-8 animate-in zoom-in-95 duration-300">
            <div className="flex justify-between items-start">
              <div className="space-y-1">
                <p className="text-[10px] font-black text-gray-300 uppercase tracking-widest">Detalhes da Peça</p>
                <h3 className="text-xl font-black text-black uppercase tracking-tight">{selectedProduct.name}</h3>
              </div>
              <button 
                onClick={() => setSelectedProduct(null)}
                className="w-10 h-10 rounded-full bg-gray-50 flex items-center justify-center text-gray-400 hover:bg-black hover:text-white transition-all"
              >
                <X size={18} />
              </button>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="bg-gray-50 p-4 rounded-3xl space-y-1">
                <div className="flex items-center gap-2 text-[9px] font-black text-gray-300 uppercase tracking-widest">
                  <Tag size={12} /> Referência
                </div>
                <p className="text-xs font-black text-black uppercase">{selectedProduct.reference_code || '---'}</p>
              </div>
              <div className="bg-gray-50 p-4 rounded-3xl space-y-1">
                <div className="flex items-center gap-2 text-[9px] font-black text-gray-300 uppercase tracking-widest">
                  <Layers size={12} /> Estoque
                </div>
                <p className={`text-xs font-black ${selectedProduct.stock < 3 ? 'text-red-600' : 'text-black'}`}>{selectedProduct.stock} unidades</p>
              </div>
              <div className="bg-gray-50 p-4 rounded-3xl space-y-1">
                <div className="flex items-center gap-2 text-[9px] font-black text-gray-300 uppercase tracking-widest">
                  <Palette size={12} /> Cor / Tam
                </div>
                <p className="text-xs font-black text-black uppercase">{selectedProduct.color || '-'} / {selectedProduct.size || '-'}</p>
              </div>
              <div className="bg-gray-50 p-4 rounded-3xl space-y-1">
                <div className="flex items-center gap-2 text-[9px] font-black text-gray-300 uppercase tracking-widest">
                  <DollarSign size={12} /> Venda
                </div>
                <p className="text-xs font-black text-emerald-600 uppercase">R$ {Number(selectedProduct.price).toFixed(2)}</p>
              </div>
            </div>

            <div className="p-6 bg-gray-950 rounded-[2rem] text-white space-y-4">
              <div className="flex justify-between items-center opacity-50">
                <span className="text-[9px] font-black uppercase tracking-widest">Custo de Compra</span>
                <span className="text-xs font-bold">R$ {Number(selectedProduct.purchase_price).toFixed(2)}</span>
              </div>
              <div className="h-px bg-white/10"></div>
              <div className="flex justify-between items-center">
                <span className="text-[9px] font-black uppercase tracking-widest">Lucro Estimado</span>
                <span className="text-lg font-black text-emerald-400">R$ {(Number(selectedProduct.price) - Number(selectedProduct.purchase_price)).toFixed(2)}</span>
              </div>
            </div>

            <div className="flex gap-3 pt-2">
              <button 
                onClick={() => setSelectedProduct(null)}
                className="flex-1 bg-gray-50 text-gray-400 py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.3em] active:scale-95 transition-all"
              >
                Fechar
              </button>
              <button 
                onClick={() => {
                  setNewProduct({
                    ...newProduct,
                    name: selectedProduct.name,
                    reference: selectedProduct.reference_code || '',
                    purchase_price: selectedProduct.purchase_price.toString(),
                    price: selectedProduct.price.toString(),
                    stock: '',
                    size: selectedProduct.size || '',
                    color: selectedProduct.color || ''
                  });
                  setSelectedProduct(null);
                  setShowForm(true);
                }}
                className="flex-[1.5] bg-black text-white py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.3em] shadow-xl flex items-center justify-center gap-2 active:scale-95 transition-all"
              >
                Reposição <ArrowRight size={14} />
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect } from 'react';
import { Search, MessageCircle, Plus, Phone, X, UserPlus, AlertCircle, Gift, Mail, Instagram, ChevronRight, ShoppingBag, Calendar, ArrowUpRight } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Customer, Sale } from '../types';

const Customers: React.FC = () => {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
  const [customerSales, setCustomerSales] = useState<Sale[]>([]);

  const [newCustomer, setNewCustomer] = useState({
    name: '',
    phone: '',
    email: '',
    instagram: '',
    birthday: ''
  });

  useEffect(() => { fetchCustomers(); }, []);

  const fetchCustomers = async () => {
    try {
      setLoading(true);
      const { data, error } = await supabase.from('customers').select('*').order('name', { ascending: true });
      if (error) throw error;
      if (data) setCustomers(data);
    } catch (e) { 
      console.error(e); 
    } finally { 
      setLoading(false); 
    }
  };

  const fetchHistory = async (id: string) => {
    if (selectedCustomerId === id) {
      setSelectedCustomerId(null);
      return;
    }
    const { data } = await supabase.from('sales').select('*, product:products(*)').eq('customer_id', id).order('created_at', { ascending: false });
    if (data) setCustomerSales(data);
    setSelectedCustomerId(id);
  };

  const handleAddCustomer = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      const { error } = await supabase.from('customers').insert([{
        name: newCustomer.name.trim(),
        phone: newCustomer.phone.replace(/\D/g, ''),
        email: newCustomer.email.trim(),
        instagram: newCustomer.instagram.trim(),
        birthday: newCustomer.birthday || null
      }]);
      if (error) throw error;
      setNewCustomer({ name: '', phone: '', email: '', instagram: '', birthday: '' });
      setShowForm(false);
      fetchCustomers();
    } catch (e) {
      alert('Erro ao cadastrar cliente.');
    } finally {
      setIsSaving(false);
    }
  };

  const openWhatsApp = (phone: string, name: string, isBirthday: boolean) => {
    const cleanPhone = phone.replace(/\D/g, '');
    const msg = isBirthday 
      ? `Parabéns ${name}! ✨ Notamos que é seu aniversário hoje e preparamos um cupom especial para você na Sensitive Shop! 🎁`
      : `Olá ${name} ✨, temos novidades incríveis na boutique!`;
    window.open(`https://wa.me/55${cleanPhone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const isTodayBirthday = (birthdayStr?: string) => {
    if (!birthdayStr) return false;
    const today = new Date();
    const bday = new Date(birthdayStr);
    return today.getDate() + 1 === bday.getDate() + 1 && today.getMonth() === bday.getMonth();
  };

  const filtered = customers.filter(c => c.name.toLowerCase().includes(search.toLowerCase()) || c.phone.includes(search));

  return (
    <div className="space-y-6">
      <div className="flex gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400" />
          <input 
            type="text" 
            placeholder="Buscar por nome ou celular..."
            className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 pl-14 pr-6 text-sm shadow-sm focus:border-black transition-all font-bold outline-none text-black"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
        <button onClick={() => setShowForm(!showForm)} className={`w-14 h-14 rounded-2xl shadow-xl transition-all flex items-center justify-center ${showForm ? 'bg-white text-black border border-gray-100' : 'bg-black text-white'}`}>
          {showForm ? <X size={24} /> : <Plus size={24} />}
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleAddCustomer} className="bg-white border border-gray-100 rounded-[2.5rem] p-8 shadow-2xl space-y-4 animate-in slide-in-from-top-4">
          <div className="flex items-center justify-between mb-2">
            <h3 className="text-xs font-black text-black uppercase tracking-[0.3em]">Novo Cliente</h3>
            <UserPlus size={16} className="text-gray-300" />
          </div>
          <input type="text" placeholder="Nome Completo" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newCustomer.name} onChange={e => setNewCustomer({...newCustomer, name: e.target.value})} required />
          <div className="grid grid-cols-2 gap-4">
            <input type="tel" placeholder="WhatsApp" className="bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newCustomer.phone} onChange={e => setNewCustomer({...newCustomer, phone: e.target.value})} required />
            <input type="date" className="bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newCustomer.birthday} onChange={e => setNewCustomer({...newCustomer, birthday: e.target.value})} />
          </div>
          <input type="email" placeholder="E-mail" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newCustomer.email} onChange={e => setNewCustomer({...newCustomer, email: e.target.value})} />
          <div className="relative">
            <Instagram size={14} className="absolute left-6 top-1/2 -translate-y-1/2 text-pink-400" />
            <input type="text" placeholder="@instagram" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 pl-12 pr-6 text-xs font-bold text-black outline-none" value={newCustomer.instagram} onChange={e => setNewCustomer({...newCustomer, instagram: e.target.value})} />
          </div>
          <button type="submit" disabled={isSaving} className="w-full bg-black text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-xl">{isSaving ? 'Gravando...' : 'Confirmar Cliente'}</button>
        </form>
      )}

      <div className="bg-white rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden divide-y divide-gray-50">
        {loading ? (
          <div className="p-16 text-center text-gray-300 text-xs font-black uppercase tracking-widest animate-pulse">Sincronizando Base...</div>
        ) : filtered.length > 0 ? (
          filtered.map(customer => {
            const isBday = isTodayBirthday(customer.birthday);
            return (
              <div key={customer.id} className="p-2 transition-all">
                <div className={`p-4 flex items-center justify-between rounded-3xl ${selectedCustomerId === customer.id ? 'bg-gray-50 shadow-inner' : 'bg-white hover:bg-gray-50/50'}`}>
                  <div className="flex items-center gap-4 flex-1 cursor-pointer" onClick={() => fetchHistory(customer.id)}>
                    <div className={`w-14 h-14 rounded-full flex items-center justify-center font-black text-lg border-4 shadow-sm relative ${isBday ? 'bg-pink-500 text-white border-pink-100 animate-bounce' : 'bg-black text-white border-gray-50'}`}>
                      {customer.name.charAt(0).toUpperCase()}
                      {isBday && <Gift size={14} className="absolute -top-1 -right-1 text-pink-500 bg-white rounded-full p-0.5" />}
                    </div>
                    <div className="min-w-0">
                      <p className="text-xs font-black text-black uppercase tracking-tight">{customer.name}</p>
                      <div className="flex items-center gap-2 mt-1">
                        <span className="text-[8px] font-bold text-gray-400 tracking-widest uppercase">{customer.instagram || 'Sem IG'}</span>
                        {isBday && <span className="text-[8px] font-black text-pink-500 uppercase tracking-widest">Aniversário Hoje! ✨</span>}
                      </div>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button 
                      onClick={() => openWhatsApp(customer.phone, customer.name, isBday)}
                      className={`w-11 h-11 rounded-xl flex items-center justify-center transition-all shadow-sm ${isBday ? 'bg-pink-500 text-white' : 'bg-white border border-gray-100 text-black hover:bg-black hover:text-white'}`}
                    >
                      {isBday ? <Gift size={20}/> : <MessageCircle size={20} />}
                    </button>
                    <button onClick={() => fetchHistory(customer.id)} className={`w-11 h-11 bg-white border border-gray-100 rounded-xl flex items-center justify-center transition-all ${selectedCustomerId === customer.id ? 'rotate-90 bg-black text-white' : ''}`}>
                      <ChevronRight size={18} />
                    </button>
                  </div>
                </div>

                {/* Aba de Compras (Histórico) - Melhor Visibility */}
                {selectedCustomerId === customer.id && (
                  <div className="px-4 pb-6 pt-2 space-y-4 animate-in slide-in-from-top-2 duration-300">
                    <div className="h-px bg-gray-100 mx-4"></div>
                    <div className="grid grid-cols-2 gap-2 px-2">
                      {customer.email && (
                        <div className="flex items-center gap-2 bg-gray-50 p-3 rounded-xl">
                          <Mail size={14} className="text-indigo-400" />
                          <span className="text-[8px] font-black text-gray-500 uppercase truncate">{customer.email}</span>
