                      )}
                    </div>

                    <div className="bg-white rounded-[2rem] p-6 border border-gray-100 shadow-xl space-y-4">
                      <div className="flex items-center justify-between">
                        <h4 className="text-[10px] font-black text-black uppercase tracking-[0.2em] flex items-center gap-2">
                          <ShoppingBag size={14} className="text-indigo-600" /> 
                          Histórico de Compras
                        </h4>
                        <div className="h-2 w-2 rounded-full bg-indigo-500"></div>
                      </div>

                      {customerSales.length > 0 ? (
                        <div className="space-y-3">
                          {customerSales.map(s => (
                            <div key={s.id} className="flex justify-between items-center group">
                              <div className="flex items-center gap-3">
                                <div className="w-8 h-8 rounded-lg bg-gray-50 flex items-center justify-center">
                                  <ArrowUpRight size={12} className="text-gray-300" />
                                </div>
                                <div>
                                  <p className="text-[10px] font-black text-black uppercase truncate max-w-[120px]">{s.product?.name}</p>
                                  <p className="text-[8px] text-gray-400 font-bold uppercase tracking-widest">{new Date(s.created_at).toLocaleDateString()}</p>
                                </div>
                              </div>
                              <div className="text-right">
                                <p className="text-[10px] font-black text-emerald-600">R$ {Number(s.value).toFixed(2)}</p>
                                <p className="text-[8px] font-bold text-gray-300 uppercase">{s.amount} unidade(s)</p>
                              </div>
                            </div>
                          ))}
                        </div>
                      ) : (
                        <div className="py-10 text-center space-y-2">
                          <div className="bg-gray-50 w-10 h-10 rounded-full flex items-center justify-center mx-auto mb-2 opacity-50">
                            <ShoppingBag size={14} className="text-gray-300" />
                          </div>
                          <p className="text-[9px] text-gray-300 font-bold uppercase tracking-widest">Nenhuma compra registrada</p>
                        </div>
                      )}
                    </div>
                  </div>
                )}
              </div>
            );
          })
        ) : (
          <div className="p-20 text-center text-gray-300 text-[10px] font-black uppercase tracking-[0.3em]">Nenhuma cliente no momento.</div>
        )}
      </div>
    </div>
  );
};

export default Customers;

import React, { useState, useEffect } from 'react';
import { ArrowLeft, TrendingUp, DollarSign, PieChart as PieIcon, Info } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Sale, Product } from '../types';

interface AnalyticsProps {
  onBack: () => void;
}

const Analytics: React.FC<AnalyticsProps> = ({ onBack }) => {
  const [data, setData] = useState<{name: string, sales: number, profit: number}[]>([]);
  const [totals, setTotals] = useState({ revenue: 0, cost: 0, profit: 0 });
  const [loading, setLoading] = useState(true);

  const COLORS = ['#000000', '#4F46E5', '#10B981', '#F59E0B', '#EF4444'];

  useEffect(() => {
    fetchAnalytics();
  }, []);

  const fetchAnalytics = async () => {
    setLoading(true);
    try {
      const { data: salesData } = await supabase.from('sales').select('*, product:products(*)');

      if (salesData) {
        let totalRev = 0;
        let totalCost = 0;
        const productStats: Record<string, {name: string, sales: number, profit: number}> = {};

        salesData.forEach((sale: any) => {
          const product = sale.product;
          if (!product) return;
          const rev = Number(sale.value);
          const cost = Number(product.purchase_price) * Number(sale.amount);

          totalRev += rev;
          totalCost += cost;

          if (!productStats[product.id]) {
            productStats[product.id] = { name: product.name, sales: 0, profit: 0 };
          }
          productStats[product.id].sales += Number(sale.amount);
          productStats[product.id].profit += (rev - cost);
        });

        const chartData = Object.values(productStats).sort((a, b) => b.sales - a.sales).slice(0, 5);
        setData(chartData);
        setTotals({ revenue: totalRev, cost: totalCost, profit: totalRev - totalCost });
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  // Cálculo do Gráfico de Pizza SVG
  const totalSalesCount = data.reduce((acc, d) => acc + d.sales, 0);
  let cumulativePercent = 0;

  const getCoordinatesForPercent = (percent: number) => {
    const x = Math.cos(2 * Math.PI * percent);
    const y = Math.sin(2 * Math.PI * percent);
    return [x, y];
  };

  if (loading) return <div className="p-20 text-center text-[10px] font-black uppercase tracking-widest animate-pulse">Gerando Inteligência...</div>;

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-10">
      <button onClick={onBack} className="flex items-center gap-2 text-gray-400 hover:text-black transition-colors">
        <ArrowLeft size={16} />
        <span className="text-[10px] font-black uppercase tracking-widest">Voltar</span>
      </button>

      <div className="space-y-2">
        <h2 className="text-2xl font-black text-black uppercase tracking-tighter">Lucratividade</h2>
        <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Desempenho Real da Boutique</p>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-emerald-50 rounded-[2rem] p-6 border border-emerald-100">
          <DollarSign size={18} className="text-emerald-600 mb-4" />
          <p className="text-[9px] font-black text-emerald-800/40 uppercase tracking-widest mb-1">Lucro Bruto</p>
          <p className="text-xl font-black text-emerald-600">R$ {totals.profit.toLocaleString('pt-BR')}</p>
        </div>
        <div className="bg-indigo-50 rounded-[2rem] p-6 border border-indigo-100">
          <PieIcon size={18} className="text-indigo-600 mb-4" />
          <p className="text-[9px] font-black text-indigo-800/40 uppercase tracking-widest mb-1">Margem Média</p>
          <p className="text-xl font-black text-indigo-600">
            {totals.revenue > 0 ? ((totals.profit / totals.revenue) * 100).toFixed(1) : 0}%
          </p>
        </div>
      </div>

      {/* Gráfico de Pizza SVG Customizado */}
      <div className="bg-white rounded-[2.5rem] border border-gray-100 p-8 shadow-sm space-y-8">
        <h3 className="text-xs font-black text-black uppercase tracking-widest flex items-center gap-2">
          <PieIcon size={14} className="text-indigo-500" /> Distribuição de Vendas
        </h3>

        <div className="flex flex-col items-center gap-8">
          <div className="relative w-48 h-48">
            <svg viewBox="-1 -1 2 2" className="transform -rotate-90 w-full h-full">
              {data.map((item, i) => {
                const percent = item.sales / totalSalesCount;
                const [startX, startY] = getCoordinatesForPercent(cumulativePercent);
                cumulativePercent += percent;
                const [endX, endY] = getCoordinatesForPercent(cumulativePercent);
                const largeArcFlag = percent > 0.5 ? 1 : 0;
                const pathData = [
                  `M ${startX} ${startY}`,
                  `A 1 1 0 ${largeArcFlag} 1 ${endX} ${endY}`,
                  `L 0 0`,
                ].join(' ');
                return <path key={i} d={pathData} fill={COLORS[i % COLORS.length]} />;
              })}
            </svg>
            <div className="absolute inset-10 bg-white rounded-full flex items-center justify-center shadow-inner">
              <span className="text-[10px] font-black text-black uppercase">Mix {data.length}</span>
            </div>
          </div>

          <div className="w-full space-y-3">
            {data.map((item, i) => (
              <div key={i} className="flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className="w-2 h-2 rounded-full" style={{ backgroundColor: COLORS[i % COLORS.length] }}></div>
                  <span className="text-[10px] font-black text-black uppercase truncate max-w-[150px]">{item.name}</span>
                </div>
                <span className="text-[10px] font-black text-gray-300">{Math.round((item.sales / totalSalesCount) * 100)}%</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="p-6 bg-gray-50 rounded-[2rem] border border-gray-100">
        <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest leading-relaxed">
          * Dados baseados nas Top 5 peças com maior volume de saída.
        </p>
      </div>
    </div>
  );
};

export default Analytics;

import React, { useState, useEffect } from 'react';
import { Sparkles, Search, Plus, X, Edit2, Save, Tag, Info, DollarSign, Package, Palette, Layers, ArrowRight, RefreshCcw } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [editingPriceId, setEditingPriceId] = useState<string | null>(null);
  const [tempPrice, setTempPrice] = useState('');

  // Replenishment Mode State
  const [isReplenishing, setIsReplenishing] = useState<string | null>(null);

  // Modal State
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);

  const [newProduct, setNewProduct] = useState({
    name: '',
    reference: '',
    purchase_price: '',
    price: '',
    stock: '',
    size: '',
    color: ''
  });

  useEffect(() => { fetchProducts(); }, []);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const { data } = await supabase.from('products').select('*').order('created_at', { ascending: false });
      if (data) setProducts(data);
    } catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const handleAddProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      if (isReplenishing) {
        // Modo Atualização de Estoque
        const { error } = await supabase.from('products')
          .update({ stock: parseInt(newProduct.stock) || 0 })
          .eq('id', isReplenishing);
        if (error) throw error;
        alert('Estoque atualizado com sucesso! 📦');
      } else {
        // Modo Novo Cadastro
        const { error } = await supabase.from('products').insert([{
          name: newProduct.name.trim(),
          reference_code: newProduct.reference.trim(),
          purchase_price: parseFloat(newProduct.purchase_price.replace(',', '.')),
          price: parseFloat(newProduct.price.replace(',', '.')),
          stock: parseInt(newProduct.stock) || 0,
          size: newProduct.size.trim(),
          color: newProduct.color.trim()
        }]);
        if (error) throw error;
        alert('Produto cadastrado! ✨');
      }

      setNewProduct({ name:'', reference:'', purchase_price:'', price:'', stock:'', size:'', color:'' });
      setShowForm(false);
      setIsReplenishing(null);
      fetchProducts();
    } catch (e) { console.error(e); } finally { setIsSaving(false); }
  };

  const saveNewPrice = async (id: string) => {
    const newPrice = parseFloat(tempPrice.replace(',', '.'));
    if (isNaN(newPrice)) return;
    try {
      await supabase.from('products').update({ price: newPrice }).eq('id', id);
      setEditingPriceId(null);
      fetchProducts();
    } catch (e) { console.error(e); }
  };

  const filtered = products.filter(p => 
    p.name.toLowerCase().includes(search.toLowerCase()) || 
    p.reference_code?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-6 relative pb-10">
      <div className="flex gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400" />
          <input 
            type="text" 
            placeholder="Buscar por nome ou ref..."
            className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 pl-14 pr-6 text-xs shadow-sm focus:border-black transition-all font-bold outline-none text-black"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
        <button 
          onClick={() => {
            if (showForm) {
              setShowForm(false);
              setIsReplenishing(null);
              setNewProduct({ name:'', reference:'', purchase_price:'', price:'', stock:'', size:'', color:'' });
            } else {
              setShowForm(true);
            }
            setSelectedProduct(null);
          }} 
          className={`w-14 h-14 rounded-2xl shadow-xl transition-all flex items-center justify-center ${showForm ? 'bg-white text-black border border-gray-100' : 'bg-black text-white'}`}
        >
          {showForm ? <X size={24} /> : <Plus size={24} />}
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleAddProduct} className="bg-white border border-gray-100 rounded-[2.5rem] p-8 shadow-2xl space-y-5 animate-in slide-in-from-top-4 duration-300">
          <div className="flex items-center justify-between">
            <h3 className="text-[10px] font-black text-black uppercase tracking-[0.3em]">
              {isReplenishing ? 'Reposição de Estoque' : 'Cadastro Boutique'}
            </h3>
            {isReplenishing ? <RefreshCcw size={16} className="text-emerald-500 animate-spin-slow" /> : <Tag size={16} className="text-indigo-400" />}
          </div>

          <div className="space-y-4">
            <div>
              <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-1 block">Nome da Peça</label>
              <input type="text" disabled={!!isReplenishing} placeholder="Ex: Conjunto Noir" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none disabled:opacity-50" value={newProduct.name} onChange={e => setNewProduct({...newProduct, name: e.target.value})} required={!isReplenishing} />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-1 block">Ref. Interna</label>
                <input type="text" disabled={!!isReplenishing} placeholder="REF-000" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none disabled:opacity-50" value={newProduct.reference} onChange={e => setNewProduct({...newProduct, reference: e.target.value})} />
              </div>
              <div>
                <label className="text-[8px] font-black text-indigo-400 uppercase tracking-widest ml-1 mb-1 block">Estoque Atual</label>
                <input type="number" placeholder="0" className="w-full bg-white border-2 border-indigo-100 rounded-2xl py-4 px-6 text-xs font-black text-black outline-none ring-4 ring-indigo-50" value={newProduct.stock} onChange={e => setNewProduct({...newProduct, stock: e.target.value})} required />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-1 block">Preço Compra</label>
                <input type="text" disabled={!!isReplenishing} placeholder="R$ 0,00" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none disabled:opacity-50" value={newProduct.purchase_price} onChange={e => setNewProduct({...newProduct, purchase_price: e.target.value})} required={!isReplenishing} />
              </div>
              <div>
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-1 block">Preço Venda</label>
                <input type="text" disabled={!!isReplenishing} placeholder="R$ 0,00" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none disabled:opacity-50" value={newProduct.price} onChange={e => setNewProduct({...newProduct, price: e.target.value})} required={!isReplenishing} />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-1 block">Tamanho</label>
                <input type="text" disabled={!!isReplenishing} placeholder="P, M, G..." className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none disabled:opacity-50" value={newProduct.size} onChange={e => setNewProduct({...newProduct, size: e.target.value})} />
              </div>
              <div>
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-1 block">Cor</label>
                <input type="text" disabled={!!isReplenishing} placeholder="Preto, Nude..." className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none disabled:opacity-50" value={newProduct.color} onChange={e => setNewProduct({...newProduct, color: e.target.value})} />
              </div>
            </div>
          </div>

          <button type="submit" disabled={isSaving} className="w-full bg-black text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-xl disabled:opacity-50 active:scale-[0.98] transition-all">
            {isSaving ? 'Gravando...' : isReplenishing ? 'Confirmar Reposição' : 'Finalizar Cadastro'}
          </button>
        </form>
      )}

      {/* Product List */}
      <div className="bg-white rounded-[2.5rem] border border-gray-50 shadow-sm divide-y divide-gray-50">
        {loading ? (
          <div className="p-20 text-center text-gray-200 text-[10px] font-black uppercase tracking-widest animate-pulse">Consultando Catálogo...</div>
        ) : filtered.map(product => (
          <div 
            key={product.id} 
