                    stock: selectedProduct.stock.toString(), // Inicia com o estoque atual para edição
                    size: selectedProduct.size || '',
                    color: selectedProduct.color || ''
                  });
                  setIsReplenishing(selectedProduct.id);
                  setSelectedProduct(null);
                  setShowForm(true);
                  window.scrollTo({ top: 0, behavior: 'smooth' });
                }}
                className="flex-[1.5] bg-emerald-500 text-white py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.3em] shadow-xl flex items-center justify-center gap-2 active:scale-95 transition-all"
              >
                Reposição <ArrowRight size={14} />
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect } from 'react';
import { Plus, ShoppingBag, User, Package, DollarSign, Calendar, X, Search, Filter, Trash2, CreditCard, Banknote, QrCode } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product, Customer, Sale } from '../types';

interface CartItem {
  product: Product;
  amount: number;
}

const Sales: React.FC = () => {
  const [sales, setSales] = useState<Sale[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Estado do Carrinho
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedProductId, setSelectedProductId] = useState('');
  const [selectedProductQty, setSelectedProductQty] = useState(1);

  const [formData, setFormData] = useState({
    customerId: '',
    discount: '0',
    discountDescription: '',
    paymentMethod: 'pix',
    date: new Date().toISOString().split('T')[0]
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const { data: s } = await supabase.from('sales').select('*, customer:customers(*), product:products(*)').order('created_at', { ascending: false });
      const { data: p } = await supabase.from('products').select('*');
      const { data: c } = await supabase.from('customers').select('*');
      if (s) setSales(s);
      if (p) setProducts(p);
      if (c) setCustomers(c);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const addToCart = () => {
    if (!selectedProductId) return;
    const prod = products.find(p => p.id === selectedProductId);
    if (!prod) return;

    if (selectedProductQty > prod.stock) {
      alert(`⚠️ Estoque insuficiente! (${prod.stock} un disponíveis)`);
      return;
    }

    setCart([...cart, { product: prod, amount: selectedProductQty }]);
    setSelectedProductId('');
    setSelectedProductQty(1);
  };

  const removeFromCart = (index: number) => {
    setCart(cart.filter((_, i) => i !== index));
  };

  const cartTotal = cart.reduce((acc, item) => acc + (item.product.price * item.amount), 0);
  const finalTotal = Math.max(0, cartTotal - parseFloat(formData.discount.replace(',', '.')) || 0);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.customerId || cart.length === 0) {
      alert('Selecione uma cliente e adicione itens ao carrinho.');
      return;
    }

    setLoading(true);
    try {
      const orderId = crypto.randomUUID();
      const totalDiscount = parseFloat(formData.discount.replace(',', '.')) || 0;

      const discountPerItem = cart.length > 0 ? totalDiscount / cart.length : 0;

      const salesPayload = cart.map(item => ({
        order_id: orderId,
        customer_id: formData.customerId,
        product_id: item.product.id,
        amount: item.amount,
        value: (item.product.price * item.amount) - discountPerItem,
        discount: discountPerItem,
        discount_description: formData.discountDescription,
        payment_method: formData.paymentMethod,
        created_at: formData.date
      }));

      const { error: saleError } = await supabase.from('sales').insert(salesPayload);
      if (saleError) throw saleError;

      for (const item of cart) {
        await supabase.from('products').update({ stock: item.product.stock - item.amount }).eq('id', item.product.id);
      }

      setShowForm(false);
      setCart([]);
      setFormData({
        customerId: '',
        discount: '0',
        discountDescription: '',
        paymentMethod: 'pix',
        date: new Date().toISOString().split('T')[0]
      });
      fetchData();
      alert('Pedido realizado com sucesso! ✨');
    } catch (err) {
      console.error(err);
      alert('Erro ao processar venda.');
    } finally {
      setLoading(false);
    }
  };

  const filteredSales = sales.filter(s => 
    s.customer?.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.product?.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      {/* Header com Botão Alinhado */}
      <div className="flex items-stretch gap-3">
        <div className="relative flex-1">
          <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
          <input 
            type="text" 
            placeholder="Buscar nota ou cliente..."
            className="w-full h-full bg-gray-50 border border-gray-100 rounded-2xl py-4 pl-12 pr-4 text-xs font-bold outline-none text-black focus:border-black transition-all"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>
        <button 
          onClick={() => setShowForm(!showForm)}
          className={`w-14 h-14 rounded-2xl shadow-xl transition-all flex items-center justify-center shrink-0 ${showForm ? 'bg-white border border-gray-100 text-black' : 'bg-black text-white'}`}
        >
          {showForm ? <X size={20} /> : <Plus size={24} />}
        </button>
      </div>

      {showForm ? (
        <form onSubmit={handleSubmit} className="bg-white rounded-[2.5rem] p-8 shadow-2xl space-y-6 border border-gray-50 animate-in slide-in-from-top-4 duration-300">
          <div className="space-y-5">
            <div>
              <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block">Cliente</label>
              <select 
                className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none"
                value={formData.customerId}
                onChange={e => setFormData({...formData, customerId: e.target.value})}
                required
              >
                <option value="">Selecionar Cliente</option>
                {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>

            <div className="p-4 bg-gray-50 rounded-3xl border border-gray-100 space-y-3">
              <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1 block">Adicionar Peças</label>
              <div className="flex gap-2">
                <select 
                  className="flex-1 bg-white border border-gray-200 rounded-xl py-3 px-4 text-xs font-bold text-black outline-none"
                  value={selectedProductId}
                  onChange={e => setSelectedProductId(e.target.value)}
                >
                  <option value="">Escolher Item</option>
                  {products.map(p => <option key={p.id} value={p.id} disabled={p.stock <= 0}>{p.name} ({p.stock} un)</option>)}
                </select>
                <input 
                  type="number" 
                  className="w-16 bg-white border border-gray-200 rounded-xl py-3 px-2 text-xs font-bold text-black outline-none text-center"
                  value={selectedProductQty}
                  onChange={e => setSelectedProductQty(parseInt(e.target.value))}
                  min="1"
                />
                <button 
                  type="button"
                  onClick={addToCart}
                  className="bg-black text-white p-3 rounded-xl hover:scale-105 transition-transform"
                >
                  <Plus size={18} />
                </button>
              </div>

              {cart.length > 0 && (
                <div className="mt-4 space-y-2 max-h-40 overflow-y-auto no-scrollbar">
                  {cart.map((item, index) => (
                    <div key={index} className="flex justify-between items-center bg-white p-3 rounded-xl border border-gray-100 shadow-sm animate-in fade-in scale-in">
                      <div className="min-w-0">
                        <p className="text-[10px] font-black text-black uppercase truncate">{item.product.name}</p>
                        <p className="text-[9px] text-gray-400 font-bold">{item.amount}x R$ {item.product.price.toFixed(2)}</p>
                      </div>
                      <button type="button" onClick={() => removeFromCart(index)} className="text-red-300 hover:text-red-500 transition-colors">
                        <Trash2 size={14} />
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block">Pagamento</label>
                <div className="grid grid-cols-3 gap-2">
                  <button type="button" onClick={() => setFormData({...formData, paymentMethod: 'cartao'})} className={`p-3 rounded-xl flex justify-center border transition-all ${formData.paymentMethod === 'cartao' ? 'bg-black text-white border-black' : 'bg-gray-50 text-gray-300 border-gray-200'}`}><CreditCard size={18}/></button>
                  <button type="button" onClick={() => setFormData({...formData, paymentMethod: 'dinheiro'})} className={`p-3 rounded-xl flex justify-center border transition-all ${formData.paymentMethod === 'dinheiro' ? 'bg-black text-white border-black' : 'bg-gray-50 text-gray-300 border-gray-200'}`}><Banknote size={18}/></button>
                  <button type="button" onClick={() => setFormData({...formData, paymentMethod: 'pix'})} className={`p-3 rounded-xl flex justify-center border transition-all ${formData.paymentMethod === 'pix' ? 'bg-black text-white border-black' : 'bg-gray-50 text-gray-300 border-gray-200'}`}><QrCode size={18}/></button>
                </div>
              </div>
              <div>
                <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block">Desconto (R$)</label>
                <input type="text" placeholder="0,00" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-red-500 outline-none" value={formData.discount} onChange={e => setFormData({...formData, discount: e.target.value})} />
              </div>
            </div>

            <input 
              type="text" 
              placeholder="Motivo do desconto (Ex: Campanha Maio)" 
              className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none"
              value={formData.discountDescription}
              onChange={e => setFormData({...formData, discountDescription: e.target.value})}
            />

            <div className="bg-gray-950 p-7 rounded-[2rem] text-white flex justify-between items-center shadow-2xl">
              <div>
                <span className="text-[9px] font-black text-white/40 uppercase tracking-[0.3em]">Total Nota</span>
                <p className="text-2xl font-black">R$ {finalTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
              </div>
              <ShoppingBag size={24} className="text-white/20" />
            </div>

            <input type="date" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} required />
          </div>

          <button type="submit" className="w-full bg-black text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-xl active:scale-95 transition-all">Confirmar Nota</button>
        </form>
      ) : (
        <div className="space-y-4">
          <div className="flex items-center justify-between px-2">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">Histórico de Vendas</h3>
            <Filter size={14} className="text-gray-200" />
          </div>

          <div className="bg-white rounded-[2.5rem] border border-gray-50 shadow-sm overflow-hidden divide-y divide-gray-50">
            {loading ? (
              <div className="p-20 text-center text-gray-300 text-[10px] font-black uppercase animate-pulse">Buscando Notas...</div>
            ) : filteredSales.length > 0 ? (
              filteredSales.map(sale => (
                <div key={sale.id} className="p-6 flex items-center justify-between hover:bg-gray-50/50 transition-colors">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 rounded-2xl bg-indigo-50 flex items-center justify-center text-indigo-600 shadow-sm">
                      <ShoppingBag size={20} />
                    </div>
                    <div>
                      <p className="text-xs font-black text-black uppercase tracking-tight">{sale.customer?.name}</p>
                      <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest">{sale.product?.name} ({sale.amount}x)</p>
                      <span className="text-[7px] font-black bg-gray-100 px-1.5 py-0.5 rounded text-gray-400 uppercase">{sale.payment_method}</span>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-xs font-black text-black">R$ {Number(sale.value).toFixed(2)}</p>
                    <p className="text-[8px] text-gray-300 font-bold uppercase mt-1">{new Date(sale.created_at).toLocaleDateString('pt-BR')}</p>
                  </div>
                </div>
              ))
            ) : (
              <div className="p-20 text-center text-gray-200 text-[10px] font-black uppercase tracking-widest">Nenhuma nota emitida</div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default Sales;

import React, { useState, useEffect } from 'react';
import { Sparkles, Search, Plus, X, Edit2, Save, Tag, Info, DollarSign, Package, Palette, Layers, ArrowRight, RefreshCcw, Lock } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product } from '../types';

const Inventory: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [editingPriceId, setEditingPriceId] = useState<string | null>(null);
  const [tempPrice, setTempPrice] = useState('');

  // Replenishment Mode State
  const [isReplenishing, setIsReplenishing] = useState<string | null>(null);

  // Modal State
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);

  const [newProduct, setNewProduct] = useState({
    name: '',
    reference: '',
    purchase_price: '',
    price: '',
    stock: '',
    size: '',
    color: ''
  });

  useEffect(() => { fetchProducts(); }, []);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const { data } = await supabase.from('products').select('*').order('created_at', { ascending: false });
      if (data) setProducts(data);
    } catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const handleAddProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      if (isReplenishing) {
        // Modo Atualização de Estoque
        const { error } = await supabase.from('products')
          .update({ stock: parseInt(newProduct.stock) || 0 })
          .eq('id', isReplenishing);
        if (error) throw error;
        alert('Estoque atualizado com sucesso! 📦');
      } else {
        // Modo Novo Cadastro
        const { error } = await supabase.from('products').insert([{
          name: newProduct.name.trim(),
          reference_code: newProduct.reference.trim(),
          purchase_price: parseFloat(newProduct.purchase_price.replace(',', '.')),
          price: parseFloat(newProduct.price.replace(',', '.')),
          stock: parseInt(newProduct.stock) || 0,
          size: newProduct.size.trim(),
          color: newProduct.color.trim()
        }]);
        if (error) throw error;
        alert('Produto cadastrado! ✨');
      }

      setNewProduct({ name:'', reference:'', purchase_price:'', price:'', stock:'', size:'', color:'' });
      setShowForm(false);
      setIsReplenishing(null);
      fetchProducts();
    } catch (e) { console.error(e); } finally { setIsSaving(false); }
  };

  const saveNewPrice = async (id: string) => {
    const newPrice = parseFloat(tempPrice.replace(',', '.'));
    if (isNaN(newPrice)) return;
    try {
      await supabase.from('products').update({ price: newPrice }).eq('id', id);
      setEditingPriceId(null);
      fetchProducts();
    } catch (e) { console.error(e); }
  };

  const filtered = products.filter(p => 
    p.name.toLowerCase().includes(search.toLowerCase()) || 
    p.reference_code?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-6 relative pb-10">
      <div className="flex gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400" />
          <input 
            type="text" 
            placeholder="Buscar por nome ou ref..."
            className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 pl-14 pr-6 text-xs shadow-sm focus:border-black transition-all font-bold outline-none text-black"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
        <button 
          onClick={() => {
            if (showForm) {
              setShowForm(false);
              setIsReplenishing(null);
              setNewProduct({ name:'', reference:'', purchase_price:'', price:'', stock:'', size:'', color:'' });
            } else {
              setShowForm(true);
            }
            setSelectedProduct(null);
          }} 
          className={`w-14 h-14 rounded-2xl shadow-xl transition-all flex items-center justify-center shrink-0 ${showForm ? 'bg-white text-black border border-gray-100' : 'bg-black text-white'}`}
        >
          {showForm ? <X size={24} /> : <Plus size={24} />}
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleAddProduct} className="bg-white border border-gray-100 rounded-[2.5rem] p-8 shadow-2xl space-y-5 animate-in slide-in-from-top-4 duration-300">
          <div className="flex items-center justify-between">
            <h3 className="text-[10px] font-black text-black uppercase tracking-[0.3em]">
              {isReplenishing ? 'Reposição Direta' : 'Cadastro Boutique'}
            </h3>
            {isReplenishing ? <Lock size={16} className="text-gray-300" /> : <Tag size={16} className="text-indigo-400" />}
          </div>

          <div className="space-y-4">
            <div>
              <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-1 block">Nome da Peça</label>
              <input type="text" readOnly={!!isReplenishing} placeholder="Ex: Conjunto Noir" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none disabled:opacity-50" value={newProduct.name} onChange={e => setNewProduct({...newProduct, name: e.target.value})} required={!isReplenishing} />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-1 block">Ref. Interna</label>
                <input type="text" readOnly={!!isReplenishing} placeholder="REF-000" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none disabled:opacity-50" value={newProduct.reference} onChange={e => setNewProduct({...newProduct, reference: e.target.value})} />
              </div>
              <div>
                <label className="text-[8px] font-black text-indigo-400 uppercase tracking-widest ml-1 mb-1 block">Novo Estoque</label>
                <input type="number" placeholder="0" className="w-full bg-white border-2 border-indigo-100 rounded-2xl py-4 px-6 text-xs font-black text-black outline-none ring-4 ring-indigo-50" value={newProduct.stock} onChange={e => setNewProduct({...newProduct, stock: e.target.value})} required />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-1 block">Preço Compra</label>
                <input type="text" readOnly={!!isReplenishing} placeholder="R$ 0,00" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none disabled:opacity-50" value={newProduct.purchase_price} onChange={e => setNewProduct({...newProduct, purchase_price: e.target.value})} required={!isReplenishing} />
              </div>
              <div>
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-1 block">Preço Venda</label>
                <input type="text" readOnly={!!isReplenishing} placeholder="R$ 0,00" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none disabled:opacity-50" value={newProduct.price} onChange={e => setNewProduct({...newProduct, price: e.target.value})} required={!isReplenishing} />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-1 block">Tamanho</label>
                <input type="text" readOnly={!!isReplenishing} placeholder="P, M, G..." className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none disabled:opacity-50" value={newProduct.size} onChange={e => setNewProduct({...newProduct, size: e.target.value})} />
              </div>
              <div>
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-1 block">Cor</label>
                <input type="text" readOnly={!!isReplenishing} placeholder="Preto, Nude..." className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none disabled:opacity-50" value={newProduct.color} onChange={e => setNewProduct({...newProduct, color: e.target.value})} />
              </div>
            </div>
          </div>

          <button type="submit" disabled={isSaving} className="w-full bg-black text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-xl disabled:opacity-50 active:scale-[0.98] transition-all">
            {isSaving ? 'Gravando...' : isReplenishing ? 'Confirmar Reposição' : 'Finalizar Cadastro'}
          </button>
        </form>
      )}

      {/* Product List */}
      <div className="bg-white rounded-[2.5rem] border border-gray-50 shadow-sm divide-y divide-gray-50">
        {loading ? (
          <div className="p-20 text-center text-gray-200 text-[10px] font-black uppercase tracking-widest animate-pulse">Consultando Catálogo...</div>
        ) : filtered.map(product => (
          <div 
            key={product.id} 
            onClick={() => setSelectedProduct(product)}
            className="p-6 flex items-center gap-5 hover:bg-gray-50/50 transition-colors cursor-pointer"
          >
            <div className="w-16 h-16 rounded-2xl bg-gray-50 flex items-center justify-center text-black shadow-inner">
              <Sparkles size={24} className="text-gray-300" />
            </div>
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2">
                <p className="text-xs font-black text-black uppercase tracking-tight truncate">{product.name}</p>
                <span className="text-[8px] font-black px-1.5 py-0.5 rounded-md bg-indigo-50 text-indigo-400">{product.size}</span>
              </div>
              <p className="text-[9px] text-gray-300 font-bold uppercase tracking-widest mt-0.5">REF: {product.reference_code || '---'}</p>

              {editingPriceId === product.id ? (
                <div className="flex items-center gap-2 mt-1" onClick={e => e.stopPropagation()}>
                  <input autoFocus type="text" className="bg-gray-100 text-[10px] font-black w-20 px-2 py-1 rounded-lg outline-none text-black" value={tempPrice} onChange={e => setTempPrice(e.target.value)} onBlur={() => setEditingPriceId(null)} />
                  <button onMouseDown={() => saveNewPrice(product.id)} className="text-black"><Save size={14} /></button>
                </div>
              ) : (
                <div className="flex items-center gap-2 mt-1 group">
                  <p className="text-[10px] text-emerald-500 font-black uppercase">R$ {Number(product.price).toFixed(2)}</p>
                  <button 
                    onClick={(e) => { 
