          className={`w-14 h-14 rounded-2xl shadow-xl transition-all flex items-center justify-center shrink-0 ${showForm ? 'bg-white text-black border border-gray-100' : 'bg-black text-white'}`}
        >
          {showForm ? <X size={24} /> : <Plus size={24} />}
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleAddProduct} className="bg-white border border-gray-100 rounded-[2.5rem] p-8 shadow-2xl space-y-5 animate-in slide-in-from-top-4 duration-300">
          <div className="flex justify-between items-center">
            <h3 className="text-[10px] font-black text-black uppercase tracking-[0.3em]">Cadastro de Variante</h3>
            {newProduct.name && (
              <span className="text-[8px] font-black bg-purple-100 text-purple-600 px-2 py-1 rounded-md uppercase tracking-widest">Modo Reposição</span>
            )}
          </div>

          <div className="space-y-4">
            <input type="text" placeholder="Nome do Conjunto" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newProduct.name} onChange={e => setNewProduct({...newProduct, name: e.target.value})} required />

            <div className="grid grid-cols-2 gap-4">
              <input type="text" placeholder="Referência" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newProduct.reference} onChange={e => setNewProduct({...newProduct, reference: e.target.value})} required />
              <input type="number" placeholder="Quantidade" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none focus:ring-2 ring-black" value={newProduct.stock} onChange={e => setNewProduct({...newProduct, stock: e.target.value})} required />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <input type="text" placeholder="Cor (Ex: Rosê)" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newProduct.color} onChange={e => setNewProduct({...newProduct, color: e.target.value})} required />
              <input type="text" placeholder="Tam (Ex: P)" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newProduct.size} onChange={e => setNewProduct({...newProduct, size: e.target.value})} required />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <input type="text" placeholder="Custo R$" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newProduct.purchase_price} onChange={e => setNewProduct({...newProduct, purchase_price: e.target.value})} required />
              <input type="text" placeholder="Venda R$" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newProduct.price} onChange={e => setNewProduct({...newProduct, price: e.target.value})} required />
            </div>

            <div className="h-px bg-gray-50 my-2"></div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-2">Data da Compra</label>
                <input type="date" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-3 px-4 text-[10px] font-bold text-black outline-none" value={newProduct.purchase_date} onChange={e => setNewProduct({...newProduct, purchase_date: e.target.value})} />
              </div>
              <div className="space-y-1">
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-2">Meta de Giro (Dias)</label>
                <input type="number" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-3 px-4 text-[10px] font-bold text-black outline-none" value={newProduct.expected_days} onChange={e => setNewProduct({...newProduct, expected_days: e.target.value})} />
              </div>
            </div>
          </div>

          <div className="flex gap-2">
            {newProduct.name && (
               <button type="button" onClick={() => setNewProduct({ name:'', reference:'', purchase_price:'', price:'', stock:'', size:'', color:'', purchase_date: new Date().toISOString().split('T')[0], expected_days: '30' })} className="px-6 bg-gray-100 rounded-2xl text-gray-400"><X size={18}/></button>
            )}
            <button type="submit" disabled={isSaving} className="flex-1 bg-black text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-xl active:scale-[0.98] transition-all">
              {isSaving ? 'Gravando...' : 'Salvar no Conjunto'}
            </button>
          </div>
        </form>
      )}

      {loading ? (
        <div className="p-20 text-center text-gray-200 text-[10px] font-black uppercase animate-pulse">Consultando...</div>
      ) : activeTab === 'catalogo' ? (
        <div className="space-y-4">
          {filteredGroups.map(group => (
            <div key={group.ref} className="bg-white rounded-[2rem] border border-gray-100 shadow-sm overflow-hidden">
              <div className="bg-gray-50 px-6 py-4 flex justify-between items-center border-b border-gray-100">
                <div>
                  <p className="text-xs font-black text-black uppercase tracking-tight">{group.name}</p>
                  <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest">REF: {group.ref}</p>
                </div>
                <div className="text-right">
                  <p className="text-[10px] font-black text-gray-300 uppercase">Total Peças</p>
                  <p className="text-sm font-black text-black">{group.total}</p>
                </div>
              </div>

              <div className="divide-y divide-gray-50">
                {group.variants.map(variant => (
                  <div 
                    key={variant.id} 
                    className="px-6 py-4 flex items-center justify-between group hover:bg-gray-50/80 transition-all cursor-pointer active:scale-[0.99]"
                    onClick={() => setSelectedProduct(variant)}
                  >
                    <div className="flex items-center gap-4">
                      <div className="flex flex-col">
                        <span className="text-[10px] font-black text-black bg-gray-100 px-2 py-0.5 rounded-md self-start mb-1">{variant.size}</span>
                        <span className="text-[10px] font-bold text-gray-500 uppercase">{variant.color}</span>
                      </div>
                    </div>
                    <div className="flex items-center gap-6">
                      <div className="text-right">
                        <p className="text-[10px] font-black text-emerald-600">R$ {Number(variant.price).toFixed(2)}</p>
                        <p className={`text-[10px] font-black ${variant.stock < 2 ? 'text-red-500' : 'text-gray-400'}`}>{variant.stock} un</p>
                      </div>
                      <button 
                        onClick={(e) => {
                          e.stopPropagation();
                          setDeletingId(variant.id);
                        }}
                        className="p-2 text-gray-200 hover:text-red-500 transition-colors"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      ) : (
        /* Aba de Giro (Aging) */
        <div className="space-y-4">
          <div className="p-4 bg-purple-50 rounded-2xl border border-purple-100 flex items-start gap-3">
             <Info size={14} className="text-purple-400 mt-0.5" />
             <p className="text-[9px] font-black text-purple-400 uppercase tracking-widest">
               Aqui você monitora o tempo de prateleira de cada item para evitar estoque parado.
             </p>
          </div>
          {products.map(product => {
            const status = getAgingStatus(product);
            return (
              <div 
                key={product.id} 
                className="bg-white p-6 rounded-[2rem] border border-gray-100 shadow-sm flex items-center justify-between cursor-pointer hover:bg-gray-50 transition-colors"
                onClick={() => setSelectedProduct(product)}
              >
                <div className="space-y-2">
                  <div>
                    <p className="text-[10px] font-black text-black uppercase">{product.name} ({product.size})</p>
                    <p className="text-[8px] text-gray-400 font-bold uppercase tracking-widest">Estoque: {product.stock} un</p>
                  </div>
                  {status && (
                    <div className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[8px] font-black uppercase ${status.color}`}>
                      <status.icon size={10} />
                      {status.label} • {status.days} dias em loja
                    </div>
                  )}
                </div>
                <div className="text-right">
                  <p className="text-[8px] font-black text-gray-300 uppercase mb-1">Expectativa</p>
                  <p className="text-xs font-black text-black">{product.expected_days} dias</p>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {filteredGroups.length === 0 && !loading && (
        <div className="p-20 text-center text-gray-200 text-[10px] font-black uppercase tracking-widest">Nenhuma peça encontrada</div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect } from 'react';
import { Search, MessageCircle, Plus, Phone, X, UserPlus, AlertCircle, Gift, Mail, Instagram, ChevronRight, ReceiptText, Calendar, ArrowUpRight, TrendingUp, History, Edit2, DollarSign, Clock } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Customer, Sale } from '../types';

const Customers: React.FC = () => {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
  const [customerSales, setCustomerSales] = useState<Sale[]>([]);

  // Estado para Edição
  const [editingId, setEditingId] = useState<string | null>(null);

  const [newCustomer, setNewCustomer] = useState({
    name: '',
    phone: '',
    email: '',
    instagram: '',
    birthday: ''
  });

  useEffect(() => { fetchCustomers(); }, []);

  const fetchCustomers = async () => {
    try {
      setLoading(true);
      const { data, error } = await supabase.from('customers').select('*').order('name', { ascending: true });
      if (error) throw error;
      if (data) setCustomers(data);
    } catch (e) { 
      console.error(e); 
    } finally { 
      setLoading(false); 
    }
  };

  const fetchHistory = async (id: string) => {
    if (selectedCustomerId === id) {
      setSelectedCustomerId(null);
      return;
    }
    const { data } = await supabase.from('sales').select('*, product:products(*)').eq('customer_id', id).order('created_at', { ascending: false });
    if (data) setCustomerSales(data);
    setSelectedCustomerId(id);
  };

  const handleSaveCustomer = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      const payload = {
        name: newCustomer.name.trim(),
        phone: newCustomer.phone.replace(/\D/g, ''),
        email: newCustomer.email.trim(),
        instagram: newCustomer.instagram.trim().replace('@', ''),
        birthday: newCustomer.birthday || null
      };

      if (editingId) {
        const { error } = await supabase.from('customers').update(payload).eq('id', editingId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('customers').insert([payload]);
        if (error) throw error;
      }

      setNewCustomer({ name: '', phone: '', email: '', instagram: '', birthday: '' });
      setShowForm(false);
      setEditingId(null);
      fetchCustomers();
    } catch (e) {
      alert('Erro ao salvar cliente.');
    } finally {
      setIsSaving(false);
    }
  };

  const startEdit = (customer: Customer) => {
    setEditingId(customer.id);
    setNewCustomer({
      name: customer.name,
      phone: customer.phone,
      email: customer.email || '',
      instagram: customer.instagram || '',
      birthday: customer.birthday || ''
    });
    setShowForm(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const calculateMetrics = (sales: Sale[]) => {
    const totalValue = sales.reduce((acc, s) => acc + Number(s.value), 0);
    const uniqueOrders = new Set(sales.map(s => s.order_id)).size;
    const avgTicket = uniqueOrders > 0 ? totalValue / uniqueOrders : 0;

    let lastPurchaseDate = null;
    let daysInactive = 0;

    if (sales.length > 0) {
      lastPurchaseDate = new Date(sales[0].created_at);
      daysInactive = Math.floor((new Date().getTime() - lastPurchaseDate.getTime()) / (1000 * 3600 * 24));
    }

    return { totalValue, frequency: uniqueOrders, avgTicket, daysInactive, lastPurchaseDate };
  };

  const openWhatsApp = (phone: string, name: string, isBirthday: boolean) => {
    const cleanPhone = phone.replace(/\D/g, '');
    const msg = isBirthday 
      ? `Parabéns ${name}! ✨ Notamos que é seu aniversário hoje e preparamos um cupom especial para você na Sensitive Shop! 🎁`
      : `Olá ${name} ✨, temos novidades incríveis na boutique!`;
    window.open(`https://wa.me/55${cleanPhone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const isTodayBirthday = (birthdayStr?: string) => {
    if (!birthdayStr) return false;
    const today = new Date();
    const bday = new Date(birthdayStr);
    return today.getDate() + 1 === bday.getDate() + 1 && today.getMonth() === bday.getMonth();
  };

  const filtered = customers.filter(c => c.name.toLowerCase().includes(search.toLowerCase()) || c.phone.includes(search));

  return (
    <div className="space-y-6 pb-20">
      <div className="flex gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400" />
          <input 
            type="text" 
            placeholder="Buscar por nome ou celular..."
            className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 pl-14 pr-6 text-sm shadow-sm focus:border-black transition-all font-bold outline-none text-black"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
        <button 
          onClick={() => {
            setShowForm(!showForm);
            if (showForm) setEditingId(null);
          }} 
          className={`w-14 h-14 rounded-2xl shadow-xl transition-all flex items-center justify-center shrink-0 ${showForm ? 'bg-white text-black border border-gray-100' : 'bg-black text-white'}`}
        >
          {showForm ? <X size={24} /> : <Plus size={24} />}
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleSaveCustomer} className="bg-white border border-gray-100 rounded-[2.5rem] p-8 shadow-2xl space-y-4 animate-in slide-in-from-top-4">
          <div className="flex items-center justify-between mb-2">
            <h3 className="text-xs font-black text-black uppercase tracking-[0.3em]">{editingId ? 'Editar Cliente' : 'Novo Cliente'}</h3>
            <UserPlus size={16} className="text-gray-300" />
          </div>
          <input type="text" placeholder="Nome Completo" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newCustomer.name} onChange={e => setNewCustomer({...newCustomer, name: e.target.value})} required />
          <div className="grid grid-cols-2 gap-4">
            <input type="tel" placeholder="WhatsApp" className="bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newCustomer.phone} onChange={e => setNewCustomer({...newCustomer, phone: e.target.value})} required />
            <input type="date" className="bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newCustomer.birthday} onChange={e => setNewCustomer({...newCustomer, birthday: e.target.value})} />
          </div>
          <input type="email" placeholder="E-mail" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newCustomer.email} onChange={e => setNewCustomer({...newCustomer, email: e.target.value})} />
          <div className="relative">
            <Instagram size={14} className="absolute left-6 top-1/2 -translate-y-1/2 text-pink-400" />
            <input type="text" placeholder="instagram (sem @)" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 pl-12 pr-6 text-xs font-bold text-black outline-none" value={newCustomer.instagram} onChange={e => setNewCustomer({...newCustomer, instagram: e.target.value})} />
          </div>
          <button type="submit" disabled={isSaving} className="w-full bg-black text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-xl active:scale-[0.98] transition-all">
            {isSaving ? 'Gravando...' : editingId ? 'Salvar Alterações' : 'Confirmar Cliente'}
          </button>
        </form>
      )}

      <div className="bg-white rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden divide-y divide-gray-50">
        {loading ? (
          <div className="p-16 text-center text-gray-300 text-xs font-black uppercase tracking-widest animate-pulse">Sincronizando Base...</div>
        ) : filtered.length > 0 ? (
          filtered.map(customer => {
            const isBday = isTodayBirthday(customer.birthday);
            return (
              <div key={customer.id} className="p-2 transition-all">
                <div className={`p-4 flex items-center justify-between rounded-3xl ${selectedCustomerId === customer.id ? 'bg-gray-50 shadow-inner' : 'bg-white hover:bg-gray-50/50'}`}>
                  <div className="flex items-center gap-4 flex-1 cursor-pointer" onClick={() => fetchHistory(customer.id)}>
                    <div className={`w-14 h-14 rounded-full flex items-center justify-center font-black text-lg border-4 shadow-sm relative ${isBday ? 'bg-pink-500 text-white border-pink-100 animate-bounce' : 'bg-black text-white border-gray-50'}`}>
                      {customer.name.charAt(0).toUpperCase()}
                      {isBday && <Gift size={14} className="absolute -top-1 -right-1 text-pink-500 bg-white rounded-full p-0.5" />}
                    </div>
                    <div className="min-w-0">
                      <p className="text-xs font-black text-black uppercase tracking-tight">{customer.name}</p>
                      <div className="flex items-center gap-2 mt-1">
                        <span className="text-[8px] font-bold text-gray-400 tracking-widest uppercase">{customer.instagram ? `@${customer.instagram}` : 'Sem IG'}</span>
                        {isBday && <span className="text-[8px] font-black text-pink-500 uppercase tracking-widest">Aniversário Hoje! ✨</span>}
                      </div>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button 
                      onClick={() => startEdit(customer)}
                      className="w-10 h-10 bg-white border border-gray-100 rounded-xl flex items-center justify-center text-gray-300 hover:text-black transition-all"
                    >
                      <Edit2 size={16} />
                    </button>
                    <button 
                      onClick={() => openWhatsApp(customer.phone, customer.name, isBday)}
                      className={`w-11 h-11 rounded-xl flex items-center justify-center transition-all shadow-sm ${isBday ? 'bg-pink-500 text-white' : 'bg-white border border-gray-100 text-black hover:bg-black hover:text-white'}`}
                    >
                      {isBday ? <Gift size={20}/> : <MessageCircle size={20} />}
                    </button>
                    <button onClick={() => fetchHistory(customer.id)} className={`w-11 h-11 bg-white border border-gray-100 rounded-xl flex items-center justify-center transition-all ${selectedCustomerId === customer.id ? 'rotate-90 bg-black text-white' : ''}`}>
                      <ChevronRight size={18} />
                    </button>
                  </div>
                </div>

                {selectedCustomerId === customer.id && (
                  <div className="px-4 pb-6 pt-2 space-y-4 animate-in slide-in-from-top-2 duration-300">
                    <div className="h-px bg-gray-100 mx-4"></div>

                    {/* Dashboard CRM da Cliente */}
                    {(() => {
                      const metrics = calculateMetrics(customerSales);
                      return (
                        <div className="grid grid-cols-3 gap-3">
                          <div className="bg-white p-4 rounded-[1.5rem] border border-gray-100 shadow-sm text-center">
                            <p className="text-[8px] font-black text-gray-300 uppercase mb-1">Lifetime Value</p>
                            <p className="text-sm font-black text-black">R$ {metrics.totalValue.toFixed(0)}</p>
                          </div>
                          <div className="bg-white p-4 rounded-[1.5rem] border border-gray-100 shadow-sm text-center">
                            <p className="text-[8px] font-black text-gray-300 uppercase mb-1">Ticket Médio</p>
                            <p className="text-sm font-black text-black">R$ {metrics.avgTicket.toFixed(0)}</p>
                          </div>
                          <div className="bg-white p-4 rounded-[1.5rem] border border-gray-100 shadow-sm text-center">
                            <p className="text-[8px] font-black text-gray-300 uppercase mb-1">Frequência</p>
                            <p className="text-sm font-black text-black">{metrics.frequency}x</p>
                          </div>

                          {/* Alerta de Inatividade */}
                          <div className={`col-span-3 p-3 rounded-2xl border flex items-center justify-between px-5 ${
                            metrics.daysInactive > 60 ? 'bg-red-50 border-red-100 text-red-500' :
                            metrics.daysInactive > 30 ? 'bg-amber-50 border-amber-100 text-amber-600' :
                            'bg-emerald-50 border-emerald-100 text-emerald-600'
                          }`}>
                            <div className="flex items-center gap-2">
                              <Clock size={14} />
                              <span className="text-[9px] font-black uppercase tracking-widest">
                                {metrics.daysInactive === 0 ? 'Comprou hoje!' : `Última compra há ${metrics.daysInactive} dias`}
                              </span>
                            </div>
                            <span className="text-[8px] font-black uppercase bg-white/50 px-3 py-1 rounded-full">
                              {metrics.daysInactive > 60 ? 'Risco de Perda' : metrics.daysInactive > 30 ? 'Atenção' : 'Fiel / Ativa'}
                            </span>
                          </div>
                        </div>
                      );
                    })()}

                    <div className="bg-white rounded-[2rem] p-6 border border-gray-100 shadow-xl space-y-4">
                      <div className="flex items-center justify-between">
                        <h4 className="text-[10px] font-black text-black uppercase tracking-[0.2em] flex items-center gap-2">
                          <ReceiptText size={16} className="text-purple-600" /> 
                          Histórico de Compras
                        </h4>
                        <div className="h-2 w-2 rounded-full bg-purple-500"></div>
                      </div>

                      {customerSales.length > 0 ? (
                        <div className="space-y-3">
                          {customerSales.map(s => (
                            <div key={s.id} className="flex justify-between items-center group bg-gray-50/50 p-3 rounded-2xl border border-gray-50">
                              <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center">
                                  <ArrowUpRight size={16} className="text-emerald-500" />
                                </div>
                                <div>
                                  <p className="text-[10px] font-black text-black uppercase truncate max-w-[120px]">{s.product?.name}</p>
                                  <p className="text-[8px] text-gray-400 font-bold uppercase tracking-widest">{new Date(s.created_at).toLocaleDateString()}</p>
                                </div>
                              </div>
                              <div className="text-right">
                                <p className="text-[10px] font-black text-emerald-600">R$ {Number(s.value).toFixed(2)}</p>
                                <p className="text-[8px] font-bold text-gray-300 uppercase">{s.amount} un.</p>
                              </div>
                            </div>
                          ))}
                        </div>
                      ) : (
                        <div className="py-10 text-center space-y-2">
                          <div className="bg-gray-50 w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-2 border border-gray-100">
                            <ReceiptText size={18} className="text-gray-300" />
                          </div>
                          <p className="text-[9px] text-gray-300 font-bold uppercase tracking-widest">Nenhuma compra registrada</p>
                        </div>
                      )}
                    </div>
                  </div>
                )}
              </div>
            );
          })
        ) : (
          <div className="p-20 text-center text-gray-300 text-[10px] font-black uppercase tracking-[0.3em]">Nenhuma cliente no momento.</div>
        )}
      </div>
    </div>
  );
};

export default Customers;

import React, { useState, useEffect } from 'react';
import { 
  Heart, 
  ShoppingBag, 
  Gem, 
  UserRound, 
  LogOut,
  BarChart3
} from 'lucide-react';
import { isSupabaseConfigured } from './lib/supabase';
import Dashboard from './components/Dashboard';
import Sales from './components/Sales';
import Inventory from './components/Inventory';
import Customers from './components/Customers';
import Login from './components/Login';
import Analytics from './components/Analytics';

enum View {
  Dashboard = 'dashboard',
  Sales = 'sales',
  Inventory = 'inventory',
  Customers = 'customers',
  Financial = 'financial'
}

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [currentView, setCurrentView] = useState<View>(View.Dashboard);
  const [configured, setConfigured] = useState<boolean>(true);

  useEffect(() => {
    const isConfigured = isSupabaseConfigured();
    setConfigured(isConfigured);

    if (isConfigured) {
      const session = localStorage.getItem('app_session');
      if (session === 'true') {
        setIsAuthenticated(true);
      }
    }
  }, []);

  if (!configured) return <div className="p-10 text-center">Configuração pendente no Supabase.</div>;
  if (!isAuthenticated) return <Login onLogin={() => setIsAuthenticated(true)} />;

  const renderView = () => {
    switch (currentView) {
      case View.Dashboard: return <Dashboard onNavigate={(v) => setCurrentView(v as View)} />;
      case View.Sales: return <Sales />;
      case View.Inventory: return <Inventory />;
      case View.Customers: return <Customers />;
      case View.Financial: return <Analytics onBack={() => setCurrentView(View.Dashboard)} />;
      default: return <Dashboard onNavigate={(v) => setCurrentView(v as View)} />;
    }
  };

  const NavItem = ({ view, icon: Icon, label }: { view: View, icon: any, label: string }) => (
    <button
      onClick={() => setCurrentView(view)}
      className={`flex flex-col items-center justify-center w-full py-2 transition-all ${
        currentView === view ? 'text-black' : 'text-purple-300'
      }`}
    >
      <div className={`p-2 rounded-2xl transition-all ${currentView === view ? 'bg-white shadow-sm' : ''}`}>
        <Icon size={20} strokeWidth={currentView === view ? 2.5 : 2} />
      </div>
      <span className={`text-[9px] mt-1 font-black uppercase tracking-[0.2em] transition-all ${currentView === view ? 'opacity-100' : 'opacity-60'}`}>
        {label}
      </span>
    </button>
  );

  return (
    <div className="min-h-screen bg-white flex flex-col max-w-md mx-auto shadow-2xl overflow-x-hidden">
      <header className="bg-white border-b border-gray-50 px-6 py-6 sticky top-0 z-20 flex justify-between items-center">
        <div className="flex items-baseline gap-3">
          <span className="text-3xl font-serif-brand font-black text-black">S.</span>
          <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em] mb-1">
            {currentView === View.Financial ? 'Análise Financeira' : currentView}
          </span>
        </div>
        <button 
          onClick={() => {
            localStorage.removeItem('app_session');
            setIsAuthenticated(false);
          }}
          className="p-2 text-gray-200 hover:text-black transition-colors"
        >
          <LogOut size={18} />
        </button>
      </header>

      <main className="flex-1 overflow-y-auto pb-32 px-6 pt-6 no-scrollbar">
        {renderView()}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-[#fefafe] border-t border-purple-50 px-4 py-4 flex justify-around items-center z-30 max-w-md mx-auto shadow-[0_-15px_40px_rgba(147,51,234,0.06)]">
        <NavItem view={View.Dashboard} icon={Heart} label="Início" />
        <NavItem view={View.Sales} icon={ShoppingBag} label="Venda" />
        <NavItem view={View.Inventory} icon={Gem} label="Peças" />
        <NavItem view={View.Customers} icon={UserRound} label="Clientes" />
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Sparkles, ShoppingBag, AlertCircle, ArrowUpRight, TrendingUp, Heart, Ribbon, ChevronRight, Flower } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product } from '../types';

interface DashboardProps {
  onNavigate: (view: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ onNavigate }) => {
  const [stats, setStats] = useState({ revenue: 0, salesCount: 0, previousRevenue: 0 });
  const [monthlyData, setMonthlyData] = useState<{month: string, total: number}[]>([]);
  const [lowStock, setLowStock] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const { data: sales } = await supabase.from('sales').select('value, created_at');

      if (sales) {
        const now = new Date();
        const currentMonth = now.getMonth();
        const currentYear = now.getFullYear();

        let currentTotal = 0;
        let prevTotal = 0;
        const monthsMap: Record<string, number> = {};

        sales.forEach(sale => {
          const date = new Date(sale.created_at);
          const monthLabel = date.toLocaleString('pt-BR', { month: 'short' });
          const m = date.getMonth();
          const y = date.getFullYear();

          const key = `${monthLabel}/${y.toString().slice(-2)}`;
          monthsMap[key] = (monthsMap[key] || 0) + Number(sale.value);

          if (m === currentMonth && y === currentYear) {
            currentTotal += Number(sale.value);
          } else if (m === (currentMonth === 0 ? 11 : currentMonth - 1) && y === (currentMonth === 0 ? currentYear - 1 : currentYear)) {
            prevTotal += Number(sale.value);
          }
        });

        const sortedMonths = Object.entries(monthsMap)
          .map(([month, total]) => ({ month, total }))
          .slice(-3);

        setMonthlyData(sortedMonths);
        setStats({ revenue: currentTotal, salesCount: sales.filter(s => new Date(s.created_at).getMonth() === currentMonth).length, previousRevenue: prevTotal });
      }

      const { data: products } = await supabase.from('products').select('*').lt('stock', 3);
      if (products) setLowStock(products);
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  const growth = stats.previousRevenue > 0 ? ((stats.revenue - stats.previousRevenue) / stats.previousRevenue) * 100 : 0;

  if (loading) return <div className="p-10 animate-pulse text-center text-[10px] font-black uppercase tracking-widest text-gray-300">Sincronizando Boutique...</div>;

  return (
    <div className="space-y-6">
      {/* Revenue Card com Glow Suave */}
      <div className="bg-gray-950 rounded-[2.5rem] p-7 text-white shadow-2xl relative overflow-hidden border border-white/5">
        <div className="absolute -right-10 -top-10 p-8 opacity-10 blur-2xl bg-purple-500 w-40 h-40 rounded-full"></div>
        <div className="absolute right-6 top-6 opacity-20">
          <Sparkles size={40} className="text-purple-300" />
        </div>

        <div className="relative z-10 space-y-6">
          <div className="flex justify-between items-center">
            <span className="text-[10px] font-black uppercase tracking-[0.3em] opacity-50">Fluxo da Boutique</span>
            <div className={`flex items-center gap-1 px-3 py-1 rounded-full text-[10px] font-black ${growth >= 0 ? 'bg-emerald-500/20 text-emerald-400' : 'bg-red-500/20 text-red-400'}`}>
              {growth >= 0 ? '+' : ''}{growth.toFixed(1)}% performance
            </div>
          </div>

          <div>
            <p className="text-4xl font-black tracking-tighter mb-1">
              R$ {stats.revenue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
            </p>
            <p className="text-[9px] font-bold text-white/30 uppercase tracking-widest">Saldo Atual {new Date().toLocaleString('pt-BR', { month: 'long' })}</p>
          </div>

          <div className="h-px bg-white/10 w-full border-t border-dashed border-white/20"></div>

          <div className="grid grid-cols-3 gap-4">
            {monthlyData.map((data, i) => (
              <div key={i} className="space-y-1">
                <p className="text-[8px] font-black text-white/30 uppercase tracking-widest">{data.month}</p>
                <p className="text-xs font-black">R$ {data.total > 1000 ? (data.total / 1000).toFixed(1) + 'k' : data.total.toFixed(0)}</p>
              </div>
            ))}
          </div>

          <button 
            onClick={() => onNavigate('financial')}
            className="w-full bg-white/5 hover:bg-white/10 border border-white/10 py-4 rounded-2xl flex items-center justify-center gap-2 transition-all group"
          >
            <span className="text-[10px] font-black uppercase tracking-widest">Análise Financeira Completa</span>
            <ArrowUpRight size={14} className="group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-transform" />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white border border-gray-100 rounded-[2rem] p-6 shadow-sm">
          <div className="bg-pink-50 w-10 h-10 rounded-2xl flex items-center justify-center mb-4">
            <Ribbon size={20} className="text-pink-400" />
          </div>
          <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Desejos (Vendas)</p>
          <p className="text-2xl font-black text-gray-900">{stats.salesCount}</p>
        </div>

        <div className="bg-white border border-gray-100 rounded-[2rem] p-6 shadow-sm">
          <div className="bg-purple-50 w-10 h-10 rounded-2xl flex items-center justify-center mb-4">
            <Flower size={20} className="text-purple-400" />
          </div>
          <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Reposição</p>
          <p className="text-2xl font-black text-red-600">{lowStock.length}</p>
        </div>
      </div>

      {/* Alerta de Estoque com Visual de Peça */}
      <div className="bg-white border border-gray-100 rounded-[2.5rem] overflow-hidden shadow-sm">
        <div className="px-6 py-5 border-b border-gray-50 flex justify-between items-center bg-gray-50/30">
          <h2 className="text-[11px] font-black text-gray-900 uppercase tracking-[0.2em] flex items-center gap-2">
            <AlertCircle size={14} className="text-amber-400" />
            Curadoria Urgente
          </h2>
        </div>
        <div className="divide-y divide-gray-50">
          {lowStock.length > 0 ? (
            lowStock.map(product => (
              <button 
                key={product.id} 
                onClick={() => onNavigate('inventory')}
                className="w-full px-6 py-4 flex justify-between items-center hover:bg-gray-50 transition-colors text-left"
              >
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 rounded-xl bg-purple-50 flex items-center justify-center text-purple-300">
                    <Sparkles size={16} />
                  </div>
                  <div>
                    <p className="text-xs font-black text-gray-900 uppercase tracking-tight">{product.name}</p>
                    <p className="text-[9px] text-gray-400 font-bold tracking-widest uppercase">{product.reference_code || 'S/ REF'}</p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <div className="text-right">
                    <p className="text-xs font-black text-red-600">{product.stock} un</p>
                  </div>
                  <ChevronRight size={14} className="text-gray-200" />
                </div>
              </button>
            ))
          ) : (
            <div className="p-12 text-center">
              <p className="text-xs text-gray-200 font-black uppercase tracking-widest">Estoque Impecável ✨</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { Search, MessageCircle, Plus, Phone, X, UserPlus, AlertCircle, Gift, Mail, Instagram, ChevronRight, ReceiptText, Calendar, ArrowUpRight, TrendingUp, History, Edit2, DollarSign, Clock, Crown, Star, Gem } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Customer, Sale } from '../types';

const Customers: React.FC = () => {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
  const [customerSales, setCustomerSales] = useState<Sale[]>([]);

  // Estado para Edição
  const [editingId, setEditingId] = useState<string | null>(null);

  const [newCustomer, setNewCustomer] = useState({
    name: '',
    phone: '',
    email: '',
    instagram: '',
    birthday: ''
  });

  useEffect(() => { fetchCustomers(); }, []);

  const fetchCustomers = async () => {
    try {
      setLoading(true);
      const { data, error } = await supabase.from('customers').select('*').order('name', { ascending: true });
      if (error) throw error;
      if (data) setCustomers(data);
    } catch (e) { 
      console.error(e); 
    } finally { 
      setLoading(false); 
    }
  };

  const fetchHistory = async (id: string) => {
    if (selectedCustomerId === id) {
      setSelectedCustomerId(null);
      return;
    }
    const { data } = await supabase.from('sales').select('*, product:products(*)').eq('customer_id', id).order('created_at', { ascending: false });
    if (data) setCustomerSales(data);
    setSelectedCustomerId(id);
  };

  const handleSaveCustomer = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      const payload = {
        name: newCustomer.name.trim(),
        phone: newCustomer.phone.replace(/\D/g, ''),
        email: newCustomer.email.trim(),
        instagram: newCustomer.instagram.trim().replace('@', ''),
        birthday: newCustomer.birthday || null
      };

      if (editingId) {
        const { error } = await supabase.from('customers').update(payload).eq('id', editingId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('customers').insert([payload]);
        if (error) throw error;
      }

      setNewCustomer({ name: '', phone: '', email: '', instagram: '', birthday: '' });
      setShowForm(false);
      setEditingId(null);
      fetchCustomers();
    } catch (e) {
      alert('Erro ao salvar cliente.');
    } finally {
      setIsSaving(false);
    }
  };

  const startEdit = (customer: Customer) => {
    setEditingId(customer.id);
    setNewCustomer({
      name: customer.name,
      phone: customer.phone,
      email: customer.email || '',
      instagram: customer.instagram || '',
      birthday: customer.birthday || ''
    });
    setShowForm(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const calculateMetrics = (sales: Sale[]) => {
    const totalValue = sales.reduce((acc, s) => acc + Number(s.value), 0);
    const uniqueOrders = new Set(sales.map(s => s.order_id)).size;
    const avgTicket = uniqueOrders > 0 ? totalValue / uniqueOrders : 0;

    let lastPurchaseDate = null;
    let daysInactive = 0;

    if (sales.length > 0) {
      lastPurchaseDate = new Date(sales[0].created_at);
      daysInactive = Math.floor((new Date().getTime() - lastPurchaseDate.getTime()) / (1000 * 3600 * 24));
    }

    return { totalValue, frequency: uniqueOrders, avgTicket, daysInactive, lastPurchaseDate };
  };

  const openWhatsApp = (phone: string, name: string, isBirthday: boolean) => {
    const cleanPhone = phone.replace(/\D/g, '');
    const msg = isBirthday 
      ? `Parabéns ${name}! ✨ Notamos que é seu aniversário hoje e preparamos um cupom especial para você na Sensitive Shop! 🎁`
      : `Olá ${name} ✨, temos novidades incríveis na boutique!`;
    window.open(`https://wa.me/55${cleanPhone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const isTodayBirthday = (birthdayStr?: string) => {
    if (!birthdayStr) return false;
    const today = new Date();
    const bday = new Date(birthdayStr);
    return today.getDate() + 1 === bday.getDate() + 1 && today.getMonth() === bday.getMonth();
  };

  const filtered = customers.filter(c => c.name.toLowerCase().includes(search.toLowerCase()) || c.phone.includes(search));

  return (
    <div className="space-y-6 pb-20">
      <div className="flex gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400" />
          <input 
            type="text" 
            placeholder="Buscar por nome ou celular..."
            className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 pl-14 pr-6 text-sm shadow-sm focus:border-black transition-all font-bold outline-none text-black"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
        <button 
          onClick={() => {
            setShowForm(!showForm);
            if (showForm) setEditingId(null);
          }} 
          className={`w-14 h-14 rounded-2xl shadow-xl transition-all flex items-center justify-center shrink-0 ${showForm ? 'bg-white text-black border border-gray-100' : 'bg-black text-white'}`}
        >
          {showForm ? <X size={24} /> : <Plus size={24} />}
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleSaveCustomer} className="bg-white border border-gray-100 rounded-[2.5rem] p-8 shadow-2xl space-y-4 animate-in slide-in-from-top-4">
          <div className="flex items-center justify-between mb-2">
            <h3 className="text-xs font-black text-black uppercase tracking-[0.3em]">{editingId ? 'Editar Cliente' : 'Novo Cliente'}</h3>
            <UserPlus size={16} className="text-gray-300" />
          </div>
          <input type="text" placeholder="Nome Completo" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newCustomer.name} onChange={e => setNewCustomer({...newCustomer, name: e.target.value})} required />
          <div className="grid grid-cols-2 gap-4">
            <input type="tel" placeholder="WhatsApp" className="bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newCustomer.phone} onChange={e => setNewCustomer({...newCustomer, phone: e.target.value})} required />
            <input type="date" className="bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newCustomer.birthday} onChange={e => setNewCustomer({...newCustomer, birthday: e.target.value})} />
          </div>
          <input type="email" placeholder="E-mail" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newCustomer.email} onChange={e => setNewCustomer({...newCustomer, email: e.target.value})} />
          <div className="relative">
            <Instagram size={14} className="absolute left-6 top-1/2 -translate-y-1/2 text-pink-400" />
            <input type="text" placeholder="instagram (sem @)" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 pl-12 pr-6 text-xs font-bold text-black outline-none" value={newCustomer.instagram} onChange={e => setNewCustomer({...newCustomer, instagram: e.target.value})} />
          </div>
          <button type="submit" disabled={isSaving} className="w-full bg-black text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-xl active:scale-[0.98] transition-all">
            {isSaving ? 'Gravando...' : editingId ? 'Salvar Alterações' : 'Confirmar Cliente'}
          </button>
        </form>
      )}

      <div className="bg-white rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden divide-y divide-gray-50">
        {loading ? (
          <div className="p-16 text-center text-gray-300 text-xs font-black uppercase tracking-widest animate-pulse">Sincronizando Base...</div>
        ) : filtered.length > 0 ? (
          filtered.map(customer => {
            const isBday = isTodayBirthday(customer.birthday);
            return (
              <div key={customer.id} className="p-2 transition-all">
                <div className={`p-4 flex items-center justify-between rounded-3xl ${selectedCustomerId === customer.id ? 'bg-gray-50 shadow-inner' : 'bg-white hover:bg-gray-50/50'}`}>
                  <div className="flex items-center gap-4 flex-1 cursor-pointer" onClick={() => fetchHistory(customer.id)}>
                    <div className={`w-14 h-14 rounded-full flex items-center justify-center font-black text-lg border-4 shadow-sm relative ${isBday ? 'bg-pink-500 text-white border-pink-100 animate-bounce' : 'bg-black text-white border-gray-50'}`}>
                      {customer.name.charAt(0).toUpperCase()}
                      {isBday && <Gift size={14} className="absolute -top-1 -right-1 text-pink-500 bg-white rounded-full p-0.5" />}
                    </div>
                    <div className="min-w-0">
                      <p className="text-xs font-black text-black uppercase tracking-tight">{customer.name}</p>
                      <div className="flex items-center gap-2 mt-1">
                        <span className="text-[8px] font-bold text-gray-400 tracking-widest uppercase">{customer.instagram ? `@${customer.instagram}` : 'Sem IG'}</span>
                        {isBday && <span className="text-[8px] font-black text-pink-500 uppercase tracking-widest">Aniversário Hoje! ✨</span>}
                      </div>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button 
                      onClick={() => startEdit(customer)}
                      className="w-10 h-10 bg-white border border-gray-100 rounded-xl flex items-center justify-center text-gray-200 hover:text-black transition-all"
                    >
                      <Edit2 size={16} />
                    </button>
                    <button 
                      onClick={() => openWhatsApp(customer.phone, customer.name, isBday)}
                      className={`w-11 h-11 rounded-xl flex items-center justify-center transition-all shadow-sm ${isBday ? 'bg-pink-500 text-white' : 'bg-white border border-gray-100 text-black hover:bg-black hover:text-white'}`}
                    >
                      {isBday ? <Gift size={20}/> : <MessageCircle size={20} />}
                    </button>
                    <button onClick={() => fetchHistory(customer.id)} className={`w-11 h-11 bg-white border border-gray-100 rounded-xl flex items-center justify-center transition-all ${selectedCustomerId === customer.id ? 'rotate-90 bg-black text-white' : ''}`}>
                      <ChevronRight size={18} />
                    </button>
                  </div>
                </div>

                {selectedCustomerId === customer.id && (
                  <div className="px-4 pb-6 pt-2 space-y-4 animate-in slide-in-from-top-2 duration-300">
                    <div className="h-px bg-gray-100 mx-4 border-t border-dashed border-gray-200"></div>

                    {/* Dashboard CRM da Cliente */}
                    {(() => {
                      const metrics = calculateMetrics(customerSales);
                      return (
                        <div className="grid grid-cols-3 gap-3">
                          <div className="bg-white p-4 rounded-[1.5rem] border border-gray-100 shadow-sm text-center">
                            <Gem size={12} className="text-purple-300 mx-auto mb-1 opacity-50" />
                            <p className="text-[8px] font-black text-gray-300 uppercase mb-1">Lifetime Value</p>
                            <p className="text-sm font-black text-black">R$ {metrics.totalValue.toFixed(0)}</p>
                          </div>
                          <div className="bg-white p-4 rounded-[1.5rem] border border-gray-100 shadow-sm text-center">
                            <Star size={12} className="text-amber-300 mx-auto mb-1 opacity-50" />
                            <p className="text-[8px] font-black text-gray-300 uppercase mb-1">Ticket Médio</p>
                            <p className="text-sm font-black text-black">R$ {metrics.avgTicket.toFixed(0)}</p>
                          </div>
                          <div className="bg-white p-4 rounded-[1.5rem] border border-gray-100 shadow-sm text-center">
                            <History size={12} className="text-emerald-300 mx-auto mb-1 opacity-50" />
                            <p className="text-[8px] font-black text-gray-300 uppercase mb-1">Frequência</p>
                            <p className="text-sm font-black text-black">{metrics.frequency}x</p>
                          </div>

                          {/* Alerta de Inatividade */}
                          <div className={`col-span-3 p-3 rounded-2xl border flex items-center justify-between px-5 ${
                            metrics.daysInactive > 60 ? 'bg-red-50 border-red-100 text-red-500' :
                            metrics.daysInactive > 30 ? 'bg-amber-50 border-amber-100 text-amber-600' :
                            'bg-emerald-50 border-emerald-100 text-emerald-600'
                          }`}>
                            <div className="flex items-center gap-2">
                              <Clock size={14} />
                              <span className="text-[9px] font-black uppercase tracking-widest">
                                {metrics.daysInactive === 0 ? 'Comprou hoje!' : `Última compra há ${metrics.daysInactive} dias`}
                              </span>
                            </div>
                            <span className="text-[8px] font-black uppercase bg-white/50 px-3 py-1 rounded-full">
                              {metrics.daysInactive > 60 ? 'Risco de Perda' : metrics.daysInactive > 30 ? 'Atenção' : 'Fiel / Ativa'}
                            </span>
                          </div>
                        </div>
                      );
                    })()}

                    <div className="bg-white rounded-[2rem] p-6 border border-gray-100 shadow-xl space-y-4">
                      <div className="flex items-center justify-between">
                        <h4 className="text-[10px] font-black text-black uppercase tracking-[0.2em] flex items-center gap-2">
                          <Crown size={16} className="text-amber-500" /> 
                          Pedidos Realizados
                        </h4>
                        <div className="h-2 w-2 rounded-full bg-purple-500"></div>
                      </div>

                      {customerSales.length > 0 ? (
                        <div className="space-y-3">
                          {customerSales.map(s => (
                            <div key={s.id} className="flex justify-between items-center group bg-gray-50/50 p-3 rounded-2xl border border-gray-50">
                              <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center">
                                  <ArrowUpRight size={16} className="text-emerald-500" />
                                </div>
                                <div>
                                  <p className="text-[10px] font-black text-black uppercase truncate max-w-[120px]">{s.product?.name}</p>
                                  <p className="text-[8px] text-gray-400 font-bold uppercase tracking-widest">{new Date(s.created_at).toLocaleDateString()}</p>
                                </div>
                              </div>
                              <div className="text-right">
                                <p className="text-[10px] font-black text-emerald-600">R$ {Number(s.value).toFixed(2)}</p>
                                <p className="text-[8px] font-bold text-gray-300 uppercase">{s.amount} un.</p>
                              </div>
                            </div>
                          ))}
                        </div>
                      ) : (
                        <div className="py-10 text-center space-y-2">
                          <div className="bg-gray-50 w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-2 border border-gray-100">
                            <ReceiptText size={18} className="text-gray-300" />
                          </div>
                          <p className="text-[9px] text-gray-300 font-bold uppercase tracking-widest">Nenhuma compra registrada</p>
                        </div>
                      )}
                    </div>
                  </div>
                )}
              </div>
            );
          })
        ) : (
          <div className="p-20 text-center text-gray-300 text-[10px] font-black uppercase tracking-[0.3em]">Nenhuma cliente no momento.</div>
        )}
      </div>
    </div>
  );
};

