import React, { useState, useEffect } from 'react';
import { 
  ArrowLeft, 
  TrendingUp, 
  DollarSign, 
  Info, 
  Target, 
  ArrowUp, 
  ArrowDown, 
  Settings2, 
  BarChart3, 
  Gem, 
  AlertTriangle, 
  Trophy, 
  Package,
  Search,
  ChevronDown
} from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Sale, Product } from '../types';

interface AnalyticsProps {
  onBack: () => void;
}

type FilterType = 'total' | 'mensal' | 'periodo';

interface ProductStats {
  product: Product;
  margin: number;
  totalSold: number;
  totalRevenue: number;
}

const Analytics: React.FC<AnalyticsProps> = ({ onBack }) => {
  const [loading, setLoading] = useState(true);
  const [filterType, setFilterType] = useState<FilterType>('mensal');
  const [customDates, setCustomDates] = useState({
    start: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0]
  });

  const [totals, setTotals] = useState({ 
    revenue: 0, 
    cogs: 0, 
    netProfit: 0, 
    prevRevenue: 0,
    prevNetProfit: 0 
  });

  const [chartData, setChartData] = useState<{label: string, amount: number}[]>([]);
  const [idealProfitGoal, setIdealProfitGoal] = useState<number>(() => {
    return Number(localStorage.getItem('sensitive_ideal_profit') || 5000);
  });
  const [showGoalInput, setShowGoalInput] = useState(false);

  // Estados de Rankings e Produto Selecionado
  const [topProfitable, setTopProfitable] = useState<ProductStats[]>([]);
  const [bottomProfitable, setBottomProfitable] = useState<ProductStats[]>([]);
  const [allProducts, setAllProducts] = useState<Product[]>([]);
  const [selectedProductId, setSelectedProductId] = useState<string>('');
  const [productMonthlyStats, setProductMonthlyStats] = useState<{month: string, qty: number}[]>([]);
  const [allSales, setAllSales] = useState<Sale[]>([]);

  useEffect(() => {
    fetchAnalytics();
  }, [filterType, customDates]);

  const fetchAnalytics = async () => {
    setLoading(true);
    try {
      const { data: salesData } = await supabase.from('sales').select('*, product:products(*)');
      const { data: productsData } = await supabase.from('products').select('*');

      if (salesData && productsData) {
        setAllSales(salesData as Sale[]);
        setAllProducts(productsData as Product[]);

        const now = new Date();
        let startDate: Date;
        let endDate: Date = new Date();
        let compareStartDate: Date;
        let compareEndDate: Date;

        if (filterType === 'mensal') {
          startDate = new Date(now.getFullYear(), now.getMonth(), 1);
          compareStartDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
          compareEndDate = new Date(now.getFullYear(), now.getMonth(), 0);
        } else if (filterType === 'periodo') {
          startDate = new Date(customDates.start);
          endDate = new Date(customDates.end);
          endDate.setHours(23, 59, 59);
          const diff = endDate.getTime() - startDate.getTime();
          compareEndDate = new Date(startDate.getTime() - 1);
          compareStartDate = new Date(compareEndDate.getTime() - diff);
        } else {
          startDate = new Date(0);
          compareStartDate = new Date(0);
          compareEndDate = new Date(0);
        }

        let currentRev = 0;
        let currentCogs = 0;
        let prevRev = 0;
        let prevNet = 0;
        const timelineMap: Record<string, number> = {};

        // Processamento para rankings e métricas
        const statsMap: Record<string, ProductStats> = {};

        salesData.forEach((sale: any) => {
          const product = sale.product;
          if (!product) return;

          const saleDate = new Date(sale.created_at);
          const rev = Number(sale.value);
          const cost = Number(product.purchase_price) * Number(sale.amount);
          const profit = rev - cost;

          // Rankings (Geral)
          if (!statsMap[product.id]) {
            statsMap[product.id] = {
              product,
              margin: product.price - product.purchase_price,
              totalSold: 0,
              totalRevenue: 0
            };
          }
          statsMap[product.id].totalSold += Number(sale.amount);
          statsMap[product.id].totalRevenue += rev;

          // Métricas de Período
          if (saleDate >= startDate && saleDate <= endDate) {
            currentRev += rev;
            currentCogs += cost;
            const label = filterType === 'total' 
              ? saleDate.toLocaleString('pt-BR', { month: 'short', year: '2-digit' })
              : saleDate.getDate().toString();
            timelineMap[label] = (timelineMap[label] || 0) + profit;
          } else if (saleDate >= compareStartDate && saleDate <= compareEndDate) {
            prevRev += rev;
            prevNet += profit;
          }
        });

        // Ordenar Rankings
        const sortedProducts = Object.values(statsMap).sort((a, b) => b.margin - a.margin);
        setTopProfitable(sortedProducts.slice(0, 5));
        setBottomProfitable([...sortedProducts].reverse().slice(0, 5));

        // Gráfico Geral
        let accumulated = 0;
        const evolution = Object.entries(timelineMap)
          .sort((a, b) => filterType === 'total' ? 0 : Number(a[0]) - Number(b[0]))
          .map(([label, profit]) => {
            accumulated += profit;
            return { label, amount: filterType === 'total' ? profit : accumulated };
          });

        setChartData(evolution);
        setTotals({ 
          revenue: currentRev, 
          cogs: currentCogs, 
          netProfit: currentRev - currentCogs,
          prevRevenue: prevRev,
          prevNetProfit: prevNet
        });
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  // Efeito para carregar performance de produto específico
  useEffect(() => {
    if (!selectedProductId) {
      setProductMonthlyStats([]);
      return;
    }

    const stats: Record<string, number> = {};
    allSales
      .filter(s => s.product_id === selectedProductId)
      .forEach(s => {
        const date = new Date(s.created_at);
        const key = date.toLocaleString('pt-BR', { month: 'short' });
        stats[key] = (stats[key] || 0) + Number(s.amount);
      });

    setProductMonthlyStats(Object.entries(stats).map(([month, qty]) => ({ month, qty })));
  }, [selectedProductId, allSales]);

  const handleSaveGoal = () => {
    localStorage.setItem('sensitive_ideal_profit', idealProfitGoal.toString());
    setShowGoalInput(false);
  };

  const revVariation = totals.prevRevenue > 0 ? ((totals.revenue - totals.prevRevenue) / totals.prevRevenue) * 100 : 0;
  const profitVariation = totals.prevNetProfit > 0 ? ((totals.netProfit - totals.prevNetProfit) / totals.prevNetProfit) * 100 : 0;
  const goalProgress = Math.min(100, (totals.netProfit / idealProfitGoal) * 100);

  const maxAmount = Math.max(...chartData.map(d => d.amount), 1);
  const chartPoints = chartData.map((d, i) => {
    const x = (i / (chartData.length - 1 || 1)) * 100;
    const y = 100 - (d.amount / maxAmount) * 100;
    return `${x},${y}`;
  }).join(' ');

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex items-center justify-between">
        <button onClick={onBack} className="flex items-center gap-2 text-gray-400 hover:text-black transition-colors">
          <ArrowLeft size={16} />
          <span className="text-[10px] font-black uppercase tracking-widest">Dashboard</span>
        </button>
        <button 
          onClick={() => setShowGoalInput(!showGoalInput)}
          className="p-3 bg-purple-50 text-purple-600 rounded-2xl hover:bg-purple-100 transition-colors"
        >
          <Settings2 size={18} />
        </button>
      </div>

      <div className="space-y-1">
        <h2 className="text-2xl font-black text-black uppercase tracking-tighter">Boutique Intelligence</h2>
        <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest leading-relaxed">Sua margem é seu poder.</p>
      </div>

      {/* Métricas Principais */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-gray-50 rounded-[2rem] p-6 border border-gray-100 space-y-3">
          <div className="flex justify-between items-start">
            <DollarSign size={18} className="text-gray-400" />
            {filterType !== 'total' && (
              <div className={`flex items-center gap-0.5 text-[8px] font-black uppercase ${revVariation >= 0 ? 'text-emerald-500' : 'text-red-500'}`}>
                {revVariation >= 0 ? <ArrowUp size={10} /> : <ArrowDown size={10} />}
                {Math.abs(revVariation).toFixed(1)}%
              </div>
            )}
          </div>
          <div>
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-0.5">Faturamento</p>
            <p className="text-lg font-black text-black">R$ {totals.revenue.toLocaleString('pt-BR')}</p>
          </div>
        </div>

        <div className="bg-emerald-50 rounded-[2rem] p-6 border border-emerald-100 space-y-3">
          <div className="flex justify-between items-start">
            <TrendingUp size={18} className="text-emerald-600" />
            {filterType !== 'total' && (
              <div className={`flex items-center gap-0.5 text-[8px] font-black uppercase ${profitVariation >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>
                {profitVariation >= 0 ? <ArrowUp size={10} /> : <ArrowDown size={10} />}
                {Math.abs(profitVariation).toFixed(1)}%
              </div>
            )}
          </div>
          <div>
            <p className="text-[9px] font-black text-emerald-800/40 uppercase tracking-widest mb-0.5">Lucro Líquido</p>
            <p className="text-lg font-black text-emerald-600">R$ {totals.netProfit.toLocaleString('pt-BR')}</p>
          </div>
        </div>
      </div>

      {/* Seletor de Filtro */}
      <div className="bg-[#f8f5ff] p-1.5 rounded-[2rem] flex gap-1 shadow-inner border border-purple-50">
        {(['total', 'mensal', 'periodo'] as FilterType[]).map((t) => (
          <button
            key={t}
            onClick={() => setFilterType(t)}
            className={`flex-1 py-3 rounded-[1.5rem] text-[9px] font-black uppercase tracking-widest transition-all ${
              filterType === t 
                ? 'bg-black text-white shadow-xl scale-[1.02]' 
                : 'text-purple-300 hover:text-purple-500'
            }`}
          >
            {t === 'periodo' ? 'Por Período' : t}
          </button>
        ))}
      </div>

      {/* Rankings de Lucratividade */}
      <div className="space-y-4">
        <h3 className="text-[10px] font-black text-black uppercase tracking-[0.3em] flex items-center gap-2 px-2">
          <Trophy size={14} className="text-amber-500" /> Rankings de Lucratividade
        </h3>

        <div className="grid grid-cols-1 gap-4">
          {/* Top 5 Profitable */}
          <div className="bg-white rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden">
            <div className="bg-emerald-50 px-6 py-4 flex items-center gap-2 border-b border-emerald-100/50">
              <Gem size={14} className="text-emerald-600" />
              <span className="text-[9px] font-black text-emerald-600 uppercase tracking-widest">Top 5 Joias (Mais Lucrativos)</span>
            </div>
            <div className="divide-y divide-gray-50">
              {topProfitable.map((item, idx) => (
                <div key={idx} className="px-6 py-4 flex justify-between items-center group">
                  <div className="flex items-center gap-3">
                    <span className="text-[10px] font-black text-gray-200">#0{idx+1}</span>
                    <div className="min-w-0">
                      <p className="text-[10px] font-black text-black uppercase truncate max-w-[120px]">{item.product.name}</p>
                      <p className="text-[8px] text-gray-400 font-bold uppercase">Ref: {item.product.reference_code}</p>
                    </div>
                  </div>
                  <div className="bg-emerald-100 px-3 py-1 rounded-full">
                    <p className="text-[9px] font-black text-emerald-700">+ R$ {item.margin.toFixed(0)}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Bottom 5 Profitable */}
          <div className="bg-white rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden">
            <div className="bg-red-50 px-6 py-4 flex items-center gap-2 border-b border-red-100/50">
              <AlertTriangle size={14} className="text-red-400" />
              <span className="text-[9px] font-black text-red-400 uppercase tracking-widest">Oportunidades (Baixa Margem)</span>
            </div>
            <div className="divide-y divide-gray-50">
              {bottomProfitable.map((item, idx) => (
                <div key={idx} className="px-6 py-4 flex justify-between items-center">
                  <div className="flex items-center gap-3">
                    <span className="text-[10px] font-black text-gray-200">#0{idx+1}</span>
                    <div className="min-w-0">
                      <p className="text-[10px] font-black text-black uppercase truncate max-w-[120px]">{item.product.name}</p>
                      <p className="text-[8px] text-gray-400 font-bold uppercase">Ref: {item.product.reference_code}</p>
                    </div>
                  </div>
                  <div className="bg-red-50 px-3 py-1 rounded-full">
                    <p className="text-[9px] font-black text-red-500">R$ {item.margin.toFixed(0)}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Análise por Produto Único */}
      <div className="bg-gray-50 rounded-[2.5rem] p-8 border border-gray-100 space-y-6">
        <div className="space-y-4">
          <h3 className="text-[10px] font-black text-black uppercase tracking-[0.3em] flex items-center gap-2">
            <Package size={14} className="text-purple-500" /> Performance por Peça
          </h3>

          <div className="relative">
            <select 
              value={selectedProductId}
              onChange={(e) => setSelectedProductId(e.target.value)}
              className="w-full bg-white border border-gray-200 rounded-2xl py-4 px-6 text-[10px] font-black uppercase tracking-widest text-black outline-none appearance-none shadow-sm focus:border-purple-400 transition-all"
            >
              <option value="">Selecione um Produto para Ver Giro</option>
              {allProducts.map(p => (
                <option key={p.id} value={p.id}>{p.name} ({p.reference_code})</option>
              ))}
            </select>
            <ChevronDown size={14} className="absolute right-6 top-1/2 -translate-y-1/2 text-gray-300 pointer-events-none" />
          </div>
        </div>

        {selectedProductId ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2">
            <div className="bg-white p-6 rounded-3xl shadow-inner border border-gray-100">
               <div className="flex justify-between items-center mb-6">
                 <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Saídas Mensais (Unidades)</p>
                 <BarChart3 size={14} className="text-purple-300" />
               </div>

               <div className="h-32 flex items-end justify-between gap-3 px-2">
                 {productMonthlyStats.length > 0 ? productMonthlyStats.map((s, idx) => {
                   const max = Math.max(...productMonthlyStats.map(m => m.qty), 1);
                   const height = (s.qty / max) * 100;
                   return (
                     <div key={idx} className="flex-1 flex flex-col items-center gap-2 group">
                       <div 
                         style={{ height: `${height}%` }}
                         className="w-full bg-purple-100 group-hover:bg-purple-500 transition-all rounded-lg relative"
                       >
                         <div className="absolute -top-6 left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity bg-black text-white text-[8px] font-black py-1 px-2 rounded">
                           {s.qty}
                         </div>
                       </div>
                       <span className="text-[8px] font-black text-gray-300 uppercase">{s.month}</span>
                     </div>
                   );
                 }) : (
                   <div className="w-full h-full flex items-center justify-center text-[8px] font-black text-gray-200 uppercase tracking-widest">Sem vendas registradas</div>
                 )}
               </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="bg-white p-5 rounded-3xl border border-gray-100 text-center">
                <p className="text-[8px] font-black text-gray-300 uppercase mb-1">Total Vendido</p>
                <p className="text-sm font-black text-black">
                  {productMonthlyStats.reduce((acc, s) => acc + s.qty, 0)} Peças
                </p>
              </div>
              <div className="bg-white p-5 rounded-3xl border border-gray-100 text-center">
                <p className="text-[8px] font-black text-gray-300 uppercase mb-1">Giro Mensal</p>
                <p className="text-sm font-black text-black">
                  {(productMonthlyStats.reduce((acc, s) => acc + s.qty, 0) / Math.max(productMonthlyStats.length, 1)).toFixed(1)} un/mês
                </p>
              </div>
            </div>
          </div>
        ) : (
          <div className="py-12 text-center space-y-3">
             <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto border border-dashed border-gray-200">
               <Search size={24} className="text-gray-100" />
             </div>
             <p className="text-[9px] font-black text-gray-300 uppercase tracking-widest">Selecione uma peça acima para ver o BI individual</p>
          </div>
        )}
      </div>

      {/* Gráfico Geral */}
      <div className="bg-gray-950 rounded-[2.5rem] p-8 text-white shadow-2xl space-y-8 relative overflow-hidden">
        <div className="flex justify-between items-center relative z-10">
          <h3 className="text-xs font-black uppercase tracking-[0.2em] flex items-center gap-2 text-white/50">
            <BarChart3 size={14} className="text-purple-400" /> 
            Evolução de Lucro
          </h3>
          <span className="text-[9px] font-black text-purple-400 uppercase tracking-widest">
            {filterType === 'mensal' ? 'Este Mês' : filterType === 'total' ? 'Histórico' : 'Período'}
          </span>
        </div>

        <div className="h-40 w-full relative z-10">
          {chartData.length > 1 ? (
            <svg className="w-full h-full" viewBox="0 0 100 100" preserveAspectRatio="none">
              <defs>
                <linearGradient id="lineGrad" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#A855F7" stopOpacity="0.4" />
                  <stop offset="100%" stopColor="#A855F7" stopOpacity="0" />
                </linearGradient>
              </defs>
              <polyline
                fill="none"
                stroke="#A855F7"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
                points={chartPoints}
              />
              <path
                fill="url(#lineGrad)"
                d={`M 0,100 L ${chartPoints} L 100,100 Z`}
              />
            </svg>
          ) : (
            <div className="h-full flex items-center justify-center text-[10px] font-black text-white/20 uppercase tracking-widest">
              Aguardando dados...
            </div>
          )}
        </div>

        <div className="flex justify-between items-end relative z-10">
          <div className="space-y-1">
            <p className="text-[8px] font-black text-white/30 uppercase tracking-widest">Margem Operacional</p>
            <p className="text-xl font-black">
              {totals.revenue > 0 ? ((totals.netProfit / totals.revenue) * 100).toFixed(1) : 0}%
            </p>
          </div>
          <div className="text-right">
            <p className="text-[8px] font-black text-white/30 uppercase tracking-widest">Custo de Mercadoria</p>
            <p className="text-sm font-black text-red-400">- R$ {totals.cogs.toLocaleString('pt-BR')}</p>
          </div>
        </div>
      </div>
    </div>
  );
};

