export default Analytics;

import React, { useState, useEffect } from 'react';
import { 
  ArrowLeft, 
  TrendingUp, 
  DollarSign, 
  ArrowUp, 
  ArrowDown, 
  Settings2, 
  BarChart3, 
  Gem, 
  AlertTriangle, 
  Trophy, 
  Package,
  Search,
  ChevronDown,
  X,
  LineChart,
  Target,
  CheckCircle2,
  TrendingDown
} from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Sale, Product } from '../types';

interface AnalyticsProps {
  onBack: () => void;
}

type FilterType = 'total' | 'mensal' | 'periodo';

interface ProductStats {
  product: Product;
  margin: number;
  totalSold: number;
  totalRevenue: number;
}

const Analytics: React.FC<AnalyticsProps> = ({ onBack }) => {
  const [loading, setLoading] = useState(true);
  const [filterType, setFilterType] = useState<FilterType>('mensal');
  const [customDates, setCustomDates] = useState({
    start: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0]
  });

  const [totals, setTotals] = useState({ 
    revenue: 0, 
    cogs: 0, 
    netProfit: 0, 
    prevRevenue: 0,
    prevNetProfit: 0 
  });

  const [chartData, setChartData] = useState<{label: string, amount: number}[]>([]);
  const [idealProfitGoal, setIdealProfitGoal] = useState<number>(() => {
    return Number(localStorage.getItem('sensitive_ideal_profit') || 5000);
  });
  const [showGoalInput, setShowGoalInput] = useState(false);
  const [newGoalValue, setNewGoalValue] = useState(idealProfitGoal.toString());

  // Sincroniza o valor do input quando a meta muda ou o painel abre
  useEffect(() => {
    if (showGoalInput) {
      setNewGoalValue(idealProfitGoal.toString());
    }
  }, [showGoalInput, idealProfitGoal]);

  // Estados de Rankings e Comparativos
  const [topProfitable, setTopProfitable] = useState<ProductStats[]>([]);
  const [bottomProfitable, setBottomProfitable] = useState<ProductStats[]>([]);
  const [allProducts, setAllProducts] = useState<Product[]>([]);
  const [allSales, setAllSales] = useState<Sale[]>([]);
  const [productId1, setProductId1] = useState<string>('');
  const [productId2, setProductId2] = useState<string>('');
  const [comparisonData, setComparisonData] = useState<{month: string, qty1: number, qty2: number}[]>([]);

  useEffect(() => {
    fetchAnalytics();
  }, [filterType, customDates]);

  const fetchAnalytics = async () => {
    setLoading(true);
    try {
      const { data: salesData } = await supabase.from('sales').select('*, product:products(*)');
      const { data: productsData } = await supabase.from('products').select('*');

      if (salesData && productsData) {
        setAllSales(salesData as Sale[]);
        setAllProducts(productsData as Product[]);

        const now = new Date();
        let startDate: Date;
        let endDate: Date = new Date();
        let compareStartDate: Date;
        let compareEndDate: Date;

        if (filterType === 'mensal') {
          startDate = new Date(now.getFullYear(), now.getMonth(), 1);
          compareStartDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
          compareEndDate = new Date(now.getFullYear(), now.getMonth(), 0);
        } else if (filterType === 'periodo') {
          startDate = new Date(customDates.start);
          endDate = new Date(customDates.end);
          endDate.setHours(23, 59, 59);
          const diff = endDate.getTime() - startDate.getTime();
          compareEndDate = new Date(startDate.getTime() - 1);
          compareStartDate = new Date(compareEndDate.getTime() - diff);
        } else {
          startDate = new Date(0);
          compareStartDate = new Date(0);
          compareEndDate = new Date(0);
        }

        let currentRev = 0;
        let currentCogs = 0;
        let prevRev = 0;
        let prevProfit = 0;
        const timelineMap: Record<string, number> = {};
        const statsMap: Record<string, ProductStats> = {};

        salesData.forEach((sale: any) => {
          const product = sale.product;
          if (!product) return;

          const saleDate = new Date(sale.created_at);
          const rev = Number(sale.value);
          const cost = Number(product.purchase_price) * Number(sale.amount);
          const profit = rev - cost;

          if (!statsMap[product.id]) {
            statsMap[product.id] = { product, margin: product.price - product.purchase_price, totalSold: 0, totalRevenue: 0 };
          }
          statsMap[product.id].totalSold += Number(sale.amount);
          statsMap[product.id].totalRevenue += rev;

          if (saleDate >= startDate && saleDate <= endDate) {
            currentRev += rev;
            currentCogs += cost;
            const label = filterType === 'total' 
              ? saleDate.toLocaleString('pt-BR', { month: 'short', year: '2-digit' })
              : saleDate.getDate().toString();
            timelineMap[label] = (timelineMap[label] || 0) + profit;
          } else if (saleDate >= compareStartDate && saleDate <= compareEndDate) {
            prevRev += rev;
            prevProfit += profit;
          }
        });

        const sortedProducts = Object.values(statsMap).sort((a, b) => b.margin - a.margin);
        setTopProfitable(sortedProducts.slice(0, 5));
        setBottomProfitable([...sortedProducts].reverse().slice(0, 5));

        let accumulated = 0;
        const evolution = Object.entries(timelineMap)
          .sort((a, b) => filterType === 'total' ? 0 : Number(a[0]) - Number(b[0]))
          .map(([label, profit]) => {
            accumulated += profit;
            return { label, amount: filterType === 'total' ? profit : accumulated };
          });

        setChartData(evolution);
        setTotals({ 
          revenue: currentRev, 
          cogs: currentCogs, 
          netProfit: currentRev - currentCogs, 
          prevRevenue: prevRev, 
          prevNetProfit: prevProfit 
        });
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleSaveGoal = () => {
    const val = parseFloat(newGoalValue) || 0;
    setIdealProfitGoal(val);
    localStorage.setItem('sensitive_ideal_profit', val.toString());
    setShowGoalInput(false);
  };

  // Variações Temporais
  const revVariation = totals.prevRevenue > 0 ? ((totals.revenue - totals.prevRevenue) / totals.prevRevenue) * 100 : 0;
  const profitVariation = totals.prevNetProfit > 0 ? ((totals.netProfit - totals.prevNetProfit) / totals.prevNetProfit) * 100 : 0;

  // Barra de Progresso da Meta
  const goalProgress = Math.min(100, (totals.netProfit / (idealProfitGoal || 1)) * 100);
  const gapToGoal = Math.max(0, idealProfitGoal - totals.netProfit);

  // Gráfico Comparativo de Giro
  useEffect(() => {
    if (!productId1 && !productId2) {
      setComparisonData([]);
      return;
    }
    const monthOrder = ['jan', 'fev', 'mar', 'abr', 'mai', 'jun', 'jul', 'ago', 'set', 'out', 'nov', 'dez'];
    const stats1: Record<string, number> = {};
    const stats2: Record<string, number> = {};
    const monthsFound = new Set<string>();
    allSales.forEach(s => {
      const date = new Date(s.created_at);
      const monthName = date.toLocaleString('pt-BR', { month: 'short' }).replace('.', '').toLowerCase();
      if (s.product_id === productId1) { stats1[monthName] = (stats1[monthName] || 0) + Number(s.amount); monthsFound.add(monthName); }
      if (s.product_id === productId2) { stats2[monthName] = (stats2[monthName] || 0) + Number(s.amount); monthsFound.add(monthName); }
    });
    const sortedMonths = Array.from(monthsFound).sort((a, b) => monthOrder.indexOf(a) - monthOrder.indexOf(b));
    setComparisonData(sortedMonths.map(month => ({ month, qty1: stats1[month] || 0, qty2: stats2[month] || 0 })));
  }, [productId1, productId2, allSales]);

  const maxAmount = Math.max(...chartData.map(d => d.amount), 1);
  const chartPoints = chartData.map((d, i) => {
    const x = (i / (chartData.length - 1 || 1)) * 100;
    const y = 100 - (d.amount / maxAmount) * 100;
    return `${x},${y}`;
  }).join(' ');

  const maxQty = Math.max(...comparisonData.map(d => Math.max(d.qty1, d.qty2)), 1);
  const points1 = comparisonData.map((d, i) => `${(i / (comparisonData.length - 1 || 1)) * 100},${100 - (d.qty1 / maxQty) * 100}`).join(' ');
  const points2 = comparisonData.map((d, i) => `${(i / (comparisonData.length - 1 || 1)) * 100},${100 - (d.qty2 / maxQty) * 100}`).join(' ');

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex items-center justify-between">
        <button onClick={onBack} className="flex items-center gap-2 text-gray-400 hover:text-black transition-colors">
          <ArrowLeft size={16} />
          <span className="text-[10px] font-black uppercase tracking-widest">Painel de Controle</span>
        </button>
        <button 
          onClick={() => setShowGoalInput(!showGoalInput)} 
          className={`p-3 rounded-2xl transition-all shadow-lg ${showGoalInput ? 'bg-black text-white' : 'bg-purple-50 text-purple-600'}`}
        >
          <Target size={20} />
        </button>
      </div>

      <div className="space-y-1">
        <h2 className="text-2xl font-black text-black uppercase tracking-tighter">Boutique Intelligence</h2>
        <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Análise de Lucratividade Real</p>
      </div>

      {/* Aba de Ajuste de Meta (Lucro Ideal) */}
      {showGoalInput && (
        <div className="bg-white border-4 border-black p-8 rounded-[2.5rem] shadow-2xl animate-in slide-in-from-top-4 duration-300 space-y-6 relative z-50">
          <div className="flex justify-between items-center">
            <div className="space-y-1">
              <p className="text-[10px] font-black uppercase tracking-widest text-black">Configuração Estratégica</p>
              <h4 className="text-lg font-black text-black uppercase">Definir Lucro Ideal</h4>
            </div>
            <button onClick={() => setShowGoalInput(false)} className="text-gray-300 hover:text-black"><X size={20} /></button>
          </div>

          <div className="space-y-4">
            <div className="relative">
              <span className="absolute left-6 top-1/2 -translate-y-1/2 text-lg font-black text-gray-300">R$</span>
              <input 
                type="number"
                step="100"
                autoFocus
                className="w-full bg-gray-50 border-2 border-gray-100 rounded-[1.5rem] py-6 pl-16 pr-6 text-2xl font-black text-black outline-none focus:border-purple-400 transition-all"
                value={newGoalValue}
                onChange={e => setNewGoalValue(e.target.value)}
                placeholder="0.00"
              />
            </div>
            <button 
              onClick={handleSaveGoal}
              className="w-full bg-black text-white py-5 rounded-[1.5rem] font-black text-xs uppercase tracking-[0.3em] shadow-xl hover:scale-[1.02] active:scale-95 transition-all"
            >
              Confirmar Objetivo
            </button>
          </div>
        </div>
      )}

      {/* Filtro Temporal */}
      <div className="bg-gray-100 p-1.5 rounded-[2rem] flex gap-1 shadow-inner border border-gray-200/50">
        {(['mensal', 'periodo', 'total'] as FilterType[]).map((t) => (
          <button
            key={t}
            onClick={() => setFilterType(t)}
            className={`flex-1 py-3.5 rounded-[1.5rem] text-[9px] font-black uppercase tracking-widest transition-all ${
              filterType === t 
                ? 'bg-white text-black shadow-xl scale-[1.02]' 
                : 'text-gray-400 hover:text-gray-600'
            }`}
          >
            {t === 'periodo' ? 'Personalizado' : t}
          </button>
        ))}
      </div>

      {/* Métricas com Comparativo Automático */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white rounded-[2rem] p-6 border border-gray-100 shadow-sm space-y-3">
          <div className="flex justify-between items-start">
            <div className="p-2 bg-gray-50 rounded-xl text-gray-400"><DollarSign size={16} /></div>
            <div className={`flex items-center gap-0.5 text-[9px] font-black uppercase ${revVariation >= 0 ? 'text-emerald-500' : 'text-red-500'}`}>
              {revVariation >= 0 ? <TrendingUp size={12} /> : <TrendingDown size={12} />}
              {Math.abs(revVariation).toFixed(1)}%
            </div>
          </div>
          <div>
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-0.5">Faturamento Bruto</p>
            <p className="text-xl font-black text-black">R$ {totals.revenue.toLocaleString('pt-BR')}</p>
            <p className="text-[7px] font-bold text-gray-300 uppercase mt-1">Comparado ao período anterior</p>
          </div>
        </div>

        <div className="bg-emerald-50 rounded-[2rem] p-6 border border-emerald-100 shadow-sm space-y-3">
          <div className="flex justify-between items-start">
            <div className="p-2 bg-emerald-100 text-emerald-600 rounded-xl"><TrendingUp size={16} /></div>
            <div className={`flex items-center gap-0.5 text-[9px] font-black uppercase ${profitVariation >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>
              {profitVariation >= 0 ? <TrendingUp size={12} /> : <TrendingDown size={12} />}
              {Math.abs(profitVariation).toFixed(1)}%
            </div>
          </div>
          <div>
            <p className="text-[9px] font-black text-emerald-800/40 uppercase tracking-widest mb-0.5">Lucro Líquido</p>
            <p className="text-xl font-black text-emerald-600">R$ {totals.netProfit.toLocaleString('pt-BR')}</p>
            <p className="text-[7px] font-bold text-emerald-400/40 uppercase mt-1">Margem: {totals.revenue > 0 ? ((totals.netProfit / totals.revenue) * 100).toFixed(1) : 0}%</p>
          </div>
        </div>
      </div>

      {/* Comparativo: Lucro Ideal vs Alcançado */}
      <div className="bg-white rounded-[2.5rem] p-8 border border-gray-100 shadow-xl space-y-6">
        <div className="flex justify-between items-end">
          <div className="space-y-1">
            <h3 className="text-[10px] font-black text-black uppercase tracking-[0.3em] flex items-center gap-2">
              <Target size={16} className="text-purple-500" /> Meta Estratégica
            </h3>
            <p className="text-[9px] font-bold text-gray-400 uppercase tracking-widest">Comparativo Lucro Ideal vs Real</p>
          </div>
          <div className="text-right">
            <p className="text-3xl font-black text-black">{goalProgress.toFixed(0)}%</p>
          </div>
        </div>

        <div className="relative h-8 w-full bg-gray-100 rounded-full overflow-hidden border border-gray-200">
          <div 
            className="absolute left-0 top-0 h-full bg-gradient-to-r from-purple-600 to-purple-400 transition-all duration-1000 ease-out flex items-center justify-end px-3 shadow-lg"
            style={{ width: `${goalProgress}%` }}
          >
            {goalProgress > 10 && <div className="h-2 w-2 bg-white rounded-full animate-pulse"></div>}
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4 pt-2">
          <div className="p-4 bg-gray-50 rounded-2xl border border-gray-100">
            <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest mb-1">Lucro Planejado</p>
            <p className="text-md font-black text-black">R$ {idealProfitGoal.toLocaleString('pt-BR')}</p>
          </div>
          <div className={`p-4 rounded-2xl border ${gapToGoal === 0 ? 'bg-emerald-50 border-emerald-100' : 'bg-purple-50 border-purple-100'}`}>
            <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest mb-1">{gapToGoal === 0 ? 'Status' : 'Faltam'}</p>
            <p className={`text-md font-black ${gapToGoal === 0 ? 'text-emerald-600' : 'text-purple-600'}`}>
              {gapToGoal === 0 ? 'META ATINGIDA! ✨' : `R$ ${gapToGoal.toLocaleString('pt-BR')}`}
            </p>
          </div>
        </div>
      </div>

      {/* Evolução do Lucro Bruto (Gráfico Principal) */}
      <div className="bg-gray-950 rounded-[2.5rem] p-8 text-white shadow-2xl space-y-8 relative overflow-hidden">
        <div className="absolute -right-20 -top-20 w-60 h-60 bg-purple-600/10 blur-[80px] rounded-full"></div>
        <div className="flex justify-between items-center relative z-10">
          <h3 className="text-xs font-black uppercase tracking-[0.2em] flex items-center gap-2 text-white/50">
            <LineChart size={14} className="text-purple-400" /> 
            Evolução de Rentabilidade
          </h3>
          <span className="text-[9px] font-black text-purple-400 uppercase tracking-widest">
            {filterType === 'mensal' ? 'Faturamento Diário' : 'Evolução Temporal'}
          </span>
        </div>

        <div className="h-44 w-full relative z-10">
          {chartData.length > 1 ? (
            <svg className="w-full h-full" viewBox="0 0 100 100" preserveAspectRatio="none">
              <defs>
                <linearGradient id="mainGrad" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#A855F7" stopOpacity="0.5" />
                  <stop offset="100%" stopColor="#A855F7" stopOpacity="0" />
                </linearGradient>
              </defs>
              <path d={`M 0,100 L ${chartPoints} L 100,100 Z`} fill="url(#mainGrad)" />
              <polyline fill="none" stroke="#A855F7" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round" points={chartPoints} />
            </svg>
          ) : (
            <div className="h-full flex items-center justify-center text-[10px] font-black text-white/20 uppercase tracking-widest">Sincronizando dados históricos...</div>
          )}
        </div>

        <div className="flex justify-between items-end relative z-10 border-t border-white/5 pt-6">
          <div className="space-y-1">
            <p className="text-[8px] font-black text-white/30 uppercase tracking-widest">Custo Operacional (Mercadoria)</p>
            <p className="text-xl font-black text-red-400">- R$ {totals.cogs.toLocaleString('pt-BR')}</p>
          </div>
          <div className="text-right space-y-1">
            <p className="text-[8px] font-black text-white/30 uppercase tracking-widest">Ticket Médio</p>
            <p className="text-xl font-black text-emerald-400">R$ {allSales.length > 0 ? (totals.revenue / allSales.length).toFixed(0) : 0}</p>
          </div>
        </div>
      </div>

      {/* Performance de Peças e Rankings */}
      <div className="space-y-4 pt-4">
        <h3 className="text-[10px] font-black text-black uppercase tracking-[0.3em] flex items-center gap-2 px-2">
          <Trophy size={16} className="text-amber-500" /> Performance por Peça
        </h3>

        <div className="grid grid-cols-1 gap-4">
          <div className="bg-white rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden">
            <div className="bg-emerald-50 px-6 py-4 flex items-center gap-2 border-b border-emerald-100/50">
              <Gem size={14} className="text-emerald-600" />
              <span className="text-[9px] font-black text-emerald-600 uppercase tracking-widest">Joias da Boutique (Top Margem)</span>
            </div>
            <div className="divide-y divide-gray-50">
              {topProfitable.map((item, idx) => (
                <div key={idx} className="px-6 py-4 flex justify-between items-center hover:bg-gray-50 transition-all">
                  <div className="flex items-center gap-3">
                    <span className="text-[10px] font-black text-gray-200">#0{idx+1}</span>
                    <div className="min-w-0">
                      <p className="text-[10px] font-black text-black uppercase truncate max-w-[140px]">{item.product.name}</p>
                      <p className="text-[8px] text-gray-400 font-bold uppercase tracking-widest">REF: {item.product.reference_code}</p>
                    </div>
                  </div>
                  <div className="bg-emerald-100 px-3 py-1 rounded-full shadow-sm">
                    <p className="text-[9px] font-black text-emerald-700">+ R$ {item.margin.toFixed(0)}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Comparador de Giro (Linha Dual) */}
      <div className="bg-white rounded-[2.5rem] p-8 border border-gray-100 shadow-xl space-y-8">
        <div className="space-y-4">
          <h3 className="text-[10px] font-black text-black uppercase tracking-[0.3em] flex items-center gap-2 px-2">
            <LineChart size={16} className="text-purple-500" /> Comparador de Giro
          </h3>

          <div className="space-y-3">
            <div className="relative">
              <select 
                value={productId1}
                onChange={(e) => setProductId1(e.target.value)}
                className={`w-full bg-gray-50 border ${productId1 ? 'border-purple-200 shadow-sm' : 'border-gray-200'} rounded-2xl py-4 px-6 text-[10px] font-black uppercase tracking-widest text-black outline-none appearance-none transition-all`}
              >
                <option value="">Peça Primária</option>
                {allProducts.map(p => <option key={p.id} value={p.id}>{p.name} ({p.reference_code})</option>)}
              </select>
              {productId1 && <button onClick={() => setProductId1('')} className="absolute right-12 top-1/2 -translate-y-1/2 text-gray-300"><X size={14}/></button>}
              <ChevronDown size={14} className="absolute right-6 top-1/2 -translate-y-1/2 text-gray-300 pointer-events-none" />
            </div>

            <div className="relative">
              <select 
                value={productId2}
                onChange={(e) => setProductId2(e.target.value)}
                className={`w-full bg-gray-50 border ${productId2 ? 'border-amber-200 shadow-sm' : 'border-gray-200'} rounded-2xl py-4 px-6 text-[10px] font-black uppercase tracking-widest text-black outline-none appearance-none transition-all`}
              >
                <option value="">Peça de Comparação</option>
                {allProducts.map(p => <option key={p.id} value={p.id} disabled={p.id === productId1}>{p.name} ({p.reference_code})</option>)}
              </select>
              {productId2 && <button onClick={() => setProductId2('')} className="absolute right-12 top-1/2 -translate-y-1/2 text-gray-300"><X size={14}/></button>}
              <ChevronDown size={14} className="absolute right-6 top-1/2 -translate-y-1/2 text-gray-300 pointer-events-none" />
            </div>
          </div>
        </div>

        {comparisonData.length > 0 ? (
          <div className="space-y-6 animate-in fade-in duration-500">
            <div className="h-48 w-full relative">
              <svg className="w-full h-full" viewBox="0 0 100 100" preserveAspectRatio="none">
                <defs>
                  <linearGradient id="compGrad1" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor="#A855F7" stopOpacity="0.1" />
                    <stop offset="100%" stopColor="#A855F7" stopOpacity="0" />
                  </linearGradient>
                  <linearGradient id="compGrad2" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor="#F59E0B" stopOpacity="0.1" />
                    <stop offset="100%" stopColor="#F59E0B" stopOpacity="0" />
                  </linearGradient>
                </defs>
                <line x1="0" y1="50" x2="100" y2="50" stroke="#f3f4f6" strokeWidth="0.5" />
                {productId1 && (
                  <>
                    <path d={`M 0,100 L ${points1} L 100,100 Z`} fill="url(#compGrad1)" />
                    <polyline fill="none" stroke="#A855F7" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" points={points1} />
                  </>
                )}
                {productId2 && (
                  <>
                    <path d={`M 0,100 L ${points2} L 100,100 Z`} fill="url(#compGrad2)" />
                    <polyline fill="none" stroke="#F59E0B" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" points={points2} />
                  </>
                )}
              </svg>
              <div className="absolute -bottom-6 left-0 right-0 flex justify-between px-1">
                {comparisonData.map((d, i) => (
                  <span key={i} className="text-[8px] font-black text-gray-300 uppercase tracking-widest">{d.month}</span>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4 pt-4">
              {productId1 && (
                <div className="bg-purple-50 p-4 rounded-2xl border border-purple-100 shadow-sm">
                  <div className="flex items-center gap-2 mb-2">
                    <div className="w-2 h-2 rounded-full bg-purple-500"></div>
                    <span className="text-[8px] font-black text-purple-700 uppercase tracking-widest truncate">Peça A</span>
                  </div>
                  <p className="text-xl font-black text-purple-900">{comparisonData.reduce((acc, d) => acc + d.qty1, 0)} <span className="text-[10px] opacity-40">un</span></p>
                </div>
              )}
              {productId2 && (
                <div className="bg-amber-50 p-4 rounded-2xl border border-amber-100 shadow-sm">
                  <div className="flex items-center gap-2 mb-2">
                    <div className="w-2 h-2 rounded-full bg-amber-500"></div>
                    <span className="text-[8px] font-black text-amber-700 uppercase tracking-widest truncate">Peça B</span>
                  </div>
                  <p className="text-xl font-black text-amber-900">{comparisonData.reduce((acc, d) => acc + d.qty2, 0)} <span className="text-[10px] opacity-40">un</span></p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="py-20 text-center space-y-3">
            <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto border border-dashed border-gray-200">
              <Search size={24} className="text-gray-100" />
            </div>
            <p className="text-[9px] font-black text-gray-300 uppercase tracking-widest">Compare o giro entre duas peças diferentes</p>
          </div>
        )}
      </div>
    </div>
  );
};

