import React, { useState, useEffect } from 'react';
import { Plus, ShoppingBag, User, Package, DollarSign, Calendar, X, Search, Filter, Trash2, CreditCard, Banknote, QrCode, ReceiptText, Printer, Share2, Truck } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product, Customer, Sale } from '../types';

interface CartItem {
  product: Product;
  amount: number;
}

const Sales: React.FC = () => {
  const [sales, setSales] = useState<Sale[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const [selectedOrderItems, setSelectedOrderItems] = useState<Sale[] | null>(null);

  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedProductId, setSelectedProductId] = useState('');
  const [selectedProductQty, setSelectedProductQty] = useState(1);

  const [formData, setFormData] = useState({
    customerId: '',
    discount: '0',
    discountDescription: '',
    paymentMethod: 'pix',
    shippingCharged: '0',
    shippingCost: '0',
    date: new Date().toISOString().split('T')[0]
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const { data: s } = await supabase.from('sales').select('*, customer:customers(*), product:products(*)').order('created_at', { ascending: false });
      const { data: p } = await supabase.from('products').select('*');
      const { data: c } = await supabase.from('customers').select('*');
      if (s) setSales(s);
      if (p) setProducts(p);
      if (c) setCustomers(c);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleShowReceipt = (orderId: string) => {
    const orderItems = sales.filter(s => s.order_id === orderId);
    if (orderItems.length > 0) {
      setSelectedOrderItems(orderItems);
    }
  };

  const addToCart = () => {
    if (!selectedProductId) return;
    const prod = products.find(p => p.id === selectedProductId);
    if (!prod) return;

    if (selectedProductQty > prod.stock) {
      alert(`⚠️ Estoque insuficiente! (${prod.stock} un disponíveis)`);
      return;
    }

    setCart([...cart, { product: prod, amount: selectedProductQty }]);
    setSelectedProductId('');
    setSelectedProductQty(1);
  };

  const removeFromCart = (index: number) => {
    setCart(cart.filter((_, i) => i !== index));
  };

  const cartTotal = cart.reduce((acc, item) => acc + (item.product.price * item.amount), 0);
  const shippingCharge = parseFloat(formData.shippingCharged.replace(',', '.')) || 0;
  const shippingCost = parseFloat(formData.shippingCost.replace(',', '.')) || 0;
  const finalTotal = Math.max(0, cartTotal + shippingCharge - (parseFloat(formData.discount.replace(',', '.')) || 0));
  const shippingBalance = shippingCharge - shippingCost;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.customerId || cart.length === 0) {
      alert('Selecione uma cliente e adicione itens ao carrinho.');
      return;
    }

    setLoading(true);
    try {
      const orderId = crypto.randomUUID();
      const totalDiscount = parseFloat(formData.discount.replace(',', '.')) || 0;

      const discountPerItem = cart.length > 0 ? totalDiscount / cart.length : 0;

      const salesPayload = cart.map(item => ({
        order_id: orderId,
        customer_id: formData.customerId,
        product_id: item.product.id,
        amount: item.amount,
        value: (item.product.price * item.amount) - discountPerItem,
        discount: discountPerItem,
        discount_description: formData.discountDescription,
        payment_method: formData.paymentMethod,
        shipping_charged: shippingCharge / cart.length,
        shipping_cost: shippingCost / cart.length,
        created_at: formData.date
      }));

      const { error: saleError } = await supabase.from('sales').insert(salesPayload);
      if (saleError) throw saleError;

      for (const item of cart) {
        await supabase.from('products').update({ stock: item.product.stock - item.amount }).eq('id', item.product.id);
      }

      setShowForm(false);
      setCart([]);
      setFormData({
        customerId: '',
        discount: '0',
        discountDescription: '',
        paymentMethod: 'pix',
        shippingCharged: '0',
        shippingCost: '0',
        date: new Date().toISOString().split('T')[0]
      });
      fetchData();
      alert('Nota emitida com sucesso! ✨');
    } catch (err) {
      console.error(err);
      alert('Erro ao processar venda.');
    } finally {
      setLoading(false);
    }
  };

  const filteredSales = sales.filter(s => 
    s.customer?.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.product?.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex items-stretch gap-3">
        <div className="relative flex-1">
          <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
          <input 
            type="text" 
            placeholder="Buscar nota ou cliente..."
            className="w-full h-full bg-gray-50 border border-gray-100 rounded-2xl py-4 pl-12 pr-4 text-xs font-bold outline-none text-black focus:border-black transition-all"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>
        <button 
          onClick={() => setShowForm(!showForm)}
          className={`w-14 h-14 rounded-2xl shadow-xl transition-all flex items-center justify-center shrink-0 ${showForm ? 'bg-white border border-gray-100 text-black' : 'bg-black text-white'}`}
        >
          {showForm ? <X size={20} /> : <Plus size={24} />}
        </button>
      </div>

      {showForm ? (
        <form onSubmit={handleSubmit} className="bg-white rounded-[2.5rem] p-8 shadow-2xl space-y-6 border border-gray-50 animate-in slide-in-from-top-4 duration-300">
          <div className="space-y-5">
            <div>
              <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block">Cliente</label>
              <select 
                className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none"
                value={formData.customerId}
                onChange={e => setFormData({...formData, customerId: e.target.value})}
                required
              >
                <option value="">Selecionar Cliente</option>
                {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>

            <div className="p-4 bg-gray-50 rounded-3xl border border-gray-100 space-y-3">
              <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1 block">Carrinho</label>
              <div className="flex gap-2">
                <select 
                  className="flex-1 bg-white border border-gray-200 rounded-xl py-3 px-4 text-xs font-bold text-black outline-none"
                  value={selectedProductId}
                  onChange={e => setSelectedProductId(e.target.value)}
                >
                  <option value="">Peça</option>
                  {products.map(p => <option key={p.id} value={p.id} disabled={p.stock <= 0}>{p.name}</option>)}
                </select>
                <input 
                  type="number" 
                  className="w-16 bg-white border border-gray-200 rounded-xl py-3 px-2 text-xs font-bold text-black outline-none text-center"
                  value={selectedProductQty}
                  onChange={e => setSelectedProductQty(parseInt(e.target.value))}
                  min="1"
                />
                <button 
                  type="button"
                  onClick={addToCart}
                  className="bg-black text-white p-3 rounded-xl"
                >
                  <Plus size={18} />
                </button>
              </div>

              {cart.length > 0 && (
                <div className="space-y-2 mt-2">
                  {cart.map((item, index) => (
                    <div key={index} className="flex justify-between items-center bg-white p-3 rounded-xl border border-gray-100">
                      <p className="text-[10px] font-black uppercase text-black truncate flex-1">{item.product.name}</p>
                      <button type="button" onClick={() => removeFromCart(index)} className="text-red-300 ml-2">
                        <Trash2 size={14} />
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Nova Seção de Frete */}
            <div className="bg-purple-50 p-5 rounded-[2rem] border border-purple-100 space-y-4">
              <div className="flex items-center gap-2 mb-1">
                <Truck size={14} className="text-purple-400" />
                <span className="text-[9px] font-black text-purple-400 uppercase tracking-widest">Logística & Frete</span>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[8px] font-black text-purple-300 uppercase block mb-1">Cobrado da Cliente</label>
                  <input type="text" placeholder="0,00" className="w-full bg-white border border-purple-100 rounded-xl py-3 px-4 text-xs font-bold text-black outline-none" value={formData.shippingCharged} onChange={e => setFormData({...formData, shippingCharged: e.target.value})} />
                </div>
                <div>
                  <label className="text-[8px] font-black text-purple-300 uppercase block mb-1">Custo Real (Pago)</label>
                  <input type="text" placeholder="0,00" className="w-full bg-white border border-purple-100 rounded-xl py-3 px-4 text-xs font-bold text-black outline-none" value={formData.shippingCost} onChange={e => setFormData({...formData, shippingCost: e.target.value})} />
                </div>
              </div>
              <div className="flex justify-between items-center px-2">
                <span className="text-[8px] font-black text-purple-300 uppercase">Resultado Logístico</span>
                <span className={`text-[10px] font-black ${shippingBalance >= 0 ? 'text-emerald-500' : 'text-red-500'}`}>
                  {shippingBalance >= 0 ? '+' : ''} R$ {shippingBalance.toFixed(2)}
                </span>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block">Pagamento</label>
                <div className="grid grid-cols-3 gap-2">
                  <button type="button" onClick={() => setFormData({...formData, paymentMethod: 'cartao'})} className={`p-3 rounded-xl flex justify-center border transition-all ${formData.paymentMethod === 'cartao' ? 'bg-black text-white border-black' : 'bg-gray-50 text-gray-300 border-gray-200'}`}><CreditCard size={18}/></button>
                  <button type="button" onClick={() => setFormData({...formData, paymentMethod: 'dinheiro'})} className={`p-3 rounded-xl flex justify-center border transition-all ${formData.paymentMethod === 'dinheiro' ? 'bg-black text-white border-black' : 'bg-gray-50 text-gray-300 border-gray-200'}`}><Banknote size={18}/></button>
                  <button type="button" onClick={() => setFormData({...formData, paymentMethod: 'pix'})} className={`p-3 rounded-xl flex justify-center border transition-all ${formData.paymentMethod === 'pix' ? 'bg-black text-white border-black' : 'bg-gray-50 text-gray-300 border-gray-200'}`}><QrCode size={18}/></button>
                </div>
              </div>
              <div>
                <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block">Desconto (R$)</label>
                <input type="text" placeholder="0,00" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-red-500 outline-none" value={formData.discount} onChange={e => setFormData({...formData, discount: e.target.value})} />
              </div>
            </div>

            <div className="bg-gray-950 p-7 rounded-[2rem] text-white flex justify-between items-center shadow-2xl">
              <div>
                <span className="text-[9px] font-black text-white/40 uppercase tracking-[0.3em]">Total Geral</span>
                <p className="text-2xl font-black">R$ {finalTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
              </div>
              <ShoppingBag size={24} className="text-white/20" />
            </div>

            <input type="date" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} required />
          </div>

          <button type="submit" className="w-full bg-black text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-xl active:scale-95 transition-all">Finalizar Nota</button>
        </form>
      ) : (
        <div className="space-y-4">
          <div className="flex items-center justify-between px-2">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">Notas Emitidas</h3>
            <Filter size={14} className="text-gray-200" />
          </div>

          <div className="bg-white rounded-[2.5rem] border border-gray-50 shadow-sm overflow-hidden divide-y divide-gray-50">
            {loading ? (
              <div className="p-20 text-center text-gray-300 text-[10px] font-black uppercase animate-pulse">Buscando Notas...</div>
            ) : filteredSales.length > 0 ? (
              filteredSales.map(sale => (
                <div 
                  key={sale.id} 
                  onClick={() => handleShowReceipt(sale.order_id)}
                  className="p-6 flex items-center justify-between hover:bg-gray-50/50 transition-colors cursor-pointer active:scale-[0.99]"
                >
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 rounded-2xl bg-indigo-50 flex items-center justify-center text-indigo-600 shadow-sm">
                      <ShoppingBag size={20} />
                    </div>
                    <div>
                      <p className="text-xs font-black text-black uppercase tracking-tight">{sale.customer?.name}</p>
                      <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest">{sale.product?.name} ({sale.amount}x)</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-xs font-black text-black">R$ {Number(sale.value + (sale.shipping_charged || 0)).toFixed(2)}</p>
                    <p className="text-[8px] text-gray-300 font-bold uppercase mt-1">{new Date(sale.created_at).toLocaleDateString('pt-BR')}</p>
                  </div>
                </div>
              ))
            ) : (
              <div className="p-20 text-center text-gray-200 text-[10px] font-black uppercase tracking-widest">Nenhuma nota emitida</div>
            )}
          </div>
        </div>
      )}

      {selectedOrderItems && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-6 bg-black/40 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-sm rounded-[2rem] p-8 shadow-2xl relative overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="border-t-8 border-black absolute top-0 left-0 right-0"></div>

            <button 
              onClick={() => setSelectedOrderItems(null)}
              className="absolute right-6 top-6 w-10 h-10 rounded-full bg-gray-50 flex items-center justify-center text-gray-400"
            >
              <X size={18} />
            </button>

            <div className="space-y-8 mt-4">
              <div className="text-center space-y-2">
                <h2 className="text-4xl font-serif-brand font-black text-black">S.</h2>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.5em]">Sensitive Shop</p>
              </div>

              <div className="space-y-1">
                <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Cliente</p>
                <p className="text-sm font-black text-black uppercase tracking-tight">{selectedOrderItems[0].customer?.name}</p>
              </div>

              <div className="space-y-4">
                <div className="border-y border-dashed border-gray-200 py-3 grid grid-cols-12 text-[8px] font-black text-gray-400 uppercase tracking-widest">
                  <span className="col-span-8">Item</span>
                  <span className="col-span-4 text-right">Subtotal</span>
                </div>

                <div className="space-y-3">
                  {selectedOrderItems.map((item, idx) => (
                    <div key={idx} className="grid grid-cols-12 items-start text-[10px] font-bold text-black uppercase">
                      <div className="col-span-8 leading-tight">
                        {item.product?.name}
                        <p className="text-[7px] text-gray-400 font-bold mt-0.5">Qt: {item.amount}</p>
                      </div>
                      <span className="col-span-4 text-right font-black">R$ {Number(item.value).toFixed(2)}</span>
                    </div>
                  ))}
                </div>

                <div className="border-t border-dashed border-gray-200 pt-4 space-y-2">
                  <div className="flex justify-between items-center text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                    <span>Frete Cobrado</span>
                    <span className="text-black font-black">R$ {(selectedOrderItems.reduce((acc, i) => acc + (i.shipping_charged || 0), 0)).toFixed(2)}</span>
                  </div>
                  {selectedOrderItems[0].discount > 0 && (
                    <div className="flex justify-between items-center text-[10px] font-bold text-red-400 uppercase tracking-widest">
                      <span>Desconto</span>
                      <span className="font-black">- R$ {(selectedOrderItems.reduce((acc, i) => acc + (i.discount || 0), 0)).toFixed(2)}</span>
                    </div>
                  )}
                  <div className="flex justify-between items-center pt-2">
                    <span className="text-xs font-black text-black uppercase tracking-widest">Total Geral</span>
                    <span className="text-xl font-black text-black">
                      R$ {selectedOrderItems.reduce((acc, i) => acc + Number(i.value) + Number(i.shipping_charged || 0), 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                    </span>
                  </div>
                </div>
              </div>

              <div className="text-center pt-4">
                <button 
                  onClick={() => setSelectedOrderItems(null)}
                  className="w-full bg-black text-white py-4 rounded-xl font-black text-[9px] uppercase tracking-widest"
                >
                  Fechar Nota
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Sales;

import React, { useState, useEffect } from 'react';
import { Plus, X, Wallet, Search, Trash2, Calendar, Tag, Filter, ChevronRight, DollarSign, ArrowRight, TrendingDown } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Expense } from '../types';

const Expenses: React.FC = () => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [search, setSearch] = useState('');
  const [isSaving, setIsSaving] = useState(false);

  const [newExpense, setNewExpense] = useState({
    description: '',
    amount: '',
    category: 'Variável',
    date: new Date().toISOString().split('T')[0]
  });

  useEffect(() => { fetchExpenses(); }, []);

  const fetchExpenses = async () => {
    try {
      setLoading(true);
      const { data } = await supabase.from('expenses').select('*').order('date', { ascending: false });
      if (data) setExpenses(data);
    } catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const handleAddExpense = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      const { error } = await supabase.from('expenses').insert([{
        description: newExpense.description.trim(),
        amount: parseFloat(newExpense.amount.toString().replace(',', '.')),
        category: newExpense.category,
        date: newExpense.date
      }]);
      if (error) throw error;
      setNewExpense({ description: '', amount: '', category: 'Variável', date: new Date().toISOString().split('T')[0] });
      setShowForm(false);
      fetchExpenses();
    } catch (e) { alert('Erro ao salvar despesa.'); } finally { setIsSaving(false); }
  };

  const deleteExpense = async (id: string) => {
    if (!confirm('Excluir esta despesa?')) return;
    try {
      await supabase.from('expenses').delete().eq('id', id);
      fetchExpenses();
    } catch (e) { console.error(e); }
  };

  const totalMonth = expenses.reduce((acc, exp) => {
    const expDate = new Date(exp.date);
    const now = new Date();
    if (expDate.getMonth() === now.getMonth() && expDate.getFullYear() === now.getFullYear()) {
      return acc + Number(exp.amount);
    }
    return acc;
  }, 0);

  const filteredExpenses = expenses.filter(e => 
    e.description.toLowerCase().includes(search.toLowerCase()) ||
    e.category.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-6 pb-20">
      <div className="bg-red-50 rounded-[2.5rem] p-8 border border-red-100 shadow-sm relative overflow-hidden">
        <div className="absolute right-6 top-6 opacity-10">
          <TrendingDown size={40} className="text-red-500" />
        </div>
        <div className="relative z-10 space-y-2">
          <p className="text-[10px] font-black text-red-400 uppercase tracking-[0.3em]">Gastos do Mês</p>
          <h2 className="text-3xl font-black text-red-600">
            R$ {totalMonth.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
          </h2>
          <div className="h-px bg-red-200/50 w-full mt-4 mb-2"></div>
          <p className="text-[9px] font-bold text-red-400/60 uppercase tracking-widest">Total de {expenses.length} lançamentos registrados</p>
        </div>
      </div>

      <div className="flex gap-3">
        <div className="relative flex-1">
          <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400" />
          <input 
            type="text" 
            placeholder="Buscar despesa..."
            className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 pl-14 pr-6 text-xs shadow-sm focus:border-black transition-all font-bold outline-none text-black"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
        <button 
          onClick={() => setShowForm(!showForm)} 
          className={`w-14 h-14 rounded-2xl shadow-xl transition-all flex items-center justify-center shrink-0 ${showForm ? 'bg-white text-black border border-gray-100' : 'bg-red-600 text-white'}`}
        >
          {showForm ? <X size={24} /> : <Plus size={24} />}
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleAddExpense} className="bg-white border-2 border-red-50 rounded-[2.5rem] p-8 shadow-2xl space-y-4 animate-in slide-in-from-top-4">
          <div className="flex items-center justify-between mb-2">
            <h3 className="text-xs font-black text-red-600 uppercase tracking-[0.3em]">Lançar Despesa</h3>
            <Wallet size={16} className="text-red-300" />
          </div>
          <input type="text" placeholder="Descrição (Ex: Aluguel)" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newExpense.description} onChange={e => setNewExpense({...newExpense, description: e.target.value})} required />
          <div className="grid grid-cols-2 gap-4">
            <input type="text" placeholder="Valor R$" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-red-600 outline-none" value={newExpense.amount} onChange={e => setNewExpense({...newExpense, amount: e.target.value})} required />
            <select className="bg-gray-50 border border-gray-200 rounded-2xl py-4 px-4 text-xs font-bold text-black outline-none" value={newExpense.category} onChange={e => setNewExpense({...newExpense, category: e.target.value})}>
              <option value="Fixo">Custo Fixo</option>
              <option value="Variável">Variável</option>
              <option value="Marketing">Marketing</option>
              <option value="Estoque">Estoque</option>
              <option value="Outros">Outros</option>
            </select>
          </div>
          <input type="date" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={newExpense.date} onChange={e => setNewExpense({...newExpense, date: e.target.value})} />
          <button type="submit" disabled={isSaving} className="w-full bg-red-600 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-xl active:scale-95 transition-all">
            {isSaving ? 'Registrando...' : 'Confirmar Saída'}
          </button>
        </form>
      )}

      <div className="bg-white rounded-[2.5rem] border border-gray-50 shadow-sm overflow-hidden divide-y divide-gray-50">
        {loading ? (
          <div className="p-16 text-center text-gray-300 text-xs font-black uppercase animate-pulse">Consultando Extrato...</div>
        ) : filteredExpenses.length > 0 ? (
          filteredExpenses.map(exp => (
            <div key={exp.id} className="p-6 flex items-center justify-between hover:bg-gray-50/50 transition-all">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-2xl bg-red-50 flex items-center justify-center text-red-400">
                  <TrendingDown size={20} />
                </div>
                <div>
                  <p className="text-xs font-black text-black uppercase tracking-tight">{exp.description}</p>
                  <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest">{exp.category} • {new Date(exp.date).toLocaleDateString()}</p>
                </div>
              </div>
              <div className="flex items-center gap-4">
                <p className="text-sm font-black text-red-600">R$ {Number(exp.amount).toFixed(2)}</p>
                <button onClick={() => deleteExpense(exp.id)} className="text-gray-200 hover:text-red-500 transition-colors">
                  <Trash2 size={16} />
                </button>
              </div>
            </div>
          ))
        ) : (
          <div className="p-20 text-center text-gray-200 text-[10px] font-black uppercase tracking-[0.3em]">Nenhuma despesa lançada</div>
        )}
      </div>
    </div>
  );
};

export default Expenses;

import React, { useState, useEffect } from 'react';
import { 
  ArrowLeft, 
  TrendingUp, 
  DollarSign, 
  ArrowUp, 
  ArrowDown, 
  Settings2, 
  BarChart3, 
  Gem, 
  AlertTriangle, 
  Trophy, 
  Package,
  Search,
  ChevronDown,
  X,
  LineChart,
  Target,
  CheckCircle2,
  TrendingDown,
  Wallet,
  Activity
} from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Sale, Product, Expense } from '../types';

interface AnalyticsProps {
  onBack: () => void;
}

type FilterType = 'total' | 'mensal' | 'periodo';

interface ProductStats {
  product: Product;
  margin: number;
  totalSold: number;
  totalRevenue: number;
}

const Analytics: React.FC<AnalyticsProps> = ({ onBack }) => {
  const [loading, setLoading] = useState(true);
  const [filterType, setFilterType] = useState<FilterType>('mensal');
  const [customDates, setCustomDates] = useState({
    start: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0]
  });

  const [totals, setTotals] = useState({ 
    revenue: 0, 
    cogs: 0, 
    netProfit: 0, 
    expenses: 0,
    shippingBalance: 0,
    prevRevenue: 0,
    prevNetProfit: 0 
  });

  const [chartData, setChartData] = useState<{label: string, amount: number}[]>([]);
  const [idealProfitGoal, setIdealProfitGoal] = useState<number>(() => {
    return Number(localStorage.getItem('sensitive_ideal_profit') || 5000);
  });
  const [showGoalInput, setShowGoalInput] = useState(false);
  const [newGoalValue, setNewGoalValue] = useState(idealProfitGoal.toString());

  useEffect(() => {
    if (showGoalInput) {
      setNewGoalValue(idealProfitGoal.toString());
    }
  }, [showGoalInput, idealProfitGoal]);

  const [topProfitable, setTopProfitable] = useState<ProductStats[]>([]);
  const [bottomProfitable, setBottomProfitable] = useState<ProductStats[]>([]);
  const [allProducts, setAllProducts] = useState<Product[]>([]);
  const [allSales, setAllSales] = useState<Sale[]>([]);
  const [productId1, setProductId1] = useState<string>('');
  const [productId2, setProductId2] = useState<string>('');
  const [comparisonData, setComparisonData] = useState<{month: string, qty1: number, qty2: number}[]>([]);

  useEffect(() => {
    fetchAnalytics();
  }, [filterType, customDates]);

  const fetchAnalytics = async () => {
    setLoading(true);
    try {
      const { data: salesData } = await supabase.from('sales').select('*, product:products(*)');
      const { data: productsData } = await supabase.from('products').select('*');
      const { data: expensesData } = await supabase.from('expenses').select('*');

      if (salesData && productsData) {
        setAllSales(salesData as Sale[]);
        setAllProducts(productsData as Product[]);

        const now = new Date();
        let startDate: Date;
        let endDate: Date = new Date();
        let compareStartDate: Date;
        let compareEndDate: Date;

        if (filterType === 'mensal') {
          startDate = new Date(now.getFullYear(), now.getMonth(), 1);
          compareStartDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
          compareEndDate = new Date(now.getFullYear(), now.getMonth(), 0);
        } else if (filterType === 'periodo') {
          startDate = new Date(customDates.start);
          endDate = new Date(customDates.end);
          endDate.setHours(23, 59, 59);
          const diff = endDate.getTime() - startDate.getTime();
          compareEndDate = new Date(startDate.getTime() - 1);
          compareStartDate = new Date(compareEndDate.getTime() - diff);
        } else {
          startDate = new Date(0);
          compareStartDate = new Date(0);
          compareEndDate = new Date(0);
        }

        let currentRev = 0;
        let currentCogs = 0;
        let currentShipCharged = 0;
        let currentShipCost = 0;
        let prevRev = 0;
        let prevProfit = 0;
        const timelineMap: Record<string, number> = {};
        const statsMap: Record<string, ProductStats> = {};

        salesData.forEach((sale: any) => {
          const product = sale.product;
          if (!product) return;

          const saleDate = new Date(sale.created_at);
          const rev = Number(sale.value);
          const cost = Number(product.purchase_price) * Number(sale.amount);
          const sCharged = Number(sale.shipping_charged || 0);
          const sCost = Number(sale.shipping_cost || 0);
          const profit = (rev + sCharged) - (cost + sCost);

          if (!statsMap[product.id]) {
            statsMap[product.id] = { product, margin: product.price - product.purchase_price, totalSold: 0, totalRevenue: 0 };
          }
          statsMap[product.id].totalSold += Number(sale.amount);
          statsMap[product.id].totalRevenue += rev;

          if (saleDate >= startDate && saleDate <= endDate) {
            currentRev += rev;
            currentCogs += cost;
            currentShipCharged += sCharged;
            currentShipCost += sCost;
            const label = filterType === 'total' 
              ? saleDate.toLocaleString('pt-BR', { month: 'short', year: '2-digit' })
              : saleDate.getDate().toString();
            timelineMap[label] = (timelineMap[label] || 0) + profit;
          } else if (saleDate >= compareStartDate && saleDate <= compareEndDate) {
            prevRev += rev;
            prevProfit += profit;
          }
        });

        // Calcular Despesas do Período
        let currentExpenses = 0;
        if (expensesData) {
          expensesData.forEach((exp: any) => {
            const d = new Date(exp.date);
            if (d >= startDate && d <= endDate) {
              currentExpenses += Number(exp.amount);
            }
          });
        }

        const sortedProducts = Object.values(statsMap).sort((a, b) => b.margin - a.margin);
        setTopProfitable(sortedProducts.slice(0, 5));
        setBottomProfitable([...sortedProducts].reverse().slice(0, 5));

        let accumulated = 0;
        const evolution = Object.entries(timelineMap)
          .sort((a, b) => filterType === 'total' ? 0 : Number(a[0]) - Number(b[0]))
          .map(([label, profit]) => {
            accumulated += profit;
            return { label, amount: filterType === 'total' ? profit : accumulated };
          });

        const netRealProfit = (currentRev + currentShipCharged) - (currentCogs + currentShipCost + currentExpenses);

        setChartData(evolution);
        setTotals({ 
          revenue: currentRev, 
          cogs: currentCogs, 
          expenses: currentExpenses,
          shippingBalance: currentShipCharged - currentShipCost,
          netProfit: netRealProfit, 
          prevRevenue: prevRev, 
          prevNetProfit: prevProfit 
        });
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleSaveGoal = () => {
    const val = parseFloat(newGoalValue) || 0;
    setIdealProfitGoal(val);
    localStorage.setItem('sensitive_ideal_profit', val.toString());
    setShowGoalInput(false);
  };

  const revVariation = totals.prevRevenue > 0 ? ((totals.revenue - totals.prevRevenue) / totals.prevRevenue) * 100 : 0;
  const profitVariation = totals.prevNetProfit > 0 ? ((totals.netProfit - totals.prevNetProfit) / totals.prevNetProfit) * 100 : 0;
  const goalProgress = Math.min(100, (totals.netProfit / (idealProfitGoal || 1)) * 100);
  const gapToGoal = Math.max(0, idealProfitGoal - totals.netProfit);

  const maxAmount = Math.max(...chartData.map(d => d.amount), 1);
  const chartPoints = chartData.map((d, i) => {
    const x = (i / (chartData.length - 1 || 1)) * 100;
    const y = 100 - (d.amount / maxAmount) * 100;
    return `${x},${y}`;
  }).join(' ');

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex items-center justify-between">
        <button onClick={onBack} className="flex items-center gap-2 text-gray-400 hover:text-black transition-colors">
          <ArrowLeft size={16} />
          <span className="text-[10px] font-black uppercase tracking-widest">Painel de Controle</span>
        </button>
        <button 
          onClick={() => setShowGoalInput(!showGoalInput)} 
          className={`p-3 rounded-2xl transition-all shadow-lg ${showGoalInput ? 'bg-black text-white' : 'bg-purple-50 text-purple-600'}`}
        >
          <Target size={20} />
        </button>
      </div>

      <div className="space-y-1">
        <h2 className="text-2xl font-black text-black uppercase tracking-tighter">Boutique Intelligence</h2>
        <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Performance Financeira Real</p>
      </div>

      {showGoalInput && (
        <div className="bg-white border-4 border-black p-8 rounded-[2.5rem] shadow-2xl animate-in slide-in-from-top-4 duration-300 space-y-6 relative z-50">
          <div className="flex justify-between items-center">
            <h4 className="text-lg font-black text-black uppercase">Lucro Ideal</h4>
            <button onClick={() => setShowGoalInput(false)} className="text-gray-300"><X size={20} /></button>
          </div>
          <div className="relative">
            <span className="absolute left-6 top-1/2 -translate-y-1/2 text-lg font-black text-gray-300">R$</span>
            <input type="number" className="w-full bg-gray-50 border-2 border-gray-100 rounded-[1.5rem] py-6 pl-16 pr-6 text-2xl font-black text-black outline-none" value={newGoalValue} onChange={e => setNewGoalValue(e.target.value)} />
          </div>
          <button onClick={handleSaveGoal} className="w-full bg-black text-white py-5 rounded-[1.5rem] font-black text-xs uppercase tracking-[0.3em]">Confirmar Meta</button>
        </div>
      )}

      {/* Filtro Temporal */}
      <div className="bg-gray-100 p-1.5 rounded-[2rem] flex gap-1 border border-gray-200/50">
        {(['mensal', 'periodo', 'total'] as FilterType[]).map((t) => (
          <button key={t} onClick={() => setFilterType(t)} className={`flex-1 py-3 rounded-[1.5rem] text-[9px] font-black uppercase tracking-widest transition-all ${filterType === t ? 'bg-white text-black shadow-xl' : 'text-gray-400'}`}>{t}</button>
        ))}
      </div>

      {/* Métricas Reais com Abatimentos */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white rounded-[2rem] p-6 border border-gray-100 shadow-sm space-y-3">
          <div className="flex justify-between items-start">
            <div className="p-2 bg-gray-50 rounded-xl text-gray-400"><DollarSign size={16} /></div>
            <div className={`flex items-center gap-0.5 text-[9px] font-black uppercase ${revVariation >= 0 ? 'text-emerald-500' : 'text-red-500'}`}>
              {revVariation >= 0 ? <TrendingUp size={12} /> : <TrendingDown size={12} />}
              {Math.abs(revVariation).toFixed(1)}%
            </div>
          </div>
          <div>
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-0.5">Vendas Brutas</p>
            <p className="text-xl font-black text-black">R$ {totals.revenue.toLocaleString('pt-BR')}</p>
          </div>
        </div>

        <div className="bg-emerald-50 rounded-[2rem] p-6 border border-emerald-100 shadow-sm space-y-3">
          <div className="flex justify-between items-start">
            <div className="p-2 bg-emerald-100 text-emerald-600 rounded-xl"><Activity size={16} /></div>
            <div className={`flex items-center gap-0.5 text-[9px] font-black uppercase ${profitVariation >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>
              {profitVariation >= 0 ? <TrendingUp size={12} /> : <TrendingDown size={12} />}
              {Math.abs(profitVariation).toFixed(1)}%
            </div>
          </div>
          <div>
            <p className="text-[9px] font-black text-emerald-800/40 uppercase tracking-widest mb-0.5">Lucro Real (Final)</p>
            <p className="text-xl font-black text-emerald-600">R$ {totals.netProfit.toLocaleString('pt-BR')}</p>
          </div>
        </div>
      </div>

      {/* Detalhamento de Saúde Financeira */}
      <div className="bg-white rounded-[2.5rem] p-8 border border-gray-100 shadow-xl space-y-6">
        <h3 className="text-[10px] font-black text-black uppercase tracking-[0.3em] flex items-center gap-2">
           <Activity size={16} className="text-purple-500" /> Saúde Financeira do Período
        </h3>
        <div className="space-y-4">
          <div className="flex justify-between items-center text-[10px] font-bold text-gray-400 uppercase">
            <span>(+) Vendas + Logística</span>
            <span className="text-black">R$ {(totals.revenue + (totals.shippingBalance > 0 ? totals.shippingBalance : 0)).toFixed(2)}</span>
          </div>
          <div className="flex justify-between items-center text-[10px] font-bold text-red-400 uppercase">
            <span>(-) Custo de Peças</span>
            <span className="font-black">- R$ {totals.cogs.toFixed(2)}</span>
          </div>
          <div className="flex justify-between items-center text-[10px] font-bold text-red-400 uppercase">
            <span>(-) Despesas & Custos Fixos</span>
            <span className="font-black">- R$ {totals.expenses.toFixed(2)}</span>
          </div>
          {totals.shippingBalance < 0 && (
             <div className="flex justify-between items-center text-[10px] font-bold text-red-400 uppercase">
              <span>(-) Prejuízo Logístico</span>
              <span className="font-black">- R$ {Math.abs(totals.shippingBalance).toFixed(2)}</span>
            </div>
          )}
          <div className="h-px bg-gray-100"></div>
          <div className="flex justify-between items-center">
            <span className="text-[11px] font-black uppercase text-black">Lucro Final</span>
            <span className={`text-xl font-black ${totals.netProfit >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>
              R$ {totals.netProfit.toLocaleString('pt-BR')}
            </span>
          </div>
        </div>
      </div>

      {/* Gráfico Comparativo: Lucro Ideal vs Alcançado */}
      <div className="bg-gray-50 rounded-[2.5rem] p-8 border border-gray-100 space-y-6">
        <div className="flex justify-between items-end">
          <div className="space-y-1">
            <h3 className="text-[10px] font-black text-black uppercase tracking-[0.3em]">Meta vs Realidade</h3>
            <p className="text-[9px] font-bold text-gray-400 uppercase">Progresso do Objetivo</p>
          </div>
          <p className="text-3xl font-black text-black">{goalProgress.toFixed(0)}%</p>
        </div>
        <div className="relative h-8 w-full bg-white rounded-full overflow-hidden border border-gray-200">
          <div className="absolute left-0 top-0 h-full bg-gradient-to-r from-purple-600 to-purple-400 transition-all duration-1000 shadow-lg" style={{ width: `${goalProgress}%` }}></div>
        </div>
        <div className="grid grid-cols-2 gap-4">
           <div className="p-4 bg-white rounded-2xl border border-gray-100">
              <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest mb-1">Lucro Planejado</p>
              <p className="text-md font-black text-black">R$ {idealProfitGoal.toLocaleString('pt-BR')}</p>
            </div>
            <div className={`p-4 rounded-2xl border ${gapToGoal === 0 ? 'bg-emerald-50 border-emerald-100' : 'bg-purple-50 border-purple-100'}`}>
              <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest mb-1">{gapToGoal === 0 ? 'Status' : 'Faltam'}</p>
              <p className={`text-md font-black ${gapToGoal === 0 ? 'text-emerald-600' : 'text-purple-600'}`}>
                {gapToGoal === 0 ? 'META ATINGIDA! ✨' : `R$ ${gapToGoal.toLocaleString('pt-BR')}`}
              </p>
            </div>
        </div>
      </div>
    </div>
  );
};

export default Analytics;

import React, { useState, useEffect } from 'react';
import { Plus, X, Wallet, Search, Trash2, Calendar, Tag, Filter, ChevronRight, DollarSign, ArrowRight, TrendingDown, Edit2, AlertTriangle } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Expense } from '../types';

const Expenses: React.FC = () => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [search, setSearch] = useState('');
  const [isSaving, setIsSaving] = useState(false);

  // Estados de Gerenciamento
  const [editingId, setEditingId] = useState<string | null>(null);
  const [deletingId, setDeletingId] = useState<string | null>(null);

  const [newExpense, setNewExpense] = useState({
    description: '',
    amount: '',
    category: 'Variável',
    date: new Date().toISOString().split('T')[0]
  });

  useEffect(() => { fetchExpenses(); }, []);

  const fetchExpenses = async () => {
    try {
      setLoading(true);
      const { data } = await supabase.from('expenses').select('*').order('date', { ascending: false });
      if (data) setExpenses(data);
    } catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const handleSaveExpense = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      const payload = {
        description: newExpense.description.trim(),
        amount: parseFloat(newExpense.amount.toString().replace(',', '.')),
        category: newExpense.category,
        date: newExpense.date
      };

      if (editingId) {
        const { error } = await supabase.from('expenses').update(payload).eq('id', editingId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('expenses').insert([payload]);
        if (error) throw error;
      }

      setNewExpense({ description: '', amount: '', category: 'Variável', date: new Date().toISOString().split('T')[0] });
      setShowForm(false);
      setEditingId(null);
      fetchExpenses();
    } catch (e) { 
      alert('Erro ao processar despesa.'); 
    } finally { 
      setIsSaving(false); 
    }
  };

  const startEdit = (expense: Expense) => {
    setEditingId(expense.id);
    setNewExpense({
      description: expense.description,
      amount: expense.amount.toString(),
      category: expense.category,
      date: expense.date
    });
    setShowForm(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const confirmDelete = async () => {
    if (!deletingId) return;
    try {
      await supabase.from('expenses').delete().eq('id', deletingId);
      setDeletingId(null);
      fetchExpenses();
    } catch (e) { console.error(e); }
  };

  const totalMonth = expenses.reduce((acc, exp) => {
    const expDate = new Date(exp.date);
    const now = new Date();
    if (expDate.getMonth() === now.getMonth() && expDate.getFullYear() === now.getFullYear()) {
      return acc + Number(exp.amount);
    }
    return acc;
  }, 0);

  const filteredExpenses = expenses.filter(e => 
    e.description.toLowerCase().includes(search.toLowerCase()) ||
    e.category.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-6 pb-20">
      {/* Modal de Confirmação de Exclusão */}
      {deletingId && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-6 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-sm rounded-[2.5rem] p-8 shadow-2xl animate-in zoom-in-95 duration-300 text-center space-y-6">
            <div className="w-16 h-16 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-2">
              <Trash2 size={28} />
            </div>
            <div className="space-y-2">
              <h3 className="text-sm font-black text-black uppercase tracking-widest">Excluir Lançamento?</h3>
              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest leading-relaxed px-4">
                Esta ação removerá o custo permanentemente dos seus registros financeiros.
              </p>
            </div>
            <div className="flex gap-3 pt-2">
              <button 
                onClick={() => setDeletingId(null)}
                className="flex-1 bg-gray-50 text-gray-400 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all active:scale-95"
              >
                Voltar
              </button>
              <button 
