                value={customDates.start}
                onChange={e => setCustomDates({...customDates, start: e.target.value})}
              />
            </div>
            <div className="relative">
              <Calendar size={12} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
              <input 
