                className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-3 pl-10 pr-4 text-[10px] font-black text-black outline-none"
                value={customDates.end}
                onChange={e => setCustomDates({...customDates, end: e.target.value})}
              />
            </div>
          </div>
        )}
      </div>

      {/* Métricas Reais com Abatimentos */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white rounded-[2rem] p-6 border border-gray-100 shadow-sm space-y-3">
          <div className="flex justify-between items-start">
