              <p className={`text-md font-black ${gapToGoal === 0 ? 'text-emerald-600' : 'text-purple-600'}`}>
                {gapToGoal === 0 ? 'META ATINGIDA! ✨' : `R$ ${gapToGoal.toLocaleString('pt-BR')}`}
              </p>
            </div>
        </div>
      </div>

      {/* NOVO: Gráfico de Lucratividade Detalhado no Rodapé */}
      <div className="bg-white rounded-[2.5rem] p-8 border border-gray-100 shadow-xl space-y-6">
        <div className="flex justify-between items-center">
          <h3 className="text-[10px] font-black text-black uppercase tracking-[0.3em] flex items-center gap-2">
