          </h3>
          <span className="text-[8px] font-black text-gray-300 uppercase tracking-widest">Saldo Real (R$)</span>
        </div>

        {chartData.length > 0 ? (
          <div className="h-40 w-full flex items-end gap-1.5 pt-4">
            {chartData.map((data, i) => {
              const heightPercentage = Math.max(5, ((data.amount - minProfit) / (range || 1)) * 100);
              return (
                <div key={i} className="flex-1 flex flex-col items-center gap-2 group relative">
                  {/* Tooltip on hover */}
                  <div className="absolute -top-8 left-1/2 -translate-x-1/2 bg-black text-white text-[8px] font-black px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap z-10">
                    R$ {data.amount.toFixed(0)}
                  </div>

                  <div 
                    className={`w-full rounded-t-lg transition-all duration-500 ${data.amount >= 0 ? 'bg-indigo-500/80 group-hover:bg-indigo-500' : 'bg-red-400/80 group-hover:bg-red-400'}`}
                    style={{ height: `${heightPercentage}%` }}
                  ></div>

                  <span className="text-[7px] font-black text-gray-300 uppercase tracking-tighter truncate w-full text-center">
                    {data.label}
                  </span>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="h-40 flex items-center justify-center border-2 border-dashed border-gray-50 rounded-3xl">
             <p className="text-[9px] font-black text-gray-200 uppercase tracking-widest">Dados insuficientes para o gráfico</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Analytics;

import React, { useState, useEffect } from 'react';
import { 
  ArrowLeft, 
  TrendingUp, 
  DollarSign, 
  X, 
  LineChart, 
  Target, 
  TrendingDown, 
  Activity, 
  Calendar 
} from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Sale, Product, Expense } from '../types';

interface AnalyticsProps {
  onBack: () => void;
}

type FilterType = 'total' | 'mensal' | 'periodo';

interface ProductStats {
  product: Product;
  margin: number;
  totalSold: number;
  totalRevenue: number;
}

const Analytics: React.FC<AnalyticsProps> = ({ onBack }) => {
  const [loading, setLoading] = useState(true);
  const [filterType, setFilterType] = useState<FilterType>('mensal');
  const [customDates, setCustomDates] = useState({
    start: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0]
  });

  const [totals, setTotals] = useState({ 
    revenue: 0, 
    cogs: 0, 
    netProfit: 0, 
    expenses: 0,
    shippingBalance: 0,
    prevRevenue: 0,
    prevNetProfit: 0 
  });

  const [chartData, setChartData] = useState<{label: string, amount: number}[]>([]);
  const [idealProfitGoal, setIdealProfitGoal] = useState<number>(() => {
    return Number(localStorage.getItem('sensitive_ideal_profit') || 5000);
  });
  const [showGoalInput, setShowGoalInput] = useState(false);
  const [newGoalValue, setNewGoalValue] = useState(idealProfitGoal.toString());

  useEffect(() => {
    fetchAnalytics();
  }, [filterType, customDates]);

  const fetchAnalytics = async () => {
    setLoading(true);
    try {
      const { data: salesData } = await supabase.from('sales').select('*, product:products(*)');
      const { data: expensesData } = await supabase.from('expenses').select('*');

      if (salesData) {
        const now = new Date();
        let startDate: Date;
        let endDate: Date = new Date();
        let compareStartDate: Date;
        let compareEndDate: Date;

        if (filterType === 'mensal') {
          startDate = new Date(now.getFullYear(), now.getMonth(), 1);
          compareStartDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
          compareEndDate = new Date(now.getFullYear(), now.getMonth(), 0);
        } else if (filterType === 'periodo') {
          startDate = new Date(customDates.start + 'T00:00:00');
          endDate = new Date(customDates.end + 'T23:59:59');
          const diff = endDate.getTime() - startDate.getTime();
          compareEndDate = new Date(startDate.getTime() - 1);
          compareStartDate = new Date(compareEndDate.getTime() - diff);
        } else {
          startDate = new Date(0);
          compareStartDate = new Date(0);
          compareEndDate = new Date(0);
        }

        let currentRev = 0;
        let currentCogs = 0;
        let currentShipCharged = 0;
        let currentShipCost = 0;
        let prevRev = 0;
        let prevProfit = 0;
        const timelineMap: Record<string, number> = {};

        salesData.forEach((sale: any) => {
          const product = sale.product;
          if (!product) return;

          const saleDate = new Date(sale.created_at);
          const rev = Number(sale.value);
          const cost = Number(product.purchase_price) * Number(sale.amount);
          const sCharged = Number(sale.shipping_charged || 0);
          const sCost = Number(sale.shipping_cost || 0);
          const profit = (rev + sCharged) - (cost + sCost);

          if (saleDate >= startDate && saleDate <= endDate) {
            currentRev += rev;
            currentCogs += cost;
            currentShipCharged += sCharged;
            currentShipCost += sCost;

            const label = filterType === 'total' 
              ? saleDate.toLocaleString('pt-BR', { month: 'short', year: '2-digit' })
              : saleDate.getDate().toString();
            timelineMap[label] = (timelineMap[label] || 0) + profit;
          } else if (saleDate >= compareStartDate && saleDate <= compareEndDate) {
            prevRev += rev;
            prevProfit += profit;
          }
        });

        let currentExpenses = 0;
        if (expensesData) {
          expensesData.forEach((exp: any) => {
            const d = new Date(exp.date);
            if (d >= startDate && d <= endDate) {
              const amount = Number(exp.amount);
              currentExpenses += amount;

              const label = filterType === 'total' 
                ? d.toLocaleString('pt-BR', { month: 'short', year: '2-digit' })
                : d.getDate().toString();
              timelineMap[label] = (timelineMap[label] || 0) - amount;
            }
          });
        }

        const evolution = Object.entries(timelineMap)
          .sort((a, b) => {
            if (filterType === 'total') return 0;
            return Number(a[0]) - Number(b[0]);
          })
          .map(([label, profit]) => ({ label, amount: profit }));

        const netRealProfit = (currentRev + currentShipCharged) - (currentCogs + currentShipCost + currentExpenses);

        setChartData(evolution);
        setTotals({ 
          revenue: currentRev, 
          cogs: currentCogs, 
          expenses: currentExpenses,
          shippingBalance: currentShipCharged - currentShipCost,
          netProfit: netRealProfit, 
          prevRevenue: prevRev, 
          prevNetProfit: prevProfit 
        });
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleSaveGoal = () => {
    const val = parseFloat(newGoalValue) || 0;
    setIdealProfitGoal(val);
    localStorage.setItem('sensitive_ideal_profit', val.toString());
    setShowGoalInput(false);
  };

  const revVariation = totals.prevRevenue > 0 ? ((totals.revenue - totals.prevRevenue) / totals.prevRevenue) * 100 : 0;
  const profitVariation = totals.prevNetProfit > 0 ? ((totals.netProfit - totals.prevNetProfit) / totals.prevNetProfit) * 100 : 0;
  const goalProgress = Math.min(100, (totals.netProfit / (idealProfitGoal || 1)) * 100);
  const gapToGoal = Math.max(0, idealProfitGoal - totals.netProfit);

  // Lógica de Renderização do Gráfico
  const amounts = chartData.map(d => d.amount);
  const maxProfit = amounts.length > 0 ? Math.max(...amounts, 0) : 100;
  const minProfit = amounts.length > 0 ? Math.min(...amounts, 0) : 0;
  const range = (maxProfit - minProfit) || 1;

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-32">
      <div className="flex items-center justify-between">
        <button onClick={onBack} className="flex items-center gap-2 text-gray-400 hover:text-black transition-colors">
          <ArrowLeft size={16} />
          <span className="text-[10px] font-black uppercase tracking-widest">Painel de Controle</span>
        </button>
        <button 
          onClick={() => setShowGoalInput(!showGoalInput)} 
          className={`p-3 rounded-2xl transition-all shadow-lg ${showGoalInput ? 'bg-black text-white' : 'bg-purple-50 text-purple-600'}`}
        >
          <Target size={20} />
        </button>
      </div>

      <div className="space-y-1">
        <h2 className="text-2xl font-black text-black uppercase tracking-tighter">Boutique Intelligence</h2>
        <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Performance Financeira Real</p>
      </div>

      {showGoalInput && (
        <div className="bg-white border-4 border-black p-8 rounded-[2.5rem] shadow-2xl animate-in slide-in-from-top-4 duration-300 space-y-6 relative z-50">
          <div className="flex justify-between items-center">
            <h4 className="text-lg font-black text-black uppercase">Lucro Ideal</h4>
            <button onClick={() => setShowGoalInput(false)} className="text-gray-300"><X size={20} /></button>
          </div>
          <div className="relative">
            <span className="absolute left-6 top-1/2 -translate-y-1/2 text-lg font-black text-gray-300">R$</span>
            <input type="number" className="w-full bg-gray-50 border-2 border-gray-100 rounded-[1.5rem] py-6 pl-16 pr-6 text-2xl font-black text-black outline-none" value={newGoalValue} onChange={e => setNewGoalValue(e.target.value)} />
          </div>
          <button onClick={handleSaveGoal} className="w-full bg-black text-white py-5 rounded-[1.5rem] font-black text-xs uppercase tracking-[0.3em]">Confirmar Meta</button>
        </div>
      )}

      {/* Filtro Temporal */}
      <div className="space-y-4">
        <div className="bg-gray-100 p-1.5 rounded-[2rem] flex gap-1 border border-gray-200/50">
          {(['mensal', 'periodo', 'total'] as FilterType[]).map((t) => (
            <button 
              key={t} 
              onClick={() => setFilterType(t)} 
              className={`flex-1 py-3 rounded-[1.5rem] text-[9px] font-black uppercase tracking-widest transition-all ${filterType === t ? 'bg-white text-black shadow-xl' : 'text-gray-400'}`}
            >
              {t}
            </button>
          ))}
        </div>

        {filterType === 'periodo' && (
          <div className="grid grid-cols-2 gap-3 animate-in slide-in-from-top-3 duration-500">
            <div className="space-y-1">
              <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-4">Início</label>
              <div className="relative">
                <Calendar size={12} className="absolute left-4 top-1/2 -translate-y-1/2 text-purple-400" />
                <input 
                  type="date" 
                  className="w-full bg-purple-50/50 border border-purple-100 rounded-2xl py-3 pl-10 pr-4 text-[10px] font-black text-black outline-none focus:border-purple-300"
                  value={customDates.start}
                  onChange={e => setCustomDates({...customDates, start: e.target.value})}
                />
              </div>
            </div>
            <div className="space-y-1">
              <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-4">Fim</label>
              <div className="relative">
                <Calendar size={12} className="absolute left-4 top-1/2 -translate-y-1/2 text-purple-400" />
                <input 
                  type="date" 
                  className="w-full bg-purple-50/50 border border-purple-100 rounded-2xl py-3 pl-10 pr-4 text-[10px] font-black text-black outline-none focus:border-purple-300"
                  value={customDates.end}
                  onChange={e => setCustomDates({...customDates, end: e.target.value})}
                />
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white rounded-[2rem] p-6 border border-gray-100 shadow-sm space-y-3">
          <div className="flex justify-between items-start">
            <div className="p-2 bg-gray-50 rounded-xl text-gray-400"><DollarSign size={16} /></div>
            <div className={`flex items-center gap-0.5 text-[9px] font-black uppercase ${revVariation >= 0 ? 'text-emerald-500' : 'text-red-500'}`}>
              {revVariation >= 0 ? <TrendingUp size={12} /> : <TrendingDown size={12} />}
              {Math.abs(revVariation).toFixed(1)}%
            </div>
          </div>
          <div>
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-0.5">Vendas Brutas</p>
            <p className="text-xl font-black text-black">R$ {totals.revenue.toLocaleString('pt-BR')}</p>
          </div>
        </div>

        <div className="bg-emerald-50 rounded-[2rem] p-6 border border-emerald-100 shadow-sm space-y-3">
          <div className="flex justify-between items-start">
            <div className="p-2 bg-emerald-100 text-emerald-600 rounded-xl"><Activity size={16} /></div>
            <div className={`flex items-center gap-0.5 text-[9px] font-black uppercase ${profitVariation >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>
              {profitVariation >= 0 ? <TrendingUp size={12} /> : <TrendingDown size={12} />}
              {Math.abs(profitVariation).toFixed(1)}%
            </div>
          </div>
          <div>
            <p className="text-[9px] font-black text-emerald-800/40 uppercase tracking-widest mb-0.5">Lucro Real (Final)</p>
            <p className="text-xl font-black text-emerald-600">R$ {totals.netProfit.toLocaleString('pt-BR')}</p>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] p-8 border border-gray-100 shadow-xl space-y-6">
        <h3 className="text-[10px] font-black text-black uppercase tracking-[0.3em] flex items-center gap-2">
           <Activity size={16} className="text-purple-500" /> Saúde Financeira do Período
        </h3>
        <div className="space-y-4">
          <div className="flex justify-between items-center text-[10px] font-bold text-gray-400 uppercase">
            <span>(+) Vendas + Logística</span>
            <span className="text-black">R$ {(totals.revenue + (totals.shippingBalance > 0 ? totals.shippingBalance : 0)).toFixed(2)}</span>
          </div>
          <div className="flex justify-between items-center text-[10px] font-bold text-red-400 uppercase">
            <span>(-) Custo de Peças</span>
            <span className="font-black">- R$ {totals.cogs.toFixed(2)}</span>
          </div>
          <div className="flex justify-between items-center text-[10px] font-bold text-red-400 uppercase">
            <span>(-) Despesas & Custos Fixos</span>
            <span className="font-black">- R$ {totals.expenses.toFixed(2)}</span>
          </div>
          <div className="h-px bg-gray-100"></div>
          <div className="flex justify-between items-center">
            <span className="text-[11px] font-black uppercase text-black">Lucro Final</span>
            <span className={`text-xl font-black ${totals.netProfit >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>
              R$ {totals.netProfit.toLocaleString('pt-BR')}
            </span>
          </div>
        </div>
      </div>

      {/* Gráfico de Evolução no Rodapé com Cores Corrigidas */}
      <div className="bg-white rounded-[2.5rem] p-8 border border-gray-100 shadow-xl space-y-8">
        <div className="flex justify-between items-center">
          <h3 className="text-[10px] font-black text-black uppercase tracking-[0.3em] flex items-center gap-2">
            <LineChart size={16} className="text-indigo-600" /> Evolução da Lucratividade
          </h3>
          <span className="text-[8px] font-black text-gray-300 uppercase tracking-widest">Saldo Diário (R$)</span>
        </div>

        {chartData.length > 0 ? (
          <div className="h-48 w-full flex items-end gap-2 pt-4">
            {chartData.map((data, i) => {
              const heightPercentage = Math.max(8, ((data.amount - minProfit) / range) * 100);
              return (
                <div key={i} className="flex-1 flex flex-col items-center gap-3 group relative h-full justify-end">
                  <div className="absolute -top-6 left-1/2 -translate-x-1/2 bg-gray-900 text-white text-[8px] font-black px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap z-20">
                    R$ {data.amount.toFixed(0)}
                  </div>

                  <div 
                    className={`w-full rounded-t-lg transition-all duration-700 shadow-sm ${data.amount >= 0 ? 'bg-indigo-600' : 'bg-rose-500'}`}
                    style={{ height: `${heightPercentage}%` }}
                  ></div>

                  <span className="text-[7px] font-black text-gray-400 uppercase tracking-tighter truncate w-full text-center">
                    {data.label}
                  </span>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="h-40 flex flex-col items-center justify-center border-2 border-dashed border-gray-100 rounded-[2rem] space-y-2">
             <Activity size={24} className="text-gray-100" />
             <p className="text-[9px] font-black text-gray-300 uppercase tracking-widest text-center px-10">Aguardando dados de vendas ou custos para gerar evolução</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Analytics;

import React, { useState, useEffect } from 'react';
import { 
  Heart, 
  ShoppingBag, 
  Gem, 
  UserRound, 
  LogOut,
  Wallet,
  LayoutDashboard
} from 'lucide-react';
import { isSupabaseConfigured } from './lib/supabase';
import Dashboard from './components/Dashboard';
import Sales from './components/Sales';
import Inventory from './components/Inventory';
import Customers from './components/Customers';
import Login from './components/Login';
import Analytics from './components/Analytics';
import Expenses from './components/Expenses';

enum View {
  Dashboard = 'dashboard',
  Sales = 'sales',
  Inventory = 'inventory',
  Customers = 'customers',
  Financial = 'financial',
  Expenses = 'expenses'
}

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [currentView, setCurrentView] = useState<View>(View.Dashboard);
  const [configured, setConfigured] = useState<boolean>(true);

  useEffect(() => {
    const isConfigured = isSupabaseConfigured();
    setConfigured(isConfigured);

    if (isConfigured) {
      const session = localStorage.getItem('app_session');
      if (session === 'true') {
        setIsAuthenticated(true);
      }
    }
  }, []);

  if (!configured) return <div className="p-10 text-center">Configuração pendente no Supabase.</div>;
  if (!isAuthenticated) return <Login onLogin={() => setIsAuthenticated(true)} />;

  const renderView = () => {
    switch (currentView) {
      case View.Dashboard: return <Dashboard onNavigate={(v) => setCurrentView(v as View)} />;
      case View.Sales: return <Sales />;
      case View.Inventory: return <Inventory />;
      case View.Customers: return <Customers />;
      case View.Expenses: return <Expenses />;
      case View.Financial: return <Analytics onBack={() => setCurrentView(View.Dashboard)} />;
      default: return <Dashboard onNavigate={(v) => setCurrentView(v as View)} />;
    }
  };

  const NavItem = ({ view, icon: Icon, label }: { view: View, icon: any, label: string }) => (
    <button
      onClick={() => setCurrentView(view)}
      className={`flex flex-col items-center justify-center w-full py-2 transition-all ${
        currentView === view ? 'text-black' : 'text-purple-300'
      }`}
    >
      <div className={`p-2 rounded-2xl transition-all ${currentView === view ? 'bg-white shadow-sm' : ''}`}>
        <Icon size={20} strokeWidth={currentView === view ? 2.5 : 2} />
      </div>
      <span className={`text-[9px] mt-1 font-black uppercase tracking-[0.2em] transition-all ${currentView === view ? 'opacity-100' : 'opacity-60'}`}>
        {label}
      </span>
    </button>
  );

  return (
    <div className="min-h-screen bg-white flex flex-col max-w-md mx-auto shadow-2xl overflow-x-hidden">
      <header className="bg-white border-b border-gray-50 px-6 py-6 sticky top-0 z-20 flex justify-between items-center">
        <div className="flex items-baseline gap-3">
          <span className="text-3xl font-serif-brand font-black text-black">S.</span>
          <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em] mb-1">
            {currentView === View.Financial ? 'Analytics' : currentView}
          </span>
        </div>
        <button 
          onClick={() => {
            localStorage.removeItem('app_session');
            setIsAuthenticated(false);
          }}
          className="p-2 text-gray-200 hover:text-black transition-colors"
        >
          <LogOut size={18} />
        </button>
      </header>

      <main className="flex-1 overflow-y-auto pb-32 px-6 pt-6 no-scrollbar">
        {renderView()}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-[#fefafe] border-t border-purple-50 px-4 py-4 flex justify-around items-center z-30 max-w-md mx-auto shadow-[0_-15px_40px_rgba(147,51,234,0.06)]">
        <NavItem view={View.Dashboard} icon={LayoutDashboard} label="Início" />
        <NavItem view={View.Sales} icon={ShoppingBag} label="Venda" />
        <NavItem view={View.Expenses} icon={Wallet} label="Custos" />
        <NavItem view={View.Inventory} icon={Gem} label="Estoque" />
        <NavItem view={View.Customers} icon={UserRound} label="Clientes" />
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Sparkles, ShoppingBag, AlertCircle, ArrowUpRight, TrendingUp, Heart, Ribbon, ChevronRight, Flower, Gift, Crown, Clock, User } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product, Customer, Sale } from '../types';

interface DashboardProps {
  onNavigate: (view: string) => void;
}

interface InactiveCustomer {
  name: string;
  days: number;
}

const Dashboard: React.FC<DashboardProps> = ({ onNavigate }) => {
  const [stats, setStats] = useState({ revenue: 0, salesCount: 0, previousRevenue: 0 });
  const [monthlyData, setMonthlyData] = useState<{month: string, total: number}[]>([]);
  const [lowStock, setLowStock] = useState<Product[]>([]);
  const [upcomingBirthdays, setUpcomingBirthdays] = useState<Customer[]>([]);
  const [topSpender, setTopSpender] = useState<{ name: string; total: number } | null>(null);
  const [inactiveCustomers, setInactiveCustomers] = useState<InactiveCustomer[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const { data: sales } = await supabase.from('sales').select('*, customer:customers(*)');
      const { data: customers } = await supabase.from('customers').select('*');

      const now = new Date();
      const currentMonth = now.getMonth();
      const currentYear = now.getFullYear();

      if (sales) {
        let currentTotal = 0;
        let prevTotal = 0;
        const monthsMap: Record<string, number> = {};
        const customerSpendMap: Record<string, { name: string, total: number }> = {};

        sales.forEach(sale => {
          const date = new Date(sale.created_at);
          const monthLabel = date.toLocaleString('pt-BR', { month: 'short' });
          const m = date.getMonth();
          const y = date.getFullYear();

          const key = `${monthLabel}/${y.toString().slice(-2)}`;
          monthsMap[key] = (monthsMap[key] || 0) + Number(sale.value);

          if (m === currentMonth && y === currentYear) {
            currentTotal += Number(sale.value);
            // Track spending for top spender
            const customerName = sale.customer?.name || 'Cliente';
            if (!customerSpendMap[customerName]) customerSpendMap[customerName] = { name: customerName, total: 0 };
            customerSpendMap[customerName].total += Number(sale.value);
          } else if (m === (currentMonth === 0 ? 11 : currentMonth - 1) && y === (currentMonth === 0 ? currentYear - 1 : currentYear)) {
            prevTotal += Number(sale.value);
          }
        });

        const sortedMonths = Object.entries(monthsMap)
          .map(([month, total]) => ({ month, total }))
          .slice(-3);

        setMonthlyData(sortedMonths);
        setStats({ 
          revenue: currentTotal, 
          salesCount: sales.filter(s => new Date(s.created_at).getDate() === now.getDate() && new Date(s.created_at).getMonth() === currentMonth).length, 
          previousRevenue: prevTotal 
        });

        // Calculate top spender
        const spender = Object.values(customerSpendMap).sort((a, b) => b.total - a.total)[0];
        setTopSpender(spender || null);
      }

      if (customers) {
        // Logic for upcoming birthdays (next 15 days)
        const upcoming = customers.filter(c => {
          if (!c.birthday) return false;
          const bday = new Date(c.birthday);
          const bdayThisYear = new Date(now.getFullYear(), bday.getMonth(), bday.getDate());
          const diffDays = Math.ceil((bdayThisYear.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
          return diffDays >= 0 && diffDays <= 15;
        }).slice(0, 3);
        setUpcomingBirthdays(upcoming);

        // Logic for inactive customers (> 30 days)
        if (sales) {
          const inactive = customers.map(c => {
            const customerSales = sales.filter(s => s.customer_id === c.id);
            if (customerSales.length === 0) return { name: c.name, days: 999 };
            const lastSale = new Date(customerSales[0].created_at);
            const diff = Math.floor((now.getTime() - lastSale.getTime()) / (1000 * 60 * 60 * 24));
            return { name: c.name, days: diff };
          }).filter(item => item.days >= 30).sort((a, b) => b.days - a.days).slice(0, 3);
          setInactiveCustomers(inactive);
        }
      }

      const { data: products } = await supabase.from('products').select('*').lt('stock', 3);
      if (products) setLowStock(products);
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  const growth = stats.previousRevenue > 0 ? ((stats.revenue - stats.previousRevenue) / stats.previousRevenue) * 100 : 0;

  if (loading) return <div className="p-10 animate-pulse text-center text-[10px] font-black uppercase tracking-widest text-gray-300">Sincronizando Boutique...</div>;

  return (
    <div className="space-y-6">
      {/* Revenue Card */}
      <div className="bg-gray-950 rounded-[2.5rem] p-7 text-white shadow-2xl relative overflow-hidden border border-white/5">
        <div className="absolute -right-10 -top-10 p-8 opacity-10 blur-2xl bg-purple-500 w-40 h-40 rounded-full"></div>
        <div className="absolute right-6 top-6 opacity-20">
          <Sparkles size={40} className="text-purple-300" />
        </div>

        <div className="relative z-10 space-y-6">
          <div className="flex justify-between items-center">
            <span className="text-[10px] font-black uppercase tracking-[0.3em] opacity-50">Fluxo da Boutique</span>
            <div className={`flex items-center gap-1 px-3 py-1 rounded-full text-[10px] font-black ${growth >= 0 ? 'bg-emerald-500/20 text-emerald-400' : 'bg-red-500/20 text-red-400'}`}>
              {growth >= 0 ? '+' : ''}{growth.toFixed(1)}% performance
            </div>
          </div>

          <div>
            <p className="text-4xl font-black tracking-tighter mb-1">
              R$ {stats.revenue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
            </p>
            <p className="text-[9px] font-bold text-white/30 uppercase tracking-widest">Saldo Atual {new Date().toLocaleString('pt-BR', { month: 'long' })}</p>
          </div>

          <div className="h-px bg-white/10 w-full border-t border-dashed border-white/20"></div>

          <div className="grid grid-cols-3 gap-4">
            {monthlyData.map((data, i) => (
              <div key={i} className="space-y-1">
                <p className="text-[8px] font-black text-white/30 uppercase tracking-widest">{data.month}</p>
                <p className="text-xs font-black">R$ {data.total > 1000 ? (data.total / 1000).toFixed(1) + 'k' : data.total.toFixed(0)}</p>
              </div>
            ))}
          </div>

          <button 
            onClick={() => onNavigate('financial')}
            className="w-full bg-white/5 hover:bg-white/10 border border-white/10 py-4 rounded-2xl flex items-center justify-center gap-2 transition-all group"
          >
            <span className="text-[10px] font-black uppercase tracking-widest">Análise Financeira Completa</span>
            <ArrowUpRight size={14} className="group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-transform" />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white border border-gray-100 rounded-[2rem] p-6 shadow-sm">
          <div className="bg-pink-50 w-10 h-10 rounded-2xl flex items-center justify-center mb-4">
            <Ribbon size={20} className="text-pink-400" />
          </div>
          <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Vendas do Dia</p>
          <p className="text-2xl font-black text-gray-900">{stats.salesCount}</p>
        </div>

        <div className="bg-white border border-gray-100 rounded-[2rem] p-6 shadow-sm">
          <div className="bg-purple-50 w-10 h-10 rounded-2xl flex items-center justify-center mb-4">
            <Flower size={20} className="text-purple-400" />
          </div>
          <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Reposição</p>
          <p className="text-2xl font-black text-red-600">{lowStock.length}</p>
        </div>
      </div>

      {/* Seção de Inteligência & CRM */}
      <div className="bg-white border border-gray-100 rounded-[2.5rem] overflow-hidden shadow-sm space-y-4 p-2">
        <div className="px-4 py-3 border-b border-gray-50 flex items-center gap-2">
           <TrendingUp size={16} className="text-indigo-400" />
           <h2 className="text-[11px] font-black text-gray-900 uppercase tracking-[0.2em]">Inteligência CRM</h2>
        </div>

        <div className="px-4 space-y-4 pb-4">
          {/* Top Spender */}
          {topSpender && (
            <div className="bg-indigo-50/50 p-4 rounded-3xl border border-indigo-100 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-indigo-500 rounded-2xl flex items-center justify-center text-white">
                  <Crown size={18} />
                </div>
                <div>
                  <p className="text-[9px] font-black text-indigo-400 uppercase tracking-widest">Estrela do Mês</p>
                  <p className="text-xs font-black text-gray-900 uppercase">{topSpender.name}</p>
                </div>
              </div>
              <p className="text-sm font-black text-indigo-600">R$ {topSpender.total.toFixed(0)}</p>
            </div>
          )}

          {/* Birthdays */}
          {upcomingBirthdays.length > 0 && (
            <div className="bg-pink-50/50 p-4 rounded-3xl border border-pink-100 space-y-3">
              <div className="flex items-center gap-2 text-pink-400">
                <Gift size={14} />
                <span className="text-[9px] font-black uppercase tracking-widest">Próximos 15 dias</span>
              </div>
              <div className="space-y-2">
                {upcomingBirthdays.map(c => (
                  <div key={c.id} className="flex justify-between items-center">
                    <p className="text-[10px] font-bold text-gray-700 uppercase">{c.name}</p>
                    <p className="text-[8px] font-black text-pink-500 bg-white px-2 py-1 rounded-lg shadow-sm uppercase">
                      {c.birthday ? new Date(c.birthday).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }) : ''}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Inactive Recovery */}
          {inactiveCustomers.length > 0 && (
            <div className="bg-amber-50/50 p-4 rounded-3xl border border-amber-100 space-y-3">
              <div className="flex items-center gap-2 text-amber-500">
                <Clock size={14} />
                <span className="text-[9px] font-black uppercase tracking-widest">Recuperação (+30 dias)</span>
              </div>
              <div className="space-y-2">
                {inactiveCustomers.map((item, idx) => (
                  <div key={idx} className="flex justify-between items-center group cursor-pointer" onClick={() => onNavigate('customers')}>
                    <p className="text-[10px] font-bold text-gray-700 uppercase">{item.name}</p>
                    <p className="text-[8px] font-black text-amber-600 uppercase tracking-tighter">Há {item.days} dias</p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Alerta de Estoque */}
      <div className="bg-white border border-gray-100 rounded-[2.5rem] overflow-hidden shadow-sm">
        <div className="px-6 py-5 border-b border-gray-50 flex justify-between items-center bg-gray-50/30">
          <h2 className="text-[11px] font-black text-gray-900 uppercase tracking-[0.2em] flex items-center gap-2">
            <AlertCircle size={14} className="text-amber-400" />
            Reposição Urgente
          </h2>
        </div>
        <div className="divide-y divide-gray-50">
          {lowStock.length > 0 ? (
            lowStock.map(product => (
              <button 
                key={product.id} 
                onClick={() => onNavigate('inventory')}
                className="w-full px-6 py-4 flex justify-between items-center hover:bg-gray-50 transition-colors text-left"
              >
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 rounded-xl bg-purple-50 flex items-center justify-center text-purple-300">
                    <Sparkles size={16} />
                  </div>
                  <div>
                    <p className="text-xs font-black text-gray-900 uppercase tracking-tight">{product.name}</p>
                    <p className="text-[9px] text-gray-400 font-bold tracking-widest uppercase">{product.reference_code || 'S/ REF'}</p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <div className="text-right">
                    <p className="text-xs font-black text-red-600">{product.stock} un</p>
                  </div>
                  <ChevronRight size={14} className="text-gray-200" />
                </div>
              </button>
            ))
          ) : (
            <div className="p-12 text-center">
              <p className="text-xs text-gray-200 font-black uppercase tracking-widest">Estoque Impecável ✨</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

