import Customers from './components/Customers';
import Login from './components/Login';
import Analytics from './components/Analytics';
import Expenses from './components/Expenses';

enum View {
  Dashboard = 'dashboard',
  Sales = 'sales',
  Inventory = 'inventory',
  Customers = 'customers',
  Financial = 'financial',
  Expenses = 'expenses'
}

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [currentView, setCurrentView] = useState<View>(View.Dashboard);
  const [configured, setConfigured] = useState<boolean>(true);

  useEffect(() => {
    const isConfigured = isSupabaseConfigured();
    setConfigured(isConfigured);

    if (isConfigured) {
      const session = localStorage.getItem('app_session');
      if (session === 'true') {
        setIsAuthenticated(true);
      }
    }
  }, []);

  if (!configured) return <div className="p-10 text-center">Configuração pendente no Supabase.</div>;
  if (!isAuthenticated) return <Login onLogin={() => setIsAuthenticated(true)} />;

  const renderView = () => {
    switch (currentView) {
      case View.Dashboard: return <Dashboard onNavigate={(v) => setCurrentView(v as View)} />;
      case View.Sales: return <Sales />;
      case View.Inventory: return <Inventory />;
      case View.Customers: return <Customers />;
      case View.Expenses: return <Expenses />;
      case View.Financial: return <Analytics onBack={() => setCurrentView(View.Dashboard)} />;
      default: return <Dashboard onNavigate={(v) => setCurrentView(v as View)} />;
    }
  };

  const NavItem = ({ view, icon: Icon, label }: { view: View, icon: any, label: string }) => (
    <button
      onClick={() => setCurrentView(view)}
      className={`flex flex-col items-center justify-center w-full py-2 transition-all ${
        currentView === view ? 'text-black' : 'text-purple-300'
      }`}
    >
      <div className={`p-2 rounded-2xl transition-all ${currentView === view ? 'bg-white shadow-sm' : ''}`}>
        <Icon size={20} strokeWidth={currentView === view ? 2.5 : 2} />
      </div>
      <span className={`text-[9px] mt-1 font-black uppercase tracking-[0.2em] transition-all ${currentView === view ? 'opacity-100' : 'opacity-60'}`}>
        {label}
      </span>
    </button>
  );

  return (
    <div className="min-h-screen bg-white flex flex-col max-w-md mx-auto shadow-2xl overflow-x-hidden">
      <header className="bg-white border-b border-gray-50 px-6 py-6 sticky top-0 z-20 flex justify-between items-center">
        <div className="flex items-baseline gap-3">
          <span className="text-3xl font-serif-brand font-black text-black">S.</span>
          <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em] mb-1">
            {currentView === View.Financial ? 'Analytics' : currentView}
          </span>
        </div>
        <button 
          onClick={() => {
            localStorage.removeItem('app_session');
            setIsAuthenticated(false);
          }}
          className="p-2 text-gray-200 hover:text-black transition-colors"
        >
          <LogOut size={18} />
        </button>
      </header>

      <main className="flex-1 overflow-y-auto pb-32 px-6 pt-6 no-scrollbar">
        {renderView()}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-[#fefafe] border-t border-purple-50 px-4 py-4 flex justify-around items-center z-30 max-w-md mx-auto shadow-[0_-15px_40px_rgba(147,51,234,0.06)]">
        <NavItem view={View.Dashboard} icon={LayoutDashboard} label="Início" />
        <NavItem view={View.Sales} icon={ShoppingBag} label="Venda" />
        <NavItem view={View.Expenses} icon={Wallet} label="Custos" />
        <NavItem view={View.Inventory} icon={Gem} label="Estoque" />
        <NavItem view={View.Customers} icon={UserRound} label="Clientes" />
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Sparkles, ShoppingBag, AlertCircle, ArrowUpRight, TrendingUp, Ribbon, ChevronRight, Flower, Gift, Crown, Clock } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product, Customer, Sale } from '../types';

interface DashboardProps {
  onNavigate: (view: string) => void;
}

interface InactiveCustomer {
  name: string;
  days: number;
}

const Dashboard: React.FC<DashboardProps> = ({ onNavigate }) => {
  const [stats, setStats] = useState({ revenue: 0, salesCount: 0, previousRevenue: 0 });
  const [monthlyData, setMonthlyData] = useState<{month: string, total: number}[]>([]);
  const [lowStock, setLowStock] = useState<Product[]>([]);
  const [upcomingBirthdays, setUpcomingBirthdays] = useState<Customer[]>([]);
  const [topSpender, setTopSpender] = useState<{ name: string; total: number } | null>(null);
  const [inactiveCustomers, setInactiveCustomers] = useState<InactiveCustomer[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const { data: sales } = await supabase.from('sales').select('*, customer:customers(*)');
      const { data: customers } = await supabase.from('customers').select('*');

      const now = new Date();
      const todayISO = now.toISOString().split('T')[0];
      const currentMonth = now.getMonth();
      const currentYear = now.getFullYear();

      if (sales) {
        let currentMonthTotal = 0;
        let prevMonthTotal = 0;
        let todaySalesCount = 0;
        const monthsMap: Record<string, number> = {};
        const customerSpendMap: Record<string, { name: string, total: number }> = {};

        sales.forEach(sale => {
          const date = new Date(sale.created_at);
          const saleISO = date.toISOString().split('T')[0];
          const monthLabel = date.toLocaleString('pt-BR', { month: 'short' });
          const m = date.getMonth();
          const y = date.getFullYear();

          const key = `${monthLabel}/${y.toString().slice(-2)}`;
          monthsMap[key] = (monthsMap[key] || 0) + Number(sale.value);

          // Vendas do Dia (Corrected logic using ISO comparison)
          if (saleISO === todayISO) {
            todaySalesCount++;
          }

          if (m === currentMonth && y === currentYear) {
            currentMonthTotal += Number(sale.value);
            // Track spending for top spender in current month
            const customerName = sale.customer?.name || 'Cliente';
            if (!customerSpendMap[customerName]) customerSpendMap[customerName] = { name: customerName, total: 0 };
            customerSpendMap[customerName].total += Number(sale.value);
          } else if (m === (currentMonth === 0 ? 11 : currentMonth - 1) && y === (currentMonth === 0 ? currentYear - 1 : currentYear)) {
            prevMonthTotal += Number(sale.value);
          }
        });

        const sortedMonths = Object.entries(monthsMap)
          .map(([month, total]) => ({ month, total }))
          .slice(-3);

        setMonthlyData(sortedMonths);
        setStats({ 
          revenue: currentMonthTotal, 
          salesCount: todaySalesCount, 
          previousRevenue: prevMonthTotal 
        });

        // Calculate top spender of the month
        const spender = Object.values(customerSpendMap).sort((a, b) => b.total - a.total)[0];
        setTopSpender(spender || null);
      }

      if (customers) {
        // Logic for upcoming birthdays (next 15 days)
        const upcoming = customers.filter(c => {
          if (!c.birthday) return false;
          const bday = new Date(c.birthday);
          const bdayThisYear = new Date(now.getFullYear(), bday.getMonth(), bday.getDate());

          // Se o aniversário já passou este ano (ex: Jan e estamos em Out), considera o próximo ano para o cálculo de proximidade correta
          if (bdayThisYear < now) {
            bdayThisYear.setFullYear(now.getFullYear() + 1);
          }

          const diffDays = Math.ceil((bdayThisYear.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
          return diffDays >= 0 && diffDays <= 15;
        }).slice(0, 3);
        setUpcomingBirthdays(upcoming);

        // Logic for inactive customers (> 30 days)
        if (sales) {
          const inactive = customers.map(c => {
            const customerSales = sales
              .filter(s => s.customer_id === c.id)
              .sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());

            if (customerSales.length === 0) return { name: c.name, days: 999 };
            const lastSale = new Date(customerSales[0].created_at);
            const diff = Math.floor((now.getTime() - lastSale.getTime()) / (1000 * 60 * 60 * 24));
            return { name: c.name, days: diff };
          }).filter(item => item.days >= 30).sort((a, b) => b.days - a.days).slice(0, 3);
          setInactiveCustomers(inactive);
        }
      }

      const { data: products } = await supabase.from('products').select('*').lt('stock', 3);
      if (products) setLowStock(products);
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  const growth = stats.previousRevenue > 0 ? ((stats.revenue - stats.previousRevenue) / stats.previousRevenue) * 100 : 0;

  if (loading) return <div className="p-10 animate-pulse text-center text-[10px] font-black uppercase tracking-widest text-gray-300">Sincronizando Boutique...</div>;

  return (
    <div className="space-y-6">
      {/* Revenue Card */}
      <div className="bg-gray-950 rounded-[2.5rem] p-7 text-white shadow-2xl relative overflow-hidden border border-white/5">
        <div className="absolute -right-10 -top-10 p-8 opacity-10 blur-2xl bg-purple-500 w-40 h-40 rounded-full"></div>
        <div className="absolute right-6 top-6 opacity-20">
          <Sparkles size={40} className="text-purple-300" />
        </div>

        <div className="relative z-10 space-y-6">
          <div className="flex justify-between items-center">
            <span className="text-[10px] font-black uppercase tracking-[0.3em] opacity-50">Fluxo da Boutique</span>
            <div className={`flex items-center gap-1 px-3 py-1 rounded-full text-[10px] font-black ${growth >= 0 ? 'bg-emerald-500/20 text-emerald-400' : 'bg-red-500/20 text-red-400'}`}>
              {growth >= 0 ? '+' : ''}{growth.toFixed(1)}% performance
            </div>
          </div>

          <div>
            <p className="text-4xl font-black tracking-tighter mb-1">
              R$ {stats.revenue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
            </p>
            <p className="text-[9px] font-bold text-white/30 uppercase tracking-widest">Saldo Atual {new Date().toLocaleString('pt-BR', { month: 'long' })}</p>
          </div>

          <div className="h-px bg-white/10 w-full border-t border-dashed border-white/20"></div>

          <div className="grid grid-cols-3 gap-4">
            {monthlyData.map((data, i) => (
              <div key={i} className="space-y-1">
                <p className="text-[8px] font-black text-white/30 uppercase tracking-widest">{data.month}</p>
                <p className="text-xs font-black">R$ {data.total > 1000 ? (data.total / 1000).toFixed(1) + 'k' : data.total.toFixed(0)}</p>
              </div>
            ))}
          </div>

          <button 
            onClick={() => onNavigate('financial')}
            className="w-full bg-white/5 hover:bg-white/10 border border-white/10 py-4 rounded-2xl flex items-center justify-center gap-2 transition-all group"
          >
            <span className="text-[10px] font-black uppercase tracking-widest">Análise Financeira Completa</span>
            <ArrowUpRight size={14} className="group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-transform" />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white border border-gray-100 rounded-[2rem] p-6 shadow-sm flex flex-col items-center text-center">
          <div className="bg-pink-50 w-12 h-12 rounded-2xl flex items-center justify-center mb-4">
            <Ribbon size={24} className="text-pink-400" />
          </div>
          <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Vendas do Dia</p>
          <p className="text-2xl font-black text-gray-900">{stats.salesCount}</p>
        </div>

        <div className="bg-white border border-gray-100 rounded-[2rem] p-6 shadow-sm flex flex-col items-center text-center">
          <div className="bg-purple-50 w-12 h-12 rounded-2xl flex items-center justify-center mb-4">
            <Flower size={24} className="text-purple-400" />
          </div>
          <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Reposição</p>
          <p className="text-2xl font-black text-red-600">{lowStock.length}</p>
        </div>
      </div>

      {/* Seção de Inteligência & CRM */}
      <div className="bg-white border border-gray-100 rounded-[2.5rem] overflow-hidden shadow-sm space-y-4 p-2">
        <div className="px-4 py-3 border-b border-gray-50 flex items-center gap-2">
           <TrendingUp size={16} className="text-indigo-400" />
           <h2 className="text-[11px] font-black text-gray-900 uppercase tracking-[0.2em]">Inteligência CRM</h2>
        </div>

        <div className="px-4 space-y-4 pb-4">
          {/* Top Spender */}
          {topSpender && (
            <div className="bg-indigo-50/50 p-4 rounded-3xl border border-indigo-100 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-indigo-500 rounded-2xl flex items-center justify-center text-white">
                  <Crown size={18} />
                </div>
                <div>
                  <p className="text-[9px] font-black text-indigo-400 uppercase tracking-widest">Estrela do Mês</p>
                  <p className="text-xs font-black text-gray-900 uppercase">{topSpender.name}</p>
                </div>
              </div>
              <p className="text-sm font-black text-indigo-600">R$ {topSpender.total.toFixed(0)}</p>
            </div>
          )}

          {/* Birthdays */}
          {upcomingBirthdays.length > 0 && (
            <div className="bg-pink-50/50 p-4 rounded-3xl border border-pink-100 space-y-3">
              <div className="flex items-center gap-2 text-pink-400">
                <Gift size={14} />
                <span className="text-[9px] font-black uppercase tracking-widest">Aniversariantes (Próx. 15 dias)</span>
              </div>
              <div className="space-y-2">
                {upcomingBirthdays.map(c => (
                  <div key={c.id} className="flex justify-between items-center">
                    <p className="text-[10px] font-bold text-gray-700 uppercase">{c.name}</p>
                    <p className="text-[8px] font-black text-pink-500 bg-white px-2 py-1 rounded-lg shadow-sm uppercase">
                      {c.birthday ? new Date(c.birthday).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }) : ''}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Inactive Recovery */}
          {inactiveCustomers.length > 0 && (
            <div className="bg-amber-50/50 p-4 rounded-3xl border border-amber-100 space-y-3">
              <div className="flex items-center gap-2 text-amber-500">
                <Clock size={14} />
                <span className="text-[9px] font-black uppercase tracking-widest">Recuperação (+30 dias)</span>
              </div>
              <div className="space-y-2">
                {inactiveCustomers.map((item, idx) => (
                  <div key={idx} className="flex justify-between items-center group cursor-pointer" onClick={() => onNavigate('customers')}>
                    <p className="text-[10px] font-bold text-gray-700 uppercase">{item.name}</p>
                    <p className="text-[8px] font-black text-amber-600 uppercase tracking-tighter">Há {item.days} dias</p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Alerta de Estoque - Reposição Urgente */}
      <div className="bg-white border border-gray-100 rounded-[2.5rem] overflow-hidden shadow-sm">
        <div className="px-6 py-5 border-b border-gray-50 flex justify-between items-center bg-gray-50/30">
          <h2 className="text-[11px] font-black text-gray-900 uppercase tracking-[0.2em] flex items-center gap-2">
            <AlertCircle size={14} className="text-amber-400" />
            Reposição Urgente
          </h2>
        </div>
        <div className="divide-y divide-gray-50">
          {lowStock.length > 0 ? (
            lowStock.map(product => (
              <button 
                key={product.id} 
                onClick={() => onNavigate('inventory')}
                className="w-full px-6 py-4 flex justify-between items-center hover:bg-gray-50 transition-colors text-left"
              >
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 rounded-xl bg-purple-50 flex items-center justify-center text-purple-300">
                    <Sparkles size={16} />
                  </div>
                  <div>
                    <p className="text-xs font-black text-gray-900 uppercase tracking-tight">{product.name}</p>
                    <p className="text-[9px] text-gray-400 font-bold tracking-widest uppercase">{product.reference_code || 'S/ REF'}</p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <div className="text-right">
                    <p className="text-xs font-black text-red-600">{product.stock} un</p>
                  </div>
                  <ChevronRight size={14} className="text-gray-200" />
                </div>
              </button>
            ))
          ) : (
            <div className="p-12 text-center">
              <p className="text-xs text-gray-200 font-black uppercase tracking-widest">Estoque Impecável ✨</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { Plus, ShoppingBag, User, Package, DollarSign, Calendar, X, Search, Filter, Trash2, CreditCard, Banknote, QrCode, ReceiptText, Printer, Share2, Truck, Check } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product, Customer, Sale } from '../types';

interface CartItem {
  product: Product;
  amount: number;
}

const Sales: React.FC = () => {
  const [sales, setSales] = useState<Sale[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterToday, setFilterToday] = useState(false);

  const [selectedOrderItems, setSelectedOrderItems] = useState<Sale[] | null>(null);

  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedProductId, setSelectedProductId] = useState('');
  const [selectedProductQty, setSelectedProductQty] = useState(1);

  const [formData, setFormData] = useState({
    customerId: '',
    discount: '0',
    discountDescription: '',
    paymentMethod: 'pix',
    shippingCharged: '0',
    shippingCost: '0',
    date: new Date().toISOString().split('T')[0]
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const { data: s } = await supabase.from('sales').select('*, customer:customers(*), product:products(*)').order('created_at', { ascending: false });
      const { data: p } = await supabase.from('products').select('*');
      const { data: c } = await supabase.from('customers').select('*');
      if (s) setSales(s);
      if (p) setProducts(p);
      if (c) setCustomers(c);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleShowReceipt = (orderId: string) => {
    const orderItems = sales.filter(s => s.order_id === orderId);
    if (orderItems.length > 0) {
      setSelectedOrderItems(orderItems);
    }
  };

  const addToCart = () => {
    if (!selectedProductId) return;
    const prod = products.find(p => p.id === selectedProductId);
    if (!prod) return;

    if (selectedProductQty > prod.stock) {
      alert(`⚠️ Estoque insuficiente! (${prod.stock} un disponíveis)`);
      return;
    }

    setCart([...cart, { product: prod, amount: selectedProductQty }]);
    setSelectedProductId('');
    setSelectedProductQty(1);
  };

  const removeFromCart = (index: number) => {
    setCart(cart.filter((_, i) => i !== index));
  };

  const cartTotal = cart.reduce((acc, item) => acc + (item.product.price * item.amount), 0);
  const shippingCharge = parseFloat(formData.shippingCharged.replace(',', '.')) || 0;
  const shippingCost = parseFloat(formData.shippingCost.replace(',', '.')) || 0;
  const finalTotal = Math.max(0, cartTotal + shippingCharge - (parseFloat(formData.discount.replace(',', '.')) || 0));
  const shippingBalance = shippingCharge - shippingCost;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.customerId || cart.length === 0) {
      alert('Selecione uma cliente e adicione itens ao carrinho.');
      return;
    }

    setLoading(true);
    try {
      const orderId = crypto.randomUUID();
      const totalDiscount = parseFloat(formData.discount.replace(',', '.')) || 0;

      const discountPerItem = cart.length > 0 ? totalDiscount / cart.length : 0;

      const salesPayload = cart.map(item => ({
        order_id: orderId,
        customer_id: formData.customerId,
        product_id: item.product.id,
        amount: item.amount,
        value: (item.product.price * item.amount) - discountPerItem,
        discount: discountPerItem,
        discount_description: formData.discountDescription,
        payment_method: formData.paymentMethod,
        shipping_charged: shippingCharge / cart.length,
        shipping_cost: shippingCost / cart.length,
        created_at: formData.date
      }));

      const { error: saleError } = await supabase.from('sales').insert(salesPayload);
      if (saleError) throw saleError;

      for (const item of cart) {
        await supabase.from('products').update({ stock: item.product.stock - item.amount }).eq('id', item.product.id);
      }

      setShowForm(false);
      setCart([]);
      setFormData({
        customerId: '',
        discount: '0',
        discountDescription: '',
        paymentMethod: 'pix',
        shippingCharged: '0',
        shippingCost: '0',
        date: new Date().toISOString().split('T')[0]
      });
      fetchData();
      alert('Nota emitida com sucesso! ✨');
    } catch (err) {
      console.error(err);
      alert('Erro ao processar venda.');
    } finally {
      setLoading(false);
    }
  };

  const todayStr = new Date().toISOString().split('T')[0];

  const filteredSales = sales.filter(s => {
    const matchesSearch = s.customer?.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         s.product?.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesDate = filterToday ? s.created_at.split('T')[0] === todayStr : true;
    return matchesSearch && matchesDate;
  });

  return (
    <div className="space-y-6">
      <div className="flex items-stretch gap-3">
        <div className="relative flex-1">
          <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
          <input 
            type="text" 
            placeholder="Buscar nota ou cliente..."
            className="w-full h-full bg-gray-50 border border-gray-100 rounded-2xl py-4 pl-12 pr-4 text-xs font-bold outline-none text-black focus:border-black transition-all"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>
        <button 
          onClick={() => setShowForm(!showForm)}
          className={`w-14 h-14 rounded-2xl shadow-xl transition-all flex items-center justify-center shrink-0 ${showForm ? 'bg-white border border-gray-100 text-black' : 'bg-black text-white'}`}
        >
          {showForm ? <X size={20} /> : <Plus size={24} />}
        </button>
      </div>

      {showForm ? (
        <form onSubmit={handleSubmit} className="bg-white rounded-[2.5rem] p-8 shadow-2xl space-y-6 border border-gray-50 animate-in slide-in-from-top-4 duration-300">
          <div className="space-y-5">
            <div>
              <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block">Cliente</label>
              <select 
                className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none"
                value={formData.customerId}
                onChange={e => setFormData({...formData, customerId: e.target.value})}
                required
              >
                <option value="">Selecionar Cliente</option>
                {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
