              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[8px] font-black text-purple-300 uppercase block mb-1">Cobrado da Cliente</label>
                  <input type="text" placeholder="0,00" className="w-full bg-white border border-purple-100 rounded-xl py-3 px-4 text-xs font-bold text-black outline-none" value={formData.shippingCharged} onChange={e => setFormData({...formData, shippingCharged: e.target.value})} />
                </div>
                <div>
                  <label className="text-[8px] font-black text-purple-300 uppercase block mb-1">Custo Real (Pago)</label>
                  <input type="text" placeholder="0,00" className="w-full bg-white border border-purple-100 rounded-xl py-3 px-4 text-xs font-bold text-black outline-none" value={formData.shippingCost} onChange={e => setFormData({...formData, shippingCost: e.target.value})} />
                </div>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block">Pagamento</label>
                <div className="grid grid-cols-3 gap-2">
                  <button type="button" onClick={() => setFormData({...formData, paymentMethod: 'cartao'})} className={`p-3 rounded-xl flex justify-center border transition-all ${formData.paymentMethod === 'cartao' ? 'bg-black text-white border-black' : 'bg-gray-50 text-gray-300 border-gray-200'}`}><CreditCard size={18}/></button>
                  <button type="button" onClick={() => setFormData({...formData, paymentMethod: 'dinheiro'})} className={`p-3 rounded-xl flex justify-center border transition-all ${formData.paymentMethod === 'dinheiro' ? 'bg-black text-white border-black' : 'bg-gray-50 text-gray-300 border-gray-200'}`}><Banknote size={18}/></button>
                  <button type="button" onClick={() => setFormData({...formData, paymentMethod: 'pix'})} className={`p-3 rounded-xl flex justify-center border transition-all ${formData.paymentMethod === 'pix' ? 'bg-black text-white border-black' : 'bg-gray-50 text-gray-300 border-gray-200'}`}><QrCode size={18}/></button>
                </div>
              </div>
              <div>
                <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 block">Desconto (R$)</label>
                <input type="text" placeholder="0,00" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-red-500 outline-none" value={formData.discount} onChange={e => setFormData({...formData, discount: e.target.value})} />
              </div>
            </div>

            <div className="bg-gray-950 p-7 rounded-[2rem] text-white flex justify-between items-center shadow-2xl">
              <div>
                <span className="text-[9px] font-black text-white/40 uppercase tracking-[0.3em]">Total Geral</span>
                <p className="text-2xl font-black">R$ {finalTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
              </div>
              <ShoppingBag size={24} className="text-white/20" />
            </div>

            <input type="date" className="w-full bg-gray-50 border border-gray-200 rounded-2xl py-4 px-6 text-xs font-bold text-black outline-none" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} required />
          </div>

          <button type="submit" className="w-full bg-black text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-xl active:scale-95 transition-all">Finalizar Nota</button>
        </form>
      ) : (
        <div className="space-y-4">
          <div className="flex items-center justify-between px-2">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">Notas Emitidas</h3>

            <button 
              onClick={() => setFilterToday(!filterToday)}
              className={`flex items-center gap-2 px-4 py-2 rounded-full border transition-all ${filterToday ? 'bg-black text-white border-black' : 'bg-white text-gray-400 border-gray-100'}`}
            >
              {filterToday && <Check size={12} />}
              <span className="text-[9px] font-black uppercase tracking-widest">{filterToday ? 'Hoje' : 'Todas'}</span>
            </button>
          </div>

          <div className="bg-white rounded-[2.5rem] border border-gray-50 shadow-sm overflow-hidden divide-y divide-gray-50">
            {loading ? (
              <div className="p-20 text-center text-gray-300 text-[10px] font-black uppercase animate-pulse">Buscando Notas...</div>
            ) : filteredSales.length > 0 ? (
              filteredSales.map(sale => (
                <div 
                  key={sale.id} 
                  onClick={() => handleShowReceipt(sale.order_id)}
                  className="p-6 flex items-center justify-between hover:bg-gray-50/50 transition-colors cursor-pointer active:scale-[0.99]"
                >
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 rounded-2xl bg-indigo-50 flex items-center justify-center text-indigo-600 shadow-sm">
                      <ShoppingBag size={20} />
                    </div>
                    <div>
                      <p className="text-xs font-black text-black uppercase tracking-tight">{sale.customer?.name}</p>
                      <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest">{sale.product?.name} ({sale.amount}x)</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-xs font-black text-black">R$ {Number(sale.value + (sale.shipping_charged || 0)).toFixed(2)}</p>
                    <p className="text-[8px] text-gray-300 font-bold uppercase mt-1">{new Date(sale.created_at).toLocaleDateString('pt-BR')}</p>
                  </div>
                </div>
              ))
            ) : (
              <div className="p-20 text-center text-gray-200 text-[10px] font-black uppercase tracking-widest">
                {filterToday ? 'Nenhuma nota hoje' : 'Nenhuma nota emitida'}
              </div>
            )}
          </div>
        </div>
      )}

      {selectedOrderItems && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-6 bg-black/40 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-sm rounded-[2rem] p-8 shadow-2xl relative overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="border-t-8 border-black absolute top-0 left-0 right-0"></div>

            <button 
              onClick={() => setSelectedOrderItems(null)}
              className="absolute right-6 top-6 w-10 h-10 rounded-full bg-gray-50 flex items-center justify-center text-gray-400"
            >
              <X size={18} />
            </button>

            <div className="space-y-8 mt-4">
              <div className="text-center space-y-2">
                <h2 className="text-4xl font-serif-brand font-black text-black">S.</h2>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.5em]">Sensitive Shop</p>
              </div>

              <div className="space-y-1">
                <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Cliente</p>
                <p className="text-sm font-black text-black uppercase tracking-tight">{selectedOrderItems[0].customer?.name}</p>
              </div>

              <div className="space-y-4">
                <div className="border-y border-dashed border-gray-200 py-3 grid grid-cols-12 text-[8px] font-black text-gray-400 uppercase tracking-widest">
                  <span className="col-span-8">Item</span>
                  <span className="col-span-4 text-right">Subtotal</span>
                </div>

                <div className="space-y-3">
                  {selectedOrderItems.map((item, idx) => (
                    <div key={idx} className="grid grid-cols-12 items-start text-[10px] font-bold text-black uppercase">
                      <div className="col-span-8 leading-tight">
                        {item.product?.name}
                        <p className="text-[7px] text-gray-400 font-bold mt-0.5">Qt: {item.amount}</p>
                      </div>
                      <span className="col-span-4 text-right font-black">R$ {Number(item.value).toFixed(2)}</span>
                    </div>
                  ))}
                </div>

                <div className="border-t border-dashed border-gray-200 pt-4 space-y-2">
                  <div className="flex justify-between items-center text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                    <span>Frete Cobrado</span>
                    <span className="text-black font-black">R$ {(selectedOrderItems.reduce((acc, i) => acc + (i.shipping_charged || 0), 0)).toFixed(2)}</span>
                  </div>
                  {selectedOrderItems[0].discount > 0 && (
                    <div className="flex justify-between items-center text-[10px] font-bold text-red-400 uppercase tracking-widest">
                      <span>Desconto</span>
                      <span className="font-black">- R$ {(selectedOrderItems.reduce((acc, i) => acc + (i.discount || 0), 0)).toFixed(2)}</span>
                    </div>
                  )}
                  <div className="flex justify-between items-center pt-2">
                    <span className="text-xs font-black text-black uppercase tracking-widest">Total Geral</span>
                    <span className="text-xl font-black text-black">
                      R$ {selectedOrderItems.reduce((acc, i) => acc + Number(i.value) + Number(i.shipping_charged || 0), 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                    </span>
                  </div>
                </div>
              </div>

              <div className="text-center pt-4">
                <button 
                  onClick={() => setSelectedOrderItems(null)}
                  className="w-full bg-black text-white py-4 rounded-xl font-black text-[9px] uppercase tracking-widest"
                >
                  Fechar Nota
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Sales;

import React, { useState, useEffect } from 'react';
import { Sparkles, ShoppingBag, AlertCircle, ArrowUpRight, TrendingUp, Ribbon, ChevronRight, Flower, Gift, Crown, Clock } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { Product, Customer, Sale } from '../types';

interface DashboardProps {
  onNavigate: (view: string) => void;
}

interface InactiveCustomer {
  name: string;
  days: number;
}

const Dashboard: React.FC<DashboardProps> = ({ onNavigate }) => {
  const [stats, setStats] = useState({ revenue: 0, salesCount: 0, previousRevenue: 0 });
  const [monthlyData, setMonthlyData] = useState<{month: string, total: number}[]>([]);
  const [lowStock, setLowStock] = useState<Product[]>([]);
  const [upcomingBirthdays, setUpcomingBirthdays] = useState<Customer[]>([]);
  const [topSpender, setTopSpender] = useState<{ name: string; total: number } | null>(null);
  const [inactiveCustomers, setInactiveCustomers] = useState<InactiveCustomer[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const { data: sales } = await supabase.from('sales').select('*, customer:customers(*)');
      const { data: customers } = await supabase.from('customers').select('*');

      const now = new Date();
      const todayISO = now.toISOString().split('T')[0];
      const currentMonth = now.getMonth();
      const currentYear = now.getFullYear();

      if (sales) {
        let currentMonthTotal = 0;
        let prevMonthTotal = 0;
        let todaySalesCount = 0;

        // Usar uma chave sortable (YYYY-MM) para garantir ordem cronológica
        const monthsMap: Record<string, number> = {};
        const customerSpendMap: Record<string, { name: string, total: number }> = {};

        sales.forEach(sale => {
          const date = new Date(sale.created_at);
          const saleISO = date.toISOString().split('T')[0];
          const m = date.getMonth();
          const y = date.getFullYear();

          // Chave para ordenação: 2024-11, 2024-12, 2025-01...
          const sortKey = `${y}-${(m + 1).toString().padStart(2, '0')}`;
          monthsMap[sortKey] = (monthsMap[sortKey] || 0) + Number(sale.value);

          // Vendas do Dia
          if (saleISO === todayISO) {
            todaySalesCount++;
          }

          // Stats do mês atual e anterior
          if (m === currentMonth && y === currentYear) {
            currentMonthTotal += Number(sale.value);
            const customerName = sale.customer?.name || 'Cliente';
            if (!customerSpendMap[customerName]) customerSpendMap[customerName] = { name: customerName, total: 0 };
            customerSpendMap[customerName].total += Number(sale.value);
          } else if (m === (currentMonth === 0 ? 11 : currentMonth - 1) && y === (currentMonth === 0 ? currentYear - 1 : currentYear)) {
            prevMonthTotal += Number(sale.value);
          }
        });

        // Ordenar as chaves (YYYY-MM) e pegar as últimas 3
        const sortedMonths = Object.keys(monthsMap)
          .sort()
          .slice(-3)
          .map(key => {
            const [y, m] = key.split('-');
            const d = new Date(parseInt(y), parseInt(m) - 1, 1);
            return {
              month: d.toLocaleString('pt-BR', { month: 'short' }).replace('.', '') + '/' + y.slice(-2),
              total: monthsMap[key]
            };
          });

        setMonthlyData(sortedMonths);
        setStats({ 
          revenue: currentMonthTotal, 
          salesCount: todaySalesCount, 
          previousRevenue: prevMonthTotal 
        });

        const spender = Object.values(customerSpendMap).sort((a, b) => b.total - a.total)[0];
        setTopSpender(spender || null);
      }

      if (customers) {
        const upcoming = customers.filter(c => {
          if (!c.birthday) return false;
          const bday = new Date(c.birthday);
          const bdayThisYear = new Date(now.getFullYear(), bday.getMonth(), bday.getDate());
          if (bdayThisYear < now) bdayThisYear.setFullYear(now.getFullYear() + 1);
          const diffDays = Math.ceil((bdayThisYear.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
          return diffDays >= 0 && diffDays <= 15;
        }).slice(0, 3);
        setUpcomingBirthdays(upcoming);

        if (sales) {
          const inactive = customers.map(c => {
            const customerSales = sales
              .filter(s => s.customer_id === c.id)
              .sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
            if (customerSales.length === 0) return { name: c.name, days: 999 };
            const lastSale = new Date(customerSales[0].created_at);
            const diff = Math.floor((now.getTime() - lastSale.getTime()) / (1000 * 60 * 60 * 24));
            return { name: c.name, days: diff };
          }).filter(item => item.days >= 30).sort((a, b) => b.days - a.days).slice(0, 3);
          setInactiveCustomers(inactive);
        }
      }

      const { data: products } = await supabase.from('products').select('*').lt('stock', 3);
      if (products) setLowStock(products);
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  const growth = stats.previousRevenue > 0 ? ((stats.revenue - stats.previousRevenue) / stats.previousRevenue) * 100 : 0;

  if (loading) return <div className="p-10 animate-pulse text-center text-[10px] font-black uppercase tracking-widest text-gray-300">Sincronizando Boutique...</div>;

  return (
    <div className="space-y-6">
      {/* Revenue Card - FLUXO DA BOUTIQUE */}
      <div className="bg-gray-950 rounded-[2.5rem] p-7 text-white shadow-2xl relative overflow-hidden border border-white/5">
        <div className="absolute -right-10 -top-10 p-8 opacity-10 blur-2xl bg-purple-500 w-40 h-40 rounded-full"></div>
        <div className="absolute right-6 top-6 opacity-20">
          <Sparkles size={40} className="text-purple-300" />
        </div>

        <div className="relative z-10 space-y-6">
          <div className="flex justify-between items-center">
            <span className="text-[10px] font-black uppercase tracking-[0.3em] opacity-50">Fluxo da Boutique</span>
            <div className={`flex items-center gap-1 px-3 py-1 rounded-full text-[10px] font-black ${growth >= 0 ? 'bg-emerald-500/20 text-emerald-400' : 'bg-red-500/20 text-red-400'}`}>
              {growth >= 0 ? '+' : ''}{growth.toFixed(1)}% performance
            </div>
          </div>

          <div className="text-center">
            <p className="text-4xl font-black tracking-tighter mb-1">
              R$ {stats.revenue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
            </p>
            <p className="text-[9px] font-bold text-white/30 uppercase tracking-widest">Saldo Atual {new Date().toLocaleString('pt-BR', { month: 'long' })}</p>
          </div>

          <div className="h-px bg-white/10 w-full border-t border-dashed border-white/20"></div>

          {/* Meses Centralizados */}
          <div className="flex justify-center gap-8 items-center">
            {monthlyData.map((data, i) => (
              <div key={i} className="space-y-1 text-center">
                <p className="text-[8px] font-black text-white/30 uppercase tracking-widest">{data.month}</p>
                <p className="text-xs font-black">R$ {data.total > 1000 ? (data.total / 1000).toFixed(1) + 'k' : data.total.toFixed(0)}</p>
              </div>
            ))}
          </div>

          <button 
            onClick={() => onNavigate('financial')}
            className="w-full bg-white/5 hover:bg-white/10 border border-white/10 py-4 rounded-2xl flex items-center justify-center gap-2 transition-all group"
          >
            <span className="text-[10px] font-black uppercase tracking-widest">Análise Financeira Completa</span>
            <ArrowUpRight size={14} className="group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-transform" />
          </button>
        </div>
      </div>

      {/* Quadros de Vendas e Reposição Centralizados */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white border border-gray-100 rounded-[2rem] p-6 shadow-sm flex flex-col items-center justify-center text-center">
          <div className="bg-pink-50 w-14 h-14 rounded-2xl flex items-center justify-center mb-4">
            <Ribbon size={28} className="text-pink-400" />
          </div>
          <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Vendas do Dia</p>
          <p className="text-3xl font-black text-gray-900">{stats.salesCount}</p>
        </div>

        <div className="bg-white border border-gray-100 rounded-[2rem] p-6 shadow-sm flex flex-col items-center justify-center text-center">
          <div className="bg-purple-50 w-14 h-14 rounded-2xl flex items-center justify-center mb-4">
            <Flower size={28} className="text-purple-400" />
          </div>
          <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Reposição</p>
          <p className="text-3xl font-black text-red-600">{lowStock.length}</p>
        </div>
      </div>

      {/* Seção de Inteligência & CRM */}
      <div className="bg-white border border-gray-100 rounded-[2.5rem] overflow-hidden shadow-sm space-y-4 p-2">
        <div className="px-4 py-3 border-b border-gray-50 flex items-center gap-2">
           <TrendingUp size={16} className="text-indigo-400" />
           <h2 className="text-[11px] font-black text-gray-900 uppercase tracking-[0.2em]">Inteligência CRM</h2>
        </div>

        <div className="px-4 space-y-4 pb-4">
          {topSpender && (
            <div className="bg-indigo-50/50 p-4 rounded-3xl border border-indigo-100 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-indigo-500 rounded-2xl flex items-center justify-center text-white">
                  <Crown size={18} />
                </div>
                <div>
                  <p className="text-[9px] font-black text-indigo-400 uppercase tracking-widest">Estrela do Mês</p>
                  <p className="text-xs font-black text-gray-900 uppercase">{topSpender.name}</p>
                </div>
              </div>
              <p className="text-sm font-black text-indigo-600">R$ {topSpender.total.toFixed(0)}</p>
            </div>
          )}

          {upcomingBirthdays.length > 0 && (
            <div className="bg-pink-50/50 p-4 rounded-3xl border border-pink-100 space-y-3">
              <div className="flex items-center gap-2 text-pink-400">
                <Gift size={14} />
                <span className="text-[9px] font-black uppercase tracking-widest">Aniversariantes (Próx. 15 dias)</span>
              </div>
              <div className="space-y-2">
                {upcomingBirthdays.map(c => (
                  <div key={c.id} className="flex justify-between items-center">
                    <p className="text-[10px] font-bold text-gray-700 uppercase">{c.name}</p>
                    <p className="text-[8px] font-black text-pink-500 bg-white px-2 py-1 rounded-lg shadow-sm uppercase">
                      {c.birthday ? new Date(c.birthday).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }) : ''}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {inactiveCustomers.length > 0 && (
            <div className="bg-amber-50/50 p-4 rounded-3xl border border-amber-100 space-y-3">
              <div className="flex items-center gap-2 text-amber-500">
                <Clock size={14} />
                <span className="text-[9px] font-black uppercase tracking-widest">Recuperação (+30 dias)</span>
              </div>
              <div className="space-y-2">
                {inactiveCustomers.map((item, idx) => (
                  <div key={idx} className="flex justify-between items-center group cursor-pointer" onClick={() => onNavigate('customers')}>
                    <p className="text-[10px] font-bold text-gray-700 uppercase">{item.name}</p>
                    <p className="text-[8px] font-black text-amber-600 uppercase tracking-tighter">Há {item.days} dias</p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Alerta de Estoque - Reposição Urgente */}
      <div className="bg-white border border-gray-100 rounded-[2.5rem] overflow-hidden shadow-sm">
        <div className="px-6 py-5 border-b border-gray-50 flex justify-between items-center bg-gray-50/30">
          <h2 className="text-[11px] font-black text-gray-900 uppercase tracking-[0.2em] flex items-center gap-2">
            <AlertCircle size={14} className="text-amber-400" />
            Reposição Urgente
          </h2>
        </div>
